window.BANCO = window.BANCO || {};
window.BANCO['CIEN'] = window.BANCO['CIEN'] || {};
window.BANCO['CIEN']["6º Ano"] = [
  {"id": 1, "uid": "CIEN-6-001", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fenômenos Físicos e Químicos", "dificuldade": "Fácil", "enunciado": "Ao amassar uma folha de papel, modificamos seu formato e tamanho, mas ela continua sendo papel. Já ao queimar essa mesma folha, formam-se cinzas, fumaça e gases. Qual é a classificação correta dessas duas transformações, respectivamente?", "alternativas": {"A": "Transformação química e transformação física.", "B": "Transformação física e transformação química.", "C": "Ambas são transformações químicas.", "D": "Ambas são transformações físicas.", "E": "Transformação biológica e transformação física."}, "resposta_correta": "B", "justificativa": "Amassar o papel altera apenas sua forma geométrica (transformação física, sem formação de novas substâncias). Já a queima envolve reação de combustão, originando cinzas e gases (transformação química).", "possui_imagem": true},
  {"id": 2, "uid": "CIEN-6-002", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Evidências de Transformações Químicas", "dificuldade": "Fácil", "enunciado": "Quando misturamos vinagre com bicarbonato de sódio em um copo, observa-se imediatamente a formação intensa de bolhas e espuma. Essa efervescência indica:", "alternativas": {"A": "A evaporação da água presente no vinagre devido ao calor ambiente.", "B": "A liberação de um gás resultante de uma reação química entre as substâncias.", "C": "Que o bicarbonato apenas se dissolveu sem que houvesse reação.", "D": "Uma transformação física reversível de fusão do bicarbonato.", "E": "A condensação do ar atmosférico dentro do copo."}, "resposta_correta": "B", "justificativa": "A efervescência observada decorre da produção e liberação de gás carbônico (CO2), evidenciando a ocorrência de uma reação química entre o ácido acético do vinagre e o bicarbonato de sódio.", "possui_imagem": true},
  {"id": 3, "uid": "CIEN-6-003", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Evidências de Transformações Químicas", "dificuldade": "Fácil", "enunciado": "Uma maçã cortada deixada exposta ao ar começa a escurecer na região da polpa após alguns minutos. Essa mudança de cor é um indício de que ocorreu:", "alternativas": {"A": "Apenas a perda de água por desidratação física da fruta.", "B": "Uma transformação química provocada pelo contato de substâncias da maçã com o oxigênio do ar.", "C": "O congelamento das células superficiais da casca.", "D": "Uma transformação puramente física decorrente do corte da faca.", "E": "A proliferação instantânea de sementes na polpa."}, "resposta_correta": "B", "justificativa": "O escurecimento da maçã cortada é resultado da oxidação enzimática, na qual substâncias da fruta reagem com o oxigênio do ar, formando pigmentos escuros (novas substâncias).", "possui_imagem": true},
  {"id": 4, "uid": "CIEN-6-004", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reagentes e Produtos", "dificuldade": "Fácil", "enunciado": "Em uma transformação química, as substâncias presentes no início do processo e as novas substâncias formadas ao final são chamadas, respectivamente, de:", "alternativas": {"A": "Produtos e catalisadores.", "B": "Reagentes e produtos.", "C": "Solutos e solventes.", "D": "Misturas e elementos.", "E": "Produtos e reagentes."}, "resposta_correta": "B", "justificativa": "Por definição, as substâncias iniciais que sofrem a transformação são os 'reagentes', e as novas substâncias geradas após a reação são os 'produtos'.", "possui_imagem": false},
  {"id": 5, "uid": "CIEN-6-005", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fatores que Afetam a Velocidade das Reações", "dificuldade": "Fácil", "enunciado": "Guardamos alimentos perecíveis, como leite e carnes, dentro da geladeira principalmente porque a temperatura mais baixa:", "alternativas": {"A": "Destrói instantaneamente todas as bactérias presentes nos alimentos.", "B": "Diminui a velocidade das reações químicas de decomposição dos alimentos.", "C": "Impede completamente o contato do alimento com o ar e a luz.", "D": "Aumenta a umidade do ar, tornando os alimentos mais crocantes.", "E": "Acelera as reações químicas que tornam o alimento mais nutritivo."}, "resposta_correta": "B", "justificativa": "O resfriamento reduz a energia cinética das moléculas e diminui a atividade de microrganismos e enzimas, retardando as reações químicas que provocam a deterioração dos alimentos.", "possui_imagem": false},
  {"id": 6, "uid": "CIEN-6-006", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fatores que Afetam a Velocidade das Reações", "dificuldade": "Fácil", "enunciado": "Dois comprimidos efervescentes idênticos são colocados em copos com água à mesma temperatura: um deles está inteiro e o outro foi previamente triturado em pó. O comprimido triturado reage mais rápido porque:", "alternativas": {"A": "Apresenta maior massa total do que o comprimido inteiro.", "B": "Apresenta maior superfície de contato exposta à água.", "C": "Está em uma temperatura inicial mais elevada.", "D": "Perdeu suas substâncias químicas ao ser amassado.", "E": "Possui menor densidade e por isso afunda mais rápido."}, "resposta_correta": "B", "justificativa": "Ao triturar o comprimido, expõe-se uma área superficial muito maior ao contato com a água, aumentando a frequência de contato entre os reagentes e acelerando a reação.", "possui_imagem": true},
  {"id": 7, "uid": "CIEN-6-007", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações no Cotidiano: Combustão", "dificuldade": "Fácil", "enunciado": "Para que uma fogueira queime e se mantenha acesa, é necessária a presença simultânea de três elementos que compõem o triângulo do fogo: combustível (madeira), fonte de calor (faísca) e um comburente. O comburente mais comum na atmosfera é o:", "alternativas": {"A": "Gás nitrogênio.", "B": "Gás oxigênio.", "C": "Gás carbônico.", "D": "Gás hélio.", "E": "Vapor de água."}, "resposta_correta": "B", "justificativa": "O gás oxigênio (O2) atua como o comburente clássico, sendo indispensável para sustentar as reações de combustão ordinárias.", "possui_imagem": true},
  {"id": 8, "uid": "CIEN-6-008", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Transformações Físicas e Químicas", "dificuldade": "Fácil", "enunciado": "Assinale a alternativa que apresenta exclusivamente exemplos de transformações químicas:", "alternativas": {"A": "Gelo derretendo, água fervendo e rasgar um tecido.", "B": "Queima de uma vela, ferrugem em um prego e cozimento de um ovo.", "C": "Evaporação do álcool, dissolução de açúcar na água e quebra de um prato.", "D": "Solidificação da água, trituração de sal e corte de cabelo.", "E": "Fusão do ferro, evaporação de um perfume e modelagem de massinha."}, "resposta_correta": "B", "justificativa": "Queima da vela (combustão), ferrugem (oxidação) e cozimento do ovo (desnaturação e transformações químicas de proteínas) geram novas substâncias, caracterizando transformações químicas.", "possui_imagem": false},
  {"id": 9, "uid": "CIEN-6-009", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Transformações Reversíveis e Irreversíveis", "dificuldade": "Fácil", "enunciado": "O derretimento de uma barra de chocolate ao sol e sua posterior solidificação na geladeira constituem um processo:", "alternativas": {"A": "Químico e irreversível, pois o chocolate perde seu sabor.", "B": "Físico e reversível, pois as substâncias do chocolate continuam as mesmas após mudar de estado.", "C": "Químico e reversível, pois formou novas substâncias quando aqueceu.", "D": "Biológico, pois foi causado pela respiração de bactérias.", "E": "Físico e irreversível, pois não é possível recuperar a barra original."}, "resposta_correta": "B", "justificativa": "A fusão e a solidificação são mudanças de estado físico (fenômenos físicos) que podem ser revertidas com a variação de temperatura sem alterar a identidade química da matéria.", "possui_imagem": true},
  {"id": 10, "uid": "CIEN-6-010", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Evidências de Transformações Químicas", "dificuldade": "Fácil", "enunciado": "Durante a queima de fogos de artifício no Réveillon, podemos perceber luzes multicoloridas brilhantes e estrondos sonoros. Essas manifestações são evidências de:", "alternativas": {"A": "Transformações químicas que liberam grande quantidade de energia na forma de luz e calor.", "B": "Transformações puramente mecânicas sem alteração de substâncias.", "C": "Mudanças físicas de estado provocadas pela altitude.", "D": "Condensação de vapor d'água no ar frio da noite.", "E": "Simples reflexão da luz solar armazenada durante o dia."}, "resposta_correta": "A", "justificativa": "A queima da pólvora e dos sais metálicos nos fogos de artifício constitui reações químicas de combustão altamente exotérmicas que liberam luz (fótons característicos) e calor.", "possui_imagem": false},
  {"id": 11, "uid": "CIEN-6-011", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Transformações no Cotidiano", "dificuldade": "Fácil", "enunciado": "Quando uma esponja de palha de aço úmida é deixada sobre a pia, após alguns dias ela fica avermelhada, frágil e esfarela com facilidade. Esse processo é conhecido como:", "alternativas": {"A": "Evaporação.", "B": "Oxidação (enferrujamento).", "C": "Sublimação.", "D": "Fusão.", "E": "Destilação."}, "resposta_correta": "B", "justificativa": "O ferro presente na palha de aço reage com o oxigênio e a água (umidade), formando óxidos e hidróxidos de ferro (ferrugem), um clássico processo químico de oxidação.", "possui_imagem": true},
  {"id": 12, "uid": "CIEN-6-012", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações Biológicas no Cotidiano", "dificuldade": "Fácil", "enunciado": "Na fabricação de pães caseiros, utiliza-se o fermento biológico misturado à massa. A massa cresce antes de ir ao forno principalmente devido à:", "alternativas": {"A": "Evaporação instantânea da farinha de trigo.", "B": "Produção de gás carbônico durante a fermentação realizada pelas leveduras.", "C": "Absorção de nitrogênio atmosférico pelas proteínas da massa.", "D": "Transformação física provocada pelo repouso térmico.", "E": "Solidificação rápida da água misturada na receita."}, "resposta_correta": "B", "justificativa": "As leveduras do fermento consomem açúcares e realizam fermentação, liberando gás carbônico (CO2), cujas bolhas ficam retidas na rede de glúten, expandindo a massa.", "possui_imagem": true},
  {"id": 13, "uid": "CIEN-6-013", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações no Cotidiano: Fotossíntese", "dificuldade": "Fácil", "enunciado": "As plantas realizam uma transformação química essencial para a manutenção da vida no planeta Terra: a fotossíntese. Nesse processo, quais são os reagentes utilizados pelas plantas?", "alternativas": {"A": "Glicose e gás oxigênio.", "B": "Água e gás carbônico (na presença de luz solar).", "C": "Gás nitrogênio e solo fértil.", "D": "Monóxido de carbono e vapor de água.", "E": "Gás oxigênio e minerais."}, "resposta_correta": "B", "justificativa": "Na fotossíntese, as células vegetais utilizam água (H2O) absorvida pelas raízes e gás carbônico (CO2) captado pelas folhas, na presença de luz solar, para produzir glicose e oxigênio.", "possui_imagem": true},
  {"id": 14, "uid": "CIEN-6-014", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações no Cotidiano: Digestão", "dificuldade": "Fácil", "enunciado": "A digestão dos alimentos no corpo humano envolve transformações físicas e químicas. Um exemplo de transformação química na boca é a:", "alternativas": {"A": "Trituração mecânica dos alimentos realizada pelos dentes.", "B": "Ação das enzimas da saliva, que começam a quebrar o amido dos alimentos em açúcares menores.", "C": "Movimentação do bolo alimentar pela língua durante a deglutição.", "D": "Dissolução do alimento na água que bebemos.", "E": "Passagem do alimento através do esôfago."}, "resposta_correta": "B", "justificativa": "A amilase salivar (ptialina) é uma enzima que catalisa a quebra química do amido em moléculas menores (maltose), caracterizando uma transformação química.", "possui_imagem": false},
  {"id": 15, "uid": "CIEN-6-015", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Lei da Conservação da Massa", "dificuldade": "Fácil", "enunciado": "O químico francês Antoine Lavoisier ficou mundialmente famoso pela célebre frase: 'Na natureza nada se cria, nada se perde, tudo se transforma'. Essa lei científica estabelece que:", "alternativas": {"A": "Em uma reação química, a massa total dos produtos é sempre o dobro da massa dos reagentes.", "B": "Em um sistema fechado, a massa total antes da reação química é igual à massa total após a reação.", "C": "As substâncias podem desaparecer completamente se forem aquecidas.", "D": "A matéria é destruída quando ocorre a queima de um material.", "E": "A massa dos reagentes sempre diminui após qualquer transformação física."}, "resposta_correta": "B", "justificativa": "A Lei da Conservação da Massa (Lei de Lavoisier) dita que, em um recipiente fechado, a soma das massas dos reagentes é rigorosamente igual à soma das massas dos produtos formados.", "possui_imagem": true},
  {"id": 16, "uid": "CIEN-6-016", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Evidências de Transformações Químicas", "dificuldade": "Fácil", "enunciado": "Qual dos seguintes fenômenos NÃO apresenta evidência de uma reação química?", "alternativas": {"A": "Leite azedando e talhando após dias fora da refrigeração.", "B": "Derretimento de cubos de gelo colocados em um copo de suco.", "C": "Queima de uma folha de papel produzindo cinzas e fumaça.", "D": "Um fósforo riscado produzindo chama, calor e fumaça.", "E": "Formação de lodo e escurecimento em uma moeda antiga de cobre."}, "resposta_correta": "B", "justificativa": "O derretimento do gelo é apenas uma mudança de estado físico (fusão da água de sólido para líquido), mantendo inalterada a molécula de H2O.", "possui_imagem": false},
  {"id": 17, "uid": "CIEN-6-017", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fatores que Afetam a Velocidade das Reações", "dificuldade": "Fácil", "enunciado": "Ao preparar um chá, nota-se que o sachê libera a cor e o sabor muito mais rapidamente se a água estiver fervendo do que se a água estiver fria. Isso ocorre porque o aumento da temperatura:", "alternativas": {"A": "Aumenta a velocidade com que as substâncias se difundem e reagem.", "B": "Destrói as propriedades químicas das folhas do chá.", "C": "Diminui o contato entre a água e o sachê.", "D": "Transforma a água líquida em gelo microscópico.", "E": "Impede qualquer tipo de reação química no líquido."}, "resposta_correta": "A", "justificativa": "O aumento da temperatura eleva a energia cinética e a agitação das moléculas de água, acelerando a extração, dissolução e eventuais reações químicas dos componentes do chá.", "possui_imagem": false},
  {"id": 18, "uid": "CIEN-6-018", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fenômenos Físicos e Químicos", "dificuldade": "Fácil", "enunciado": "Qual das seguintes situações representa uma transformação química irreversível no dia a dia?", "alternativas": {"A": "Fritar ou cozinhar um ovo de galinha.", "B": "Congelar água para produzir gelo.", "C": "Dissolver um pouco de açúcar na água.", "D": "Derreter uma vela de cera sem acender o pavio.", "E": "Evaporar a água de uma panela."}, "resposta_correta": "A", "justificativa": "Ao fritar um ovo, o calor desnatura irreversivelmente as proteínas da clara e da gema e promove reações químicas que alteram permanentemente a cor, consistência e sabor.", "possui_imagem": false},
  {"id": 19, "uid": "CIEN-6-019", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Evidências de Reação Química", "dificuldade": "Fácil", "enunciado": "Ao misturar duas soluções aquosas incolores e límpidas em um tubo de ensaio de laboratório, surge instantaneamente um pó branco sólido que se deposita no fundo. O aparecimento desse sólido é denominado:", "alternativas": {"A": "Evaporação de reagente.", "B": "Formação de precipitado.", "C": "Fusão instantânea.", "D": "Sublimação do solvente.", "E": "Condensação de vapores."}, "resposta_correta": "B", "justificativa": "A formação de precipitado (substância sólida insolúvel originada pela reação entre duas substâncias dissolvidas) é uma das evidências clássicas de transformação química.", "possui_imagem": false},
  {"id": 20, "uid": "CIEN-6-020", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações no Cotidiano", "dificuldade": "Fácil", "enunciado": "Para acender uma churrasqueira com carvão, costuma-se abanar a brasa para que o fogo ganhe força. O ato de abanar contribui para avivar a chama porque:", "alternativas": {"A": "Aumenta a umidade sobre o carvão vegetal.", "B": "Fornece mais gás oxigênio (comburente) para reagir com o carvão.", "C": "Resfria o carvão, permitindo que ele queime sem gastar combustível.", "D": "Remove todo o oxigênio acumulado ao redor da brasa.", "E": "Diminui a superfície de contato do carvão."}, "resposta_correta": "B", "justificativa": "Abanar renova o ar ao redor das brasas, fornecendo oxigênio fresco (comburente), acelerando a reação de combustão do carbono do carvão.", "possui_imagem": false},
  {"id": 21, "uid": "CIEN-6-021", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Conceitos Fundamentais", "dificuldade": "Fácil", "enunciado": "Um aluno afirma que 'todas as transformações que liberam cheiro são reações químicas'. Essa afirmação está:", "alternativas": {"A": "Correta, pois apenas reações químicas produzem substâncias voláteis.", "B": "Incorreta, pois a evaporação de um perfume espalha aroma pelo ar sendo apenas um fenômeno físico.", "C": "Correta, pois a evaporação sempre altera a fórmula das substâncias.", "D": "Incorreta, pois nenhuma reação química produz alteração de odor.", "E": "Correta, pois o olfato humano só detecta reações de combustão."}, "resposta_correta": "B", "justificativa": "A evaporação de um perfume ou de álcool espalha moléculas voláteis no ar sem alterar sua composição química; é uma transformação física que permite sentir odor sem haver reação química.", "possui_imagem": false},
  {"id": 22, "uid": "CIEN-6-022", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Velocidade das Reações: Temperatura", "dificuldade": "Médio", "enunciado": "Em um experimento em sala de aula, foram cronometrados os tempos de dissolução/reação de dois comprimidos efervescentes idênticos em 100 mL de água:\n- Copo 1: água a 10 ºC (tempo = 95 segundos)\n- Copo 2: água a 50 ºC (tempo = 25 segundos)\nQual é a explicação científica para a diferença no tempo observado?", "alternativas": {"A": "No Copo 1, o comprimido perdeu massa devido à baixa temperatura.", "B": "No Copo 2, a maior energia térmica aumentou a frequência e a energia das colisões entre as moléculas de água e o comprimido.", "C": "No Copo 2, a água ferveu e destruiu quimicamente o ácido cítrico do comprimido antes de ele reagir.", "D": "No Copo 1, o oxigênio da atmosfera impediu a dissolução do bicarbonato.", "E": "A temperatura não interfere na velocidade das reações químicas; a diferença foi um erro de medição."}, "resposta_correta": "B", "justificativa": "Em temperaturas mais altas, a energia cinética média das partículas é maior, fazendo com que as moléculas colidam com mais frequência e maior energia, acelerando a reação química.", "possui_imagem": true},
  {"id": 23, "uid": "CIEN-6-023", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Superfície de Contato", "dificuldade": "Médio", "enunciado": "Para iniciar o fogo em uma lareira, é muito mais eficiente utilizar pequenos gravetos ou lascas finas de madeira do que tentar queimar diretamente uma tora grossa e pesada. Isso ocorre porque:", "alternativas": {"A": "A tora grossa de madeira não é inflamável nem contém carbono.", "B": "Gravetos e lascas possuem maior área superficial total exposta ao oxigênio e ao calor, facilitando a combustão.", "C": "A tora grossa possui uma densidade de oxigênio superior à dos gravetos.", "D": "Os gravetos finos queimam sem a necessidade de gás oxigênio como comburente.", "E": "A madeira em pedaços pequenos atua como catalisador da queima."}, "resposta_correta": "B", "justificativa": "Ao dividir a madeira em lascas finas, a superfície de contato em contato com o ar e com a chama aumenta drasticamente, propiciando que mais moléculas de celulose reajam simultaneamente com o oxigênio.", "possui_imagem": false},
  {"id": 24, "uid": "CIEN-6-024", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Lei de Lavoisier: Sistema Aberto vs. Fechado", "dificuldade": "Médio", "enunciado": "Um pedaço de papel de 10 gramas é queimado sobre o prato de uma balança aberta. Ao final da combustão, a balança registra apenas 1,5 grama de cinzas. Um estudante conclui que 'a matéria foi destruída'. Por que essa conclusão está incorreta segundo a Lei de Lavoisier?", "alternativas": {"A": "Porque as cinzas pesam menos por terem perdido elétrons para o prato da balança.", "B": "Porque a queima liberou gases (como CO2 e vapor de água) e fumaça que escaparam para a atmosfera no sistema aberto.", "C": "Porque a balança perdeu a calibração com o calor do fogo.", "D": "Porque o papel é composto apenas por ar comprimido que retornou à atmosfera.", "E": "Porque as cinzas possuem energia negativa que anula parte do peso."}, "resposta_correta": "B", "justificativa": "A matéria não foi destruída. Em um sistema aberto, os produtos gasosos da combustão (principalmente dióxido de carbono e vapor d'água) dispersam-se no ar. Se o recipiente fosse hermeticamente fechado, a massa total final seria igual à inicial (10 g de papel + massa de oxigênio consumido).", "possui_imagem": false},
  {"id": 25, "uid": "CIEN-6-025", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Lei de Lavoisier: Queima da Palha de Aço", "dificuldade": "Médio", "enunciado": "Ao queimar uma porção de palha de aço sobre uma balança digital em um prato aberto, observa-se surpreendentemente que a massa indicada na balança AUMENTA após a queima. Qual é a justificativa correta para esse fenômeno?", "alternativas": {"A": "O calor gerado pelo fogo atrai gravidade adicional para o prato da balança.", "B": "O ferro da palha de aço reagiu e combinou-se quimicamente com o oxigênio do ar, formando óxido de ferro, cuja massa inclui os átomos de oxigênio incorporados.", "C": "A palha de aço absorveu nitrogênio e água líquida do ambiente durante a incandescência.", "D": "A queima provocou a criação espontânea de novos átomos de ferro na estrutura.", "E": "A balança sofreu interferência magnética causada pela luz da combustão."}, "resposta_correta": "B", "justificativa": "Na combustão da palha de aço (Fe), ocorre a reação com o oxigênio gasoso (O2) do ar atmosférico, formando óxido de ferro (Fe2O3/Fe3O4). Como o oxigênio que estava no ar se incorporou ao sólido no prato da balança, a massa do produto sólido é maior que a do reagente ferro inicial.", "possui_imagem": false},
  {"id": 26, "uid": "CIEN-6-026", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Lei de Lavoisier: Cálculo de Massa", "dificuldade": "Médio", "enunciado": "Em um recipiente fechado e vedado, 12 gramas de carbono reagem completamente com 32 gramas de gás oxigênio, produzindo exclusivamente gás carbônico (dióxido de carbono). De acordo com a Lei da Conservação da Massa, qual será a massa de gás carbônico obtida?", "alternativas": {"A": "20 gramas.", "B": "24 gramas.", "C": "44 gramas.", "D": "48 gramas.", "E": "384 gramas."}, "resposta_correta": "C", "justificativa": "Pela Lei de Lavoisier, massa dos reagentes = massa dos produtos. Portanto: Massa do carbono (12 g) + Massa do oxigênio (32 g) = 44 g de gás carbônico.", "possui_imagem": true},
  {"id": 27, "uid": "CIEN-6-027", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Catalisadores e Velocidade", "dificuldade": "Médio", "enunciado": "A água oxigenada (peróxido de hidrogênio) líquida se decompõe lentamente em água e gás oxigênio com o passar do tempo. Se adicionarmos uma pequena quantidade de dióxido de manganês ou um pedaço de fígado cru a essa solução, nota-se uma efervescência vigorosa imediata, mas a substância adicionada permanece quimicamente inalterada ao final. Essa substância atuou como um:", "alternativas": {"A": "Comburente da combustão.", "B": "Catalisador da reação química.", "C": "Reagente que foi totalmente consumido.", "D": "Solvente apolar.", "E": "Indicador de pH."}, "resposta_correta": "B", "justificativa": "Um catalisador (ou enzima, no caso da catalase do fígado) acelera a velocidade de uma reação química sem ser consumido ou alterado permanentemente no processo.", "possui_imagem": false},
  {"id": 28, "uid": "CIEN-6-028", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações no Organismo: Digestão Enzimática", "dificuldade": "Médio", "enunciado": "Durante o almoço, um estudante mastiga pacientemente um pedaço de pão francês por quase dois minutos antes de engolir. Ele nota que o pão começou a apresentar um leve sabor adocicado na boca. Isso acontece porque:", "alternativas": {"A": "As bactérias da boca produziram açúcar a partir da água ingerida.", "B": "A amilase presente na saliva quebrou o amido (que não tem gosto doce) em açúcares menores, como a maltose.", "C": "O pão continha açúcar cristal oculto que só se dissolveu com o calor da língua.", "D": "A mastigação transformou o pão em gordura adocicada.", "E": "O esmalte dentário liberou substâncias doces durante o atrito mecânico."}, "resposta_correta": "B", "justificativa": "A amilase salivar catalisa a hidrólise do amido em dissacarídeos e monossacarídeos, que possuem sabor doce característico percebido pelas papilas gustativas.", "possui_imagem": false},
  {"id": 29, "uid": "CIEN-6-029", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Oxidação e Prevenção", "dificuldade": "Médio", "enunciado": "Para evitar que fatias de maçã ou abacate escureçam ao serem preparadas para um lanche escolar, uma prática comum é pingar algumas gotas de suco de limão fresco sobre elas. A função do suco de limão nesse caso é:", "alternativas": {"A": "Acelerar a fermentação das fibras da fruta.", "B": "Atuar como antioxidante devido à vitamina C e à acidez, retardando as reações de oxidação enzimática.", "C": "Aumentar a temperatura da polpa da fruta para cozinhar a casca.", "D": "Remover todas as vitaminas da fruta para mantê-la clara.", "E": "Fazer a água da fruta evaporar mais rapidamente."}, "resposta_correta": "B", "justificativa": "O suco de limão contém ácido cítrico e ácido ascórbico (vitamina C), que é um antioxidante natural. O meio ácido inibe a ação das enzimas polifenoloxidases e o ácido ascórbico consome o oxigênio, impedindo o escurecimento.", "possui_imagem": false},
  {"id": 30, "uid": "CIEN-6-030", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Concentração dos Reagentes", "dificuldade": "Médio", "enunciado": "Em uma aula prática, um grupo de alunos adiciona vinagre comum (cerca de 4% de ácido acético) a um balão com bicarbonato. Outro grupo adiciona vinagre concentrado (10% de ácido acético) à mesma massa de bicarbonato. O segundo grupo observa uma reação muito mais rápida e vigorosa. Isso demonstra que:", "alternativas": {"A": "A maior concentração de reagente aumenta a quantidade de partículas por volume, elevando a frequência de colisões efetivas.", "B": "A concentração de uma substância não interfere na velocidade de sua transformação.", "C": "A água pura do primeiro vinagre consumiu o bicarbonato antes do ácido.", "D": "O vinagre concentrado possui menor densidade e por isso ferveu instantaneamente.", "E": "A reação só ocorre quando o ácido está em concentração máxima absoluta."}, "resposta_correta": "A", "justificativa": "Quanto maior a concentração dos reagentes em solução, maior é o número de partículas reagentes por unidade de volume, o que eleva a probabilidade de choques mecânicos efetivos entre elas, aumentando a velocidade da reação.", "possui_imagem": false},
  {"id": 31, "uid": "CIEN-6-031", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Indicadores Ácido-Base Naturais", "dificuldade": "Médio", "enunciado": "O extrato aquoso de folhas de repolho roxo possui uma coloração roxa natural. Ao adicionar algumas gotas desse extrato ao vinagre, a mistura torna-se vermelha/rosa. Ao adicionar ao sabão em pó dissolvido em água, torna-se verde/amarela. Essas mudanças de cor evidenciam:", "alternativas": {"A": "Que o repolho roxo apenas diluiu as soluções sem nenhuma interação química.", "B": "Reações químicas entre as antocianinas do repolho e as substâncias ácidas ou básicas das amostras, alterando sua estrutura molecular.", "C": "Que houve a evaporação instantânea de água em ambos os recipientes.", "D": "Uma transformação física de fusão das moléculas de água.", "E": "A decomposição radioativa dos produtos de limpeza."}, "resposta_correta": "B", "justificativa": "As antocianinas presentes no repolho roxo sofrem alterações estruturais reversíveis dependendo do pH do meio (ácido ou básico), gerando novas espécies químicas com cores características.", "possui_imagem": false},
  {"id": 32, "uid": "CIEN-6-032", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Transformações no Cotidiano: Ferrugem", "dificuldade": "Médio", "enunciado": "Três pregos de ferro idênticos foram colocados em tubos de ensaio fechados sob diferentes condições por duas semanas:\n- Tubo 1: prego com água e ar atmosférico.\n- Tubo 2: prego apenas com ar seco (com sílica em gel para retirar a umidade).\n- Tubo 3: prego imerso em água fervida coberta com uma camada de óleo vegetal (sem contato com oxigênio).\nEm qual(is) tubo(s) será observada a formação evidente de ferrugem?", "alternativas": {"A": "Apenas no Tubo 2.", "B": "Apenas no Tubo 3.", "C": "Apenas no Tubo 1.", "D": "Nos Tubos 1, 2 e 3 igualmente.", "E": "Nos Tubos 2 e 3 apenas."}, "resposta_correta": "C", "justificativa": "A oxidação do ferro para formar ferrugem requer a presença conjunta de oxigênio (ar) e água (umidade). No tubo 2 faltou água; no tubo 3 faltou oxigênio dissolvido. Portanto, a ferrugem só se forma no Tubo 1.", "possui_imagem": false},
  {"id": 33, "uid": "CIEN-6-033", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Respiração Celular vs. Fotossíntese", "dificuldade": "Médio", "enunciado": "Enquanto a fotossíntese absorve energia luminosa para converter água e gás carbônico em glicose e oxigênio, a respiração celular que ocorre em nossas células faz o caminho oposto: consome glicose e oxigênio para:", "alternativas": {"A": "Produzir água, gás carbônico e liberar energia utilizável pelo organismo.", "B": "Produzir exclusivamente gás nitrogênio e armazenar luz solar.", "C": "Criar novos átomos de hidrogênio e queimar gorduras sem produzir resíduos.", "D": "Transformar água líquida em vapor sem liberação de energia.", "E": "Neutralizar o oxigênio para que o sangue não enferruje."}, "resposta_correta": "A", "justificativa": "A respiração celular é uma reação química metabólica vital na qual nutrientes (como glicose) reagem com gás oxigênio, produzindo gás carbônico, água e energia química (ATP).", "possui_imagem": false},
  {"id": 34, "uid": "CIEN-6-034", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Chuva Ácida e Degradação de Monumentos", "dificuldade": "Médio", "enunciado": "Estátuas históricas feitas de mármore (constituído principalmente por carbonato de cálcio) sofrem desgaste acelerado em cidades com altos índices de poluição atmosférica devido à chamada 'chuva ácida'. Essa degradação é explicada quimicamente porque:", "alternativas": {"A": "A água pura da chuva dissolve o mármore por ser um excelente solvente físico.", "B": "Os ácidos presentes na chuva (como ácido sulfúrico e nítrico) reagem quimicamente com o carbonato de cálcio, corroendo a pedra e liberando gás carbônico.", "C": "O vento das tempestades lixa a superfície da estátua por atrito mecânico puro.", "D": "A chuva ácida congela o mármore e quebra as moléculas de cálcio por choque térmico.", "E": "A fuligem cria uma camada protetora que impede o mármore de respirar."}, "resposta_correta": "B", "justificativa": "A reação entre ácidos dissolvidos na água da chuva e o carbonato de cálcio (CaCO3) produz sais solúveis de cálcio, água e CO2 gasoso, desintegrando progressivamente o relevo das esculturas.", "possui_imagem": false},
  {"id": 35, "uid": "CIEN-6-035", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Combustão Completa e Incompleta", "dificuldade": "Médio", "enunciado": "Ao acender uma chama de fogão a gás bem regulada, observa-se uma chama azulada e limpa. Quando a entrada de ar do queimador está parcialmente obstruída, a chama torna-se amarelada e o fundo da panela fica coberto por uma fuligem preta. Essa fuligem é formada porque:", "alternativas": {"A": "O excesso de oxigênio queima o metal da panela.", "B": "A falta de oxigênio suficiente provoca combustão incompleta do gás, liberando partículas sólidas de carbono (fuligem).", "C": "A água do cozimento vazou e tingiu o queimador de preto.", "D": "O gás de cozinha se transformou em petróleo sólido por resfriamento da chama.", "E": "Ocorreu uma transformação física de solidificação do gás carbônico."}, "resposta_correta": "B", "justificativa": "Com suprimento inadequado de oxigênio (comburente), a combustão do gás hidrocarboneto é incompleta, gerando monóxido de carbono (CO) e fuligem (carbono elementar em partículas sólidas finas).", "possui_imagem": true},
  {"id": 36, "uid": "CIEN-6-036", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Métodos de Proteção contra a Corrosão", "dificuldade": "Médio", "enunciado": "Portões de ferro e cascos de navios costumam ser pintados com tintas especiais ou revestidos com camadas de outros metais (como o zinco, processo chamado galvanização). O objetivo principal dessas medidas é:", "alternativas": {"A": "Melhorar a condução de eletricidade pelo metal.", "B": "Criar uma barreira física que impeça o contato direto do ferro com o oxigênio e a umidade do ar, prevenindo a oxidação.", "C": "Aumentar o peso da estrutura para que ela não seja levada pelo vento.", "D": "Tornar o ferro um material biodegradável no meio ambiente.", "E": "Transformar o ferro quimicamente em aço inoxidável instantaneamente."}, "resposta_correta": "B", "justificativa": "A pintura ou a galvanização cria uma camada protetora isolante sobre o metal, bloqueando a penetração de oxigênio atmosférico e água, essenciais para a reação de enferrujamento.", "possui_imagem": false},
  {"id": 37, "uid": "CIEN-6-037", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reversibilidade das Transformações", "dificuldade": "Médio", "enunciado": "Considere as seguintes afirmações sobre a reversibilidade das transformações da matéria:\nI. A quebra de um copo de vidro é uma transformação química irreversível.\nII. A evaporação da água de uma poça é uma transformação física reversível por condensação.\nIII. A queima de um palito de fósforo é uma transformação química irreversível.\nEstá(ão) correta(s) apenas:", "alternativas": {"A": "I.", "B": "II.", "C": "I e II.", "D": "II e III.", "E": "I, II e III."}, "resposta_correta": "D", "justificativa": "A afirmação I está incorreta: quebrar o copo é uma transformação física (embora difícil de colar de volta, a substância vidro permanece vidro). As afirmações II e III estão plenamente corretas.", "possui_imagem": false},
  {"id": 38, "uid": "CIEN-6-038", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Fermentação Alcoólica e Panificação", "dificuldade": "Médio", "enunciado": "Durante o preparo do pão, as leveduras do fermento biológico consomem glicose e produzem gás carbônico e álcool etílico. No entanto, ao comer o pão assado, ele não possui teor alcoólico. Isso ocorre porque:", "alternativas": {"A": "O álcool foi absorvido e destruído pela farinha de trigo.", "B": "Durante o forneamento em alta temperatura, o álcool etílico (que possui baixo ponto de ebulição) evapora completamente.", "C": "As leveduras consomem o próprio álcool antes de o pão entrar no forno.", "D": "O sal adicionado na massa reage com o álcool e o transforma em água e sal.", "E": "O álcool se transforma em açúcar doce durante o cozimento."}, "resposta_correta": "B", "justificativa": "O álcool etílico gerado na fermentação tem ponto de ebulição de aproximadamente 78 ºC. No forno (a cerca de 180 ºC a 200 ºC), ele evapora facilmente junto com parte da água, restando apenas a massa assada e arejada.", "possui_imagem": false},
  {"id": 39, "uid": "CIEN-6-039", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações Endotérmicas e Exotérmicas", "dificuldade": "Médio", "enunciado": "Bolsas térmicas instantâneas utilizadas por atletas para tratar lesões funcionam ao romper uma cápsula interna que mistura substâncias químicas. Algumas bolsas ficam intensamente frias ao serem ativadas, enquanto outras esquentam. A bolsa que resfria funciona porque ocorre uma reação química que:", "alternativas": {"A": "Libera calor para as mãos do atleta.", "B": "Absorve calor do meio ambiente ao redor para que a reação ocorra.", "C": "Congela a água atmosférica transformando-a em gelo seco.", "D": "Destrói a energia térmica existente dentro dos reagentes.", "E": "Libera gás nitrogênio líquido sob alta pressão."}, "resposta_correta": "B", "justificativa": "Reações endotérmicas absorvem calor do ambiente vizinho para ocorrer. Ao retirar calor do ambiente (e da pele do atleta em contato com a bolsa), a temperatura local cai sensivelmente.", "possui_imagem": false},
  {"id": 40, "uid": "CIEN-6-040", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Diferença entre Dissolução e Reação Química", "dificuldade": "Médio", "enunciado": "Ao colocar cloreto de sódio (sal de cozinha) em água, a água continua transparente e, se a deixarmos evaporar completamente sob o sol, o sal reaparece intacto no fundo do prato. Já ao colocar um comprimido efervescente em água e evaporar o líquido, o pó obtido não efervesce mais com água. Isso comprova que:", "alternativas": {"A": "A dissolução do sal é uma transformação química e a do comprimido é física.", "B": "A dissolução do sal é uma transformação física e a do comprimido efervescente é uma transformação química que originou novas substâncias.", "C": "Em ambos os casos ocorreram apenas transformações físicas reversíveis.", "D": "O comprimido efervescente apenas evaporou sem deixar resíduos.", "E": "O sal de cozinha sofreu combustão espontânea na água."}, "resposta_correta": "B", "justificativa": "A dissolução do sal é um fenômeno físico reversível (separação e solvatação de íons sem reação química). O comprimido efervescente contém ácido e bicarbonato que reagem quimicamente ao entrar em contato com a água, formando novas substâncias (incluindo CO2 que escapa).", "possui_imagem": false},
  {"id": 41, "uid": "CIEN-6-041", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Digestão Mecânica e Química", "dificuldade": "Médio", "enunciado": "A mastigação dos alimentos pelos dentes e a ação dos movimentos peristálticos do estômago são essenciais para que os sucos digestivos ajam com eficiência. A relação entre a mastigação e a digestão química pelas enzimas se baseia em qual fator cinético?", "alternativas": {"A": "Aumento da temperatura corporal durante a mastigação.", "B": "Aumento da superfície de contato dos pedaços de alimento exposta às enzimas digestivas.", "C": "Aumento da concentração de ácido clorídrico na saliva.", "D": "Redução da quantidade de água necessária para a digestão.", "E": "Transformação dos carboidratos em proteínas na cavidade bucal."}, "resposta_correta": "B", "justificativa": "Triturar o alimento em fragmentos minúsculos aumenta exponencialmente a área de contato total do bolo alimentar, permitindo que as enzimas digestivas (catalisadores biológicos) atuem com muito mais rapidez e eficácia.", "possui_imagem": false},
  {"id": 42, "uid": "CIEN-6-042", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Análise de Tabela Experimental", "dificuldade": "Médio", "enunciado": "Considere a tabela a seguir, que registra o tempo para dissolver 5 g de açúcar em 100 mL de água sob diferentes condições:\n- Condição 1: Açúcar em torrão + água fria + sem agitar (180 s)\n- Condição 2: Açúcar em pó + água fria + sem agitar (70 s)\n- Condição 3: Açúcar em pó + água quente + sem agitar (25 s)\n- Condição 4: Açúcar em pó + água quente + com agitação (8 s)\nCom base nesses dados, a condição mais rápida (4) combinou:", "alternativas": {"A": "Menor temperatura, menor superfície de contato e repouso mecânico.", "B": "Maior superfície de contato, maior temperatura e facilitação do transporte por agitação mecânica.", "C": "Maior massa de açúcar e menor volume de solvente.", "D": "Ausência de colisões entre as moléculas do soluto e do solvente.", "E": "Transformação química de queima do açúcar na água quente."}, "resposta_correta": "B", "justificativa": "A condição 4 combinou os três fatores otimizados: açúcar em pó (maior superfície de contato), água aquecida (maior energia cinética das moléculas) e agitação (renovação do contato entre soluto e solvente).", "possui_imagem": false},
  {"id": 43, "uid": "CIEN-6-043", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Conservação de Massas em Sistemas Abertos e Fechados", "dificuldade": "Difícil", "enunciado": "Um químico monta um dispositivo composto por um erlenmeyer contendo 50 g de vinagre e um balão de borracha acoplado à boca do frasco contendo 5 g de bicarbonato de sódio. A massa total do conjunto fechado na balança é de 155 g. Ao virar o balão, o bicarbonato cai no vinagre, ocorre efervescência e o balão infla. Em seguida, o balão é perfurado com uma agulha. O que acontece com a massa indicada na balança antes e depois de furar o balão?", "alternativas": {"A": "Antes de furar, a massa cai para 100 g; após furar, permanece em 100 g.", "B": "Antes de furar, a massa permanece rigorosamente em 155 g; após furar, a massa diminui, pois o gás carbônico gerado escapa para a atmosfera.", "C": "Antes de furar, a massa sobe para 200 g devido à pressão interna; após furar, volta para 155 g.", "D": "A massa não se altera em nenhum momento, pois os gases não possuem peso.", "E": "Antes de furar, a massa diminui para 150 g devido ao consumo de vinagre; após furar, a massa aumenta."}, "resposta_correta": "B", "justificativa": "Enquanto o sistema estava fechado pelo balão, nenhum átomo escapou, mantendo a massa total constante em 155 g (Lei de Lavoisier). Ao perfurar o balão, o gás carbônico (CO2) produzido na reação escapa para o ambiente aberto, fazendo a balança registrar uma massa final menor.", "possui_imagem": false},
  {"id": 44, "uid": "CIEN-6-044", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Teoria das Colisões Moleculares", "dificuldade": "Difícil", "enunciado": "De acordo com a teoria das colisões da química, para que duas moléculas reajam e se transformem em novos produtos, é necessário que elas colidam com orientação adequada e com energia suficiente (energia de ativação). Por que um aumento de apenas 10 ºC na temperatura pode duplicar a velocidade de muitas reações?", "alternativas": {"A": "Porque o calor cria novas moléculas reagentes que não existiam no início.", "B": "Porque aumenta a fração de moléculas que possuem energia cinética igual ou superior à energia necessária para que a colisão seja efetiva.", "C": "Porque o calor destrói o solvente, deixando os reagentes sem espaço para se moverem.", "D": "Porque os elétrons das moléculas congelam e facilitam a atração nuclear.", "E": "Porque a gravidade diminui na presença de temperaturas mais elevadas."}, "resposta_correta": "B", "justificativa": "O aumento da temperatura não apenas aumenta o número total de colisões por segundo, mas, fundamentalmente, aumenta de forma muito expressiva a proporção de moléculas com energia cinética suficiente para ultrapassar a barreira da energia de ativação.", "possui_imagem": false},
  {"id": 45, "uid": "CIEN-6-045", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Balanço Quantitativo de Lavoisier", "dificuldade": "Difícil", "enunciado": "Considere a reação descrita pela equação em palavras: Gás Hidrogênio + Gás Oxigênio -> Água líquida. Em um recipiente hermeticamente fechado, 4 gramas de gás hidrogênio reagiram totalmente com certa massa de gás oxigênio, produzindo exatamente 36 gramas de água líquida, sem sobrar nenhum reagente. Qual era a massa de gás oxigênio utilizada?", "alternativas": {"A": "9 gramas.", "B": "18 gramas.", "C": "32 gramas.", "D": "40 gramas.", "E": "144 gramas."}, "resposta_correta": "C", "justificativa": "Pela Lei da Conservação das Massas de Lavoisier: Massa dos Reagentes = Massa dos Produtos. Portanto: Massa do Hidrogênio (4 g) + Massa do Oxigênio (x) = 36 g de água -> x = 36 - 4 = 32 gramas de oxigênio.", "possui_imagem": false},
  {"id": 46, "uid": "CIEN-6-046", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Análise de Métodos de Extinção de Chamas", "dificuldade": "Difícil", "enunciado": "Para combater princípios de incêndio provocados por curto-circuito em equipamentos elétricos energizados, é proibido o uso de extintores de água, recomendando-se o uso de extintores de gás carbônico (CO2). Esse tipo de extintor atua na extinção da chama principalmente por:", "alternativas": {"A": "Aumentar a temperatura do fogo até consumir o combustível em milissegundos.", "B": "Abafamento, pois o CO2 é mais denso que o ar e desloca o gás oxigênio (comburente), interrompendo a reação de combustão.", "C": "Umedecer o circuito elétrico sem conduzir corrente elétrica.", "D": "Fornecer mais comburente para que o fogo queime mais rápido e termine logo.", "E": "Reagir quimicamente com os fios de cobre para formar uma liga metálica à prova de chamas."}, "resposta_correta": "B", "justificativa": "O dióxido de carbono pressurizado é mais denso que o oxigênio e atua expulsando e cobrindo o oxigênio do ar próximo ao material em chamas (método do abafamento), quebrando o triângulo do fogo sem conduzir corrente elétrica.", "possui_imagem": true},
  {"id": 47, "uid": "CIEN-6-047", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Catalisadores Automotivos", "dificuldade": "Difícil", "enunciado": "Os veículos automotores modernos possuem no sistema de escapamento uma peça chamada 'conversor catalítico' (catalisador), que contém metais nobres como platina e paládio. A função desse dispositivo é:", "alternativas": {"A": "Consumir todo o combustível que sobrou no tanque antes que ele evapore.", "B": "Acelerar reações químicas que transformam gases altamente poluentes e tóxicos (como monóxido de carbono e óxidos de nitrogênio) em substâncias menos nocivas (como gás carbônico, água e gás nitrogênio).", "C": "Aumentar a potência do motor ao queimar o oxigênio que sai do escapamento.", "D": "Resfriar os gases de escape para transformá-los em pedras sólidas que caem na pista.", "E": "Produzir combustível fóssil renovável a partir da fumaça do escapamento."}, "resposta_correta": "B", "justificativa": "O catalisador automotivo facilita e acelera a conversão química de gases tóxicos gerados na combustão do motor (CO, hidrocarbonetos não queimados e NOx) em gases atóxicos ou menos nocivos (CO2, H2O e N2).", "possui_imagem": false},
  {"id": 48, "uid": "CIEN-6-048", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Conservação e Decomposição de Alimentos", "dificuldade": "Difícil", "enunciado": "Além da refrigeração, a humanidade desenvolveu técnicas tradicionais de conservação de alimentos como a salga da carne (carne-seca/charque) e a fabricação de compotas de frutas com calda de açúcar concentrada. O princípio biológico e físico-químico comum que explica por que esses métodos impedem a decomposição rápida é:", "alternativas": {"A": "O sal e o açúcar cozinham quimicamente os alimentos em alta temperatura.", "B": "O excesso de soluto cria um meio hipertônico que retira água das células dos microrganismos decompositores por osmose, impedindo suas funções vitais e reações metabólicas.", "C": "O sal destrói o oxigênio atmosférico ao redor do pote de alimento.", "D": "O açúcar transforma todas as bactérias em leveduras benéficas para o consumo.", "E": "A carne salgada e a compota tornam-se materiais inorgânicos imunes a reações químicas."}, "resposta_correta": "B", "justificativa": "Ao elevar muito a concentração de sal ou açúcar, a água livre no alimento diminui drasticamente e a pressão osmótica desidrata microrganismos (bactérias e fungos), inibindo as reações químicas vitais e enzimáticas que causam a putrefação.", "possui_imagem": false},
  {"id": 49, "uid": "CIEN-6-049", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações Fotoquímicas no Cotidiano", "dificuldade": "Difícil", "enunciado": "O peróxido de hidrogênio comercial (água oxigenada) é vendido obrigatoriamente em frascos plásticos opacos e escuros, e não em garrafas de vidro totalmente transparentes. Isso se deve ao fato de que a luz:", "alternativas": {"A": "Solidifica a água oxigenada, tornando-a perigosa para uso tópico.", "B": "Fornece energia que acelera a reação fotoquímica de decomposição do peróxido de hidrogênio em água líquida e oxigênio gasoso.", "C": "Neutraliza o oxigênio dissolvido, transformando o líquido em ácido clorídrico.", "D": "Faz a garrafa de vidro encolher e vazar o produto.", "E": "Impede que a água oxigenada reaja com ferimentos na pele humana."}, "resposta_correta": "B", "justificativa": "A molécula de peróxido de hidrogênio (H2O2) é sensível à radiação luminosa (fotólise). A energia dos fótons de luz catalisa sua decomposição em água e oxigênio gasoso; frascos opacos bloqueiam a passagem de luz, garantindo a estabilidade do produto.", "possui_imagem": false},
  {"id": 50, "uid": "CIEN-6-050", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Combustão e Experimento da Vela sob Campânula", "dificuldade": "Difícil", "enunciado": "Um clássico experimento de ciências consiste em fixar uma vela acesa em um prato com água colorida e cobri-la com um copo de vidro invertido. Após alguns segundos, a chama da vela diminui até se apagar completamente e o nível da água sobe dentro do copo. A explicação rigorosa para a subida da água envolve:", "alternativas": {"A": "Apenas a transformação do oxigênio em ouro sólido na borda do copo.", "B": "O consumo de parte do gás oxigênio na combustão associado principalmente ao resfriamento e contração dos gases aquecidos dentro do copo quando a chama se apaga, gerando uma redução de pressão interna.", "C": "A criação de um vácuo absoluto de 100% dentro do copo assim que a vela se acende.", "D": "A atração gravitacional magnética exercida pela cera derretida sobre as moléculas de água.", "E": "A água subindo para fornecer hidrogênio líquido como novo combustível para a vela."}, "resposta_correta": "B", "justificativa": "A queima consome O2 e gera CO2 e vapor de água. Enquanto acesa, a chama aquece o ar interno, que se expande e parte escapa. Quando a chama se extingue (por esgotamento do O2), o ar restante resfria rapidamente e o vapor condensa, diminuindo a pressão interna; a pressão atmosférica externa empurra então a água para dentro do copo.", "possui_imagem": false},
  {"id": 51, "uid": "CIEN-6-051", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Energia de Ativação", "dificuldade": "Difícil", "enunciado": "Um palito de fósforo comum contém em sua cabeça substâncias combustíveis (como sulfeto de antimônio e enxofre) e oxidantes (como clorato de potássio). No entanto, o palito pode permanecer anos dentro da caixinha sem pegar fogo espontaneamente. Ele só entra em combustão quando é friccionado vigorosamente na lixa lateral da caixa. O papel da fricção mecânica é:", "alternativas": {"A": "Criar oxigênio que não existia no ar ao redor do fósforo.", "B": "Fornecer a energia de ativação necessária, por meio do atrito e calor gerado, para iniciar a reação química em cadeia.", "C": "Transformar o fósforo em um catalisador biológico que atrai chamas.", "D": "Remover todo o comburente da cabeça do palito para que a madeira queime pura.", "E": "Destruir a estrutura física da madeira para que ela vire cinza antes da queima."}, "resposta_correta": "B", "justificativa": "Mesmo reações altamente exotérmicas (que liberam muito calor) requerem uma quantidade inicial mínima de energia para romper as primeiras ligações dos reagentes — chamada de energia de ativação. O atrito na lixa gera calor suficiente para fornecer essa energia inicial.", "possui_imagem": false},
  {"id": 52, "uid": "CIEN-6-052", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Oxidação Gradual e Consumo de Oxigênio", "dificuldade": "Difícil", "enunciado": "Em um tubo de ensaio invertido sobre um béquer com água, prende-se no fundo interno uma mecha úmida de palha de aço. Após 48 horas à temperatura ambiente, nota-se que o ferro escureceu com ferrugem e a água subiu cerca de 1/5 (aproximadamente 21%) do volume total do tubo. Por que a água subiu exatamente essa fração?", "alternativas": {"A": "Porque a água evaporou dentro do tubo e preencheu o espaço vazio.", "B": "Porque a reação de oxidação do ferro consumiu o gás oxigênio presente no ar do tubo, que corresponde a aproximadamente 21% da composição do ar atmosférico.", "C": "Porque o nitrogênio do ar foi completamente destruído pelo contato com o ferro.", "D": "Porque o ferro absorveu hidrogênio da água líquida e expulsou o ar restante.", "E": "Porque a gravidade do béquer empurrou a água para cima como um ímã."}, "resposta_correta": "B", "justificativa": "O ar atmosférico é composto por cerca de 78% de nitrogênio, 21% de oxigênio e 1% de outros gases. A formação da ferrugem consumiu especificamente o O2 do ar confinado; a água subiu para ocupar o volume do gás consumido, demonstrando a proporção de oxigênio no ar.", "possui_imagem": false},
  {"id": 53, "uid": "CIEN-6-053", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Efeito Estufa e Reações de Queima de Combustíveis Fósseis", "dificuldade": "Difícil", "enunciado": "A queima de combustíveis fósseis (como gasolina, diesel e carvão mineral) nos motores dos veículos e indústrias é uma transformação química que preocupa cientistas no mundo todo. O principal impacto ambiental global dessa reação química em larga escala é:", "alternativas": {"A": "A destruição total do oxigênio de todo o planeta nas próximas duas semanas.", "B": "A emissão maciça de dióxido de carbono (CO2) na atmosfera, intensificando o efeito estufa e contribuindo para o aquecimento global antropogênico.", "C": "O resfriamento extremo do planeta devido ao excesso de cinzas na estratosfera.", "D": "A transformação dos oceanos em combustível líquido inflamável.", "E": "A eliminação da camada de ozônio causada unicamente pelo vapor de água gerado."}, "resposta_correta": "B", "justificativa": "A combustão de hidrocarbonetos gera água e dióxido de carbono (CO2). O acúmulo contínuo de CO2 na atmosfera eleva a retenção de calor irradiado pela superfície terrestre, intensificando o efeito estufa.", "possui_imagem": false},
  {"id": 54, "uid": "CIEN-6-054", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Cinética Química: Superfície de Contato e Explosões de Poeira", "dificuldade": "Difícil", "enunciado": "Em moinhos de trigo e silos de armazenamento de grãos, existem avisos rigorosos proibindo qualquer faísca ou chama aberta, pois pós finos de farinha em suspensão no ar podem causar explosões violentas. Esse risco extremo é explicado pelo fato de que:", "alternativas": {"A": "A farinha de trigo contém pólvora e dinamite em sua composição natural.", "B": "A pulverização em partículas finíssimas cria uma superfície de contato imensa entre o carboidrato e o oxigênio do ar, permitindo que a queima ocorra com velocidade instantânea e explosiva.", "C": "A farinha atua como comburente e substitui o oxigênio da atmosfera.", "D": "O pó de trigo absorve calor até transformar o nitrogênio do ar em chamas.", "E": "Grãos de trigo são substâncias químicas inertes que não sofrem combustão."}, "resposta_correta": "B", "justificativa": "Materiais orgânicos combustíveis (como farinha, amido e serragem), quando dispersos no ar em partículas microscópicas, possuem uma razão área/volume extraordinariamente alta. Uma faísca pode desencadear uma reação de combustão em cadeia quase instantânea (explosão de poeira).", "possui_imagem": false},
  {"id": 55, "uid": "CIEN-6-055", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Identificação de Transformações em Sequência", "dificuldade": "Difícil", "enunciado": "Analise as três etapas do preparo de um bolo:\n1. Bater a manteiga com o açúcar até formar um creme homogêneo.\n2. Misturar os ovos, a farinha e o fermento químico em pó.\n3. Assar a massa no forno quente a 180 ºC por 40 minutos.\nQuais etapas representam, respectivamente, transformações físicas e químicas preponderantes?", "alternativas": {"A": "1: física; 2: física; 3: química.", "B": "1: química; 2: química; 3: física.", "C": "1: física; 2: química; 3: física.", "D": "1: química; 2: física; 3: química.", "E": "1, 2 e 3 são exclusivamente transformações químicas."}, "resposta_correta": "A", "justificativa": "A etapa 1 é uma mistura mecânica (transformação física). Na etapa 2, os ingredientes são misturados fisicamente (embora o fermento comece a reagir lentamente, a grande transformação química ocorre no calor). Na etapa 3, o calor do forno desencadeia a desnaturação de proteínas, caramelização, expansão de gases do fermento e reações químicas irreversíveis que estruturam o bolo assado.", "possui_imagem": false},
  {"id": 56, "uid": "CIEN-6-056", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Equilíbrio e Reversibilidade no Cotidiano", "dificuldade": "Difícil", "enunciado": "Garrafas de refrigerante fechadas contêm gás carbônico dissolvido sob alta pressão em equilíbrio com o gás no espaço livre do gargalo. Ao abrir a tampa, escuta-se o ruído característico de escape de gás e formam-se inúmeras bolhas no líquido. A liberação do gás ao abrir a garrafa ocorre porque:", "alternativas": {"A": "A queda na pressão interna diminui a solubilidade do gás carbônico no líquido, fazendo com que ele se desprenda como gás.", "B": "O oxigênio do ar entrou e queimou instantaneamente o refrigerante.", "C": "Ocorreu uma reação química entre o plástico da garrafa e o refrigerante.", "D": "A abertura da garrafa aumentou a temperatura do refrigerante em 50 ºC.", "E": "O gás carbônico se transformou em açúcar sólido no fundo da garrafa."}, "resposta_correta": "A", "justificativa": "O gás carbônico é dissolvido sob pressão na fábrica (formando ácido carbônico em equilíbrio: H2O + CO2 <-> H2CO3). Ao despressurizar o frasco, a solubilidade do gás cai drasticamente e o equilíbrio desloca-se, liberando o CO2 gasoso em forma de efervescência física.", "possui_imagem": false},
  {"id": 57, "uid": "CIEN-6-057", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Conservação de Massas: Experimento de Queima", "dificuldade": "Difícil", "enunciado": "Um aluno realizou três experimentos de combustão em recipientes abertos na balança:\n- Experimento X: queima de 20 g de carvão vegetal (deixou 1 g de cinzas).\n- Experimento Y: queima de 20 g de palha de aço (deixou 26 g de resíduo escurecido).\n- Experimento Z: queima de 20 g de parafina de vela (não deixou resíduo visível).\nConsiderando a Lei de Lavoisier e a presença do oxigênio atmosférico, pode-se afirmar corretamente que:", "alternativas": {"A": "Apenas o experimento Y obedeceu à Lei de Lavoisier; os outros a violaram.", "B": "Em todos os experimentos a Lei de Lavoisier é válida, e as variações de massa na balança decorrem das trocas de matéria (gases consumidos ou liberados) com a atmosfera no sistema aberto.", "C": "Nenhum dos experimentos seguiu a lei de conservação de massas por terem sido feitos na Terra.", "D": "O carvão e a parafina violaram a conservação porque a matéria foi convertida em luz pura.", "E": "No experimento Y, a matéria foi criada do nada pela alta temperatura da chama."}, "resposta_correta": "B", "justificativa": "A Lei de Lavoisier é universal. Em sistemas abertos, quando há gases como reagentes (como O2 absorvido pelo ferro em Y) ou como produtos (como CO2 e H2O liberados em X e Z), a balança registra variações aparentes de massa sólida, mas a massa de todo o sistema (sólidos + gases) sempre se conserva.", "possui_imagem": false},
  {"id": 58, "uid": "CIEN-6-058", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Velocidade de Reação: Superfície e Enzimas na Digestão", "dificuldade": "Difícil", "enunciado": "Duas amostras idênticas de 10 gramas de carne bovina cozida foram colocadas em tubos de ensaio com a mesma solução de ácido clorídrico e pepsina (suco gástrico artificial) a 37 ºC:\n- Tubo A: a carne foi colocada em um único cubo maciço.\n- Tubo B: a carne foi triturada em pedacinhos de menos de 1 mm.\nApós 3 horas, verificou-se que o Tubo B teve praticamente toda a carne digerida, enquanto o Tubo A teve apenas a superfície externa desgastada. A conclusão pedagógica correta é:", "alternativas": {"A": "A digestão mecânica diminui a eficiência das enzimas digestivas.", "B": "A redução do tamanho das partículas aumenta a área superficial total, permitindo maior contato simultâneo entre as enzimas e as proteínas da carne.", "C": "No tubo A, a carne não possuía proteínas em sua composição interna.", "D": "A pepsina só funciona quando o alimento está em estado gasoso.", "E": "O tubo B aqueceu sozinho por causa do tamanho dos pedaços de carne."}, "resposta_correta": "B", "justificativa": "A mastigação ou trituração (digestão mecânica) fraciona o alimento, aumentando drasticamente a área superficial exposta aos catalisadores biológicos (pepsina e ácido), elevando a taxa de hidrólise enzimática das proteínas.", "possui_imagem": false},
  {"id": 59, "uid": "CIEN-6-059", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Reações Químicas no Solo e Agricultura", "dificuldade": "Difícil", "enunciado": "Muitos solos brasileiros são naturalmente ácidos, o que dificulta o cultivo de grãos como a soja e o milho. Os agricultores realizam a 'calagem', aplicando calcário agrícola (carbonato de cálcio e magnésio) ao solo. O papel do calcário no solo é um exemplo de transformação química porque:", "alternativas": {"A": "Ele reage quimicamente com os ácidos do solo, neutralizando a acidez e corrigindo o pH para valores propícios ao desenvolvimento das raízes.", "B": "Ele atua apenas compactando a terra para que a água da chuva não penetre.", "C": "Ele se transforma em água pura que irriga a plantação em períodos de seca.", "D": "Ele queima as sementes das ervas daninhas através de uma combustão controlada.", "E": "Ele atrai oxigênio do espaço sideral diretamente para as folhas da planta."}, "resposta_correta": "A", "justificativa": "A calagem é uma clássica reação química de neutralização: os carbonatos básicos reagem com os íons hidrogênio (H+) responsáveis pela acidez do solo, elevando o pH e liberando nutrientes minerais essenciais para a absorção pelas plantas.", "possui_imagem": false},
  {"id": 60, "uid": "CIEN-6-060", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Cinética Química e Conservação por Desidratação", "dificuldade": "Difícil", "enunciado": "Frutas desidratadas (como uvas-passas, banana-passa e damascos secos) duram meses ou anos sem estragar, mesmo armazenadas em temperatura ambiente fora da geladeira. Sob a ótica da cinética química e das reações biológicas de decomposição, isso se explica porque:", "alternativas": {"A": "A ausência quase total de água líquida inviabiliza as reações químicas catalisadas por enzimas de microrganismos que dependem do meio aquoso para ocorrer.", "B": "As frutas desidratadas perdem todos os seus nutrientes, tornando-se plástico inerte.", "C": "A desidratação transforma as frutas em pedras minerais não comestíveis.", "D": "As uvas-passas liberam toxinas que matam instantaneamente qualquer ser vivo.", "E": "A água das frutas secas se transformou em álcool desinfetante permanente."}, "resposta_correta": "A", "justificativa": "A água atua como solvente e meio reacional indispensável para o transporte de nutrientes e atividade de enzimas metabólicas de fungos e bactérias. Na ausência de água livre, a velocidade das reações químicas de decomposição cai a níveis desprezíveis, preservando o alimento.", "possui_imagem": false},
  {"id": 61, "uid": "CIEN-6-061", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Oxidação de Metais Nobres vs. Metais Comuns", "dificuldade": "Difícil", "enunciado": "Joias de ouro puro (24 quilates) encontradas em tumbas egípcias com mais de 3.000 anos mantêm seu brilho e cor originais intactos, enquanto objetos de ferro ou cobre da mesma época encontram-se profundamente corroídos por ferrugem ou azinhavre. Essa diferença marcante ocorre porque:", "alternativas": {"A": "O ouro não é matéria e portanto não possui átomos sujeitos a transformações.", "B": "O ouro é um metal quimicamente muito pouco reativo (metal nobre) que praticamente não reage com o oxigênio e a água em condições ambientais normais.", "C": "Os egípcios pintaram o ouro com plástico protetor impermeável.", "D": "O ferro e o cobre absorveram luz solar no escuro das tumbas e explodiram.", "E": "O ouro é um gás comprimido que não sofre oxidação."}, "resposta_correta": "B", "justificativa": "A reatividade química dos metais varia amplamente. O ferro é facilmente oxidado por O2 e umidade, enquanto o ouro possui altíssima estabilidade química e baixíssima tendência a doar elétrons ao oxigênio, permanecendo inalterado ao longo de milênios.", "possui_imagem": false},
  {"id": 62, "uid": "CIEN-6-062", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Efervescência e Ácidos Orgânicos", "dificuldade": "Difícil", "enunciado": "O pó de um comprimido efervescente contém uma mistura seca de bicarbonato de sódio e ácido cítrico. Enquanto estão na embalagem lacrada e seca, nada acontece e o pó permanece inerte. Porém, ao jogar uma colherada desse pó em um copo com água, a efervescência ocorre vigorosamente em frações de segundo. Por que a água líquida é indispensável para que a reação ocorra?", "alternativas": {"A": "A água líquida fornece calor para queimar o bicarbonato como combustível.", "B": "No estado sólido seco, os íons e moléculas estão fixos em suas redes cristalinas sem mobilidade para se encontrarem e colidirem; a água dissolve e ioniza os reagentes, permitindo a colisão efetiva entre as partículas.", "C": "A água reage com o ar e cria o gás carbônico antes de tocar no comprimido.", "D": "A água atua destruindo o ácido cítrico e deixando apenas o sal puro.", "E": "O bicarbonato só existe quando entra em contato com água doce."}, "resposta_correta": "B", "justificativa": "No estado sólido, as partículas dos reagentes estão imobilizadas em redes cristalinas, com contato restrito aos pontos de toque dos grãos. A água atua como solvente: dissolve os componentes, promove a ionização do ácido e confere mobilidade aos íons em solução, permitindo colisões imediatas e a reação química.", "possui_imagem": false},
  {"id": 63, "uid": "CIEN-6-063", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 14: Transformações Químicas", "tema": "Ciclo da Matéria e Conservação de Massa na Biosfera", "dificuldade": "Difícil", "enunciado": "Considere a seguinte reflexão: 'Os átomos de carbono que compõem o tecido muscular do seu corpo hoje já fizeram parte, em épocas remotas, de dinossauros, plantas pré-históricas ou da atmosfera primitiva da Terra'. Essa afirmação está fundamentada em qual princípio científico?", "alternativas": {"A": "Na criação contínua e espontânea de novos elementos químicos pelo calor do Sol.", "B": "Na Lei da Conservação da Massa e na ciclagem biogeoquímica da matéria, onde os átomos se recombinam em diferentes substâncias químicas sem serem destruídos ou criados.", "C": "Na teoria de que a matéria do universo é renovada e destruída a cada século.", "D": "No fato de que os seres vivos são constituídos apenas de energia e não de matéria.", "E": "Na transformação biológica que transforma ferro em carbono dentro das células."}, "resposta_correta": "B", "justificativa": "Pela Lei de Lavoisier e pelos ciclos biogeoquímicos (como o ciclo do carbono), a quantidade de átomos na biosfera é constante em termos práticos; os átomos de carbono passam continuamente por reações químicas (fotossíntese, respiração, combustão, decomposição), reorganizando-se em moléculas distintas ao longo das eras geológicas.", "possui_imagem": false},
  {"id": 64, "uid": "CIEN-6-064", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Estrutura do Neurônio", "dificuldade": "Fácil", "enunciado": "O sistema nervoso é formado principalmente por células altamente especializadas na transmissão de impulsos elétricos, chamadas neurônios. A parte do neurônio que contém o núcleo e a maior parte do citoplasma é o:", "alternativas": {"A": "Axônio.", "B": "Dendrito.", "C": "Corpo celular.", "D": "Terminação nervosa.", "E": "Bainha de mielina."}, "resposta_correta": "C", "justificativa": "O corpo celular (ou pericário) é a região central do neurônio que abriga o núcleo celular e a maior parte das organelas citoplasmáticas.", "possui_imagem": true},
  {"id": 65, "uid": "CIEN-6-065", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Divisão do Sistema Nervoso", "dificuldade": "Fácil", "enunciado": "O Sistema Nervoso Central (SNC) do corpo humano é protegido por estruturas ósseas rígidas e é composto por:", "alternativas": {"A": "Encéfalo e medula espinhal.", "B": "Nervos cranianos e nervos espinhais.", "C": "Coração e pulmões.", "D": "Cérebro e gânglios periféricos.", "E": "Medula óssea e coluna vertebral."}, "resposta_correta": "A", "justificativa": "O SNC é formado pelo encéfalo (abrigado no crânio) e pela medula espinhal (abrigada no canal vertebral). Os nervos e gânglios compõem o Sistema Nervoso Periférico (SNP).", "possui_imagem": true},
  {"id": 66, "uid": "CIEN-6-066", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Órgãos do Encéfalo", "dificuldade": "Fácil", "enunciado": "Durante uma partida de futebol ou ao andar de bicicleta, um órgão do encéfalo é fundamental para coordenar os movimentos musculares, manter o equilíbrio e a postura corporal. Esse órgão é o:", "alternativas": {"A": "Cérebro.", "B": "Cerebelo.", "C": "Bulbo raquidiano.", "D": "Estômago.", "E": "Fígado."}, "resposta_correta": "B", "justificativa": "O cerebelo é a estrutura encefálica responsável pela coordenação motora fina, controle do tônus muscular e manutenção do equilíbrio corporal.", "possui_imagem": true},
  {"id": 67, "uid": "CIEN-6-067", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Transmissão do Impulso Nervoso: Sinapse", "dificuldade": "Fácil", "enunciado": "A região de comunicação funcional entre dois neurônios vizinhos, por onde passam sinais químicos chamados neurotransmissores, é denominada:", "alternativas": {"A": "Ventrículo.", "B": "Sinapse.", "C": "Articulação.", "D": "Válvula.", "E": "Tendão."}, "resposta_correta": "B", "justificativa": "A sinapse é a junção funcional especializada entre um neurônio e outra célula (neurônio, fibra muscular ou glândula), onde ocorre a transmissão do sinal por neurotransmissores.", "possui_imagem": true},
  {"id": 68, "uid": "CIEN-6-068", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sentido do Tato", "dificuldade": "Fácil", "enunciado": "O tato é o sentido que nos permite perceber textura, temperatura, pressão e dor. O principal órgão do corpo humano associado a esse sentido é:", "alternativas": {"A": "A língua.", "B": "O nariz.", "C": "A pele.", "D": "O ouvido.", "E": "O olho."}, "resposta_correta": "C", "justificativa": "A pele é o maior órgão do corpo humano e contém uma variedade de receptores sensoriais responsáveis por captar estímulos táteis, térmicos e dolorosos.", "possui_imagem": false},
  {"id": 69, "uid": "CIEN-6-069", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sentido da Gustação: Sabores Básicos", "dificuldade": "Fácil", "enunciado": "As papilas gustativas localizadas na língua humana são capazes de identificar cinco sabores primários distintos. Quais são eles?", "alternativas": {"A": "Doce, salgado, picante, amargo e crocante.", "B": "Doce, salgado, azedo (ácido), amargo e umami.", "C": "Gorduroso, doce, azedo, quente e frio.", "D": "Salgado, doce, mentolado, queimado e azedo.", "E": "Umami, ácido, amargo, perfumado e adstringente."}, "resposta_correta": "B", "justificativa": "Os cinco gostos primários reconhecidos cientificamente pelos receptores gustativos são: doce, salgado, azedo (ácido), amargo e umami (relacionado ao glutamato). 'Picante' é uma sensação de dor/calor (nocicepção), não um sabor primário.", "possui_imagem": true},
  {"id": 70, "uid": "CIEN-6-070", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Integração Olfato e Paladar", "dificuldade": "Fácil", "enunciado": "Quando uma pessoa está com um resfriado forte e o nariz completamente entupido por secreções, ela frequentemente reclama que os alimentos parecem 'sem gosto'. Isso acontece porque:", "alternativas": {"A": "A língua perde todas as suas papilas gustativas durante a gripe.", "B": "A maior parte do sabor percebido resulta da combinação entre o paladar (gosto) e o olfato (aroma).", "C": "O estômago para de produzir enzimas digestivas.", "D": "Os dentes não conseguem mastigar os alimentos adequadamente.", "E": "O resfriado bloqueia os nervos auditivos da cabeça."}, "resposta_correta": "B", "justificativa": "O que chamamos popularmente de 'sabor' é a integração sensorial entre o paladar (detectado na língua) e o olfato retronasal (moléculas voláteis que sobem à cavidade nasal). Com o nariz entupido, perde-se a percepção olfativa dos aromas.", "possui_imagem": false},
  {"id": 71, "uid": "CIEN-6-071", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Anatomia da Audição: Orelha Humana", "dificuldade": "Fácil", "enunciado": "A orelha humana é dividida anatomicamente em três partes. A estrutura visível externamente que capta as ondas sonoras e as direciona para o canal auditivo é o:", "alternativas": {"A": "Tímpano.", "B": "Pavilhão auricular.", "C": "Labirinto.", "D": "Caracol (cóclea).", "E": "Estribo."}, "resposta_correta": "B", "justificativa": "O pavilhão auricular (orelha externa) funciona como uma concha acústica, captando e afunilando as ondas mecânicas do som para o interior do meato acústico externo.", "possui_imagem": true},
  {"id": 72, "uid": "CIEN-6-072", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Estruturas da Orelha Média", "dificuldade": "Fácil", "enunciado": "Na orelha média humana encontram-se os três menores ossos do corpo humano, cuja função é amplificar e transmitir as vibrações sonoras do tímpano até a orelha interna. Esses ossículos são chamados de:", "alternativas": {"A": "Fêmur, tíbia e fíbula.", "B": "Martelo, bigorna e estribo.", "C": "Rádio, ulna e úmero.", "D": "Clavícula, escápula e esterno.", "E": "Córnea, íris e cristalino."}, "resposta_correta": "B", "justificativa": "O martelo, a bigorna e o estribo formam a cadeia ossicular da orelha média, responsável pela transmissão mecânica amplificada das vibrações do tímpano para a janela oval da cóclea.", "possui_imagem": true},
  {"id": 73, "uid": "CIEN-6-073", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sentido do Equilíbrio", "dificuldade": "Fácil", "enunciado": "Além da audição, a orelha interna desempenha outro papel biológico vital para o organismo humano, que é:", "alternativas": {"A": "Controlar a produção de saliva.", "B": "A manutenção do equilíbrio corporal e a percepção da orientação da cabeça no espaço.", "C": "A regulação da temperatura do sangue no cérebro.", "D": "A filtragem mecânica de poeira do ar respirado.", "E": "A dilatação das pupilas em ambientes escuros."}, "resposta_correta": "B", "justificativa": "Os canais semicirculares e o vestíbulo (aparelho vestibular/labirinto), localizados na orelha interna, contêm líquido e células ciliadas que detectam a posição e movimentos da cabeça, sendo fundamentais para o equilíbrio.", "possui_imagem": true},
  {"id": 74, "uid": "CIEN-6-074", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Atos Reflexos", "dificuldade": "Fácil", "enunciado": "Ao encostar acidentalmente o dedo em uma panela quente, a pessoa recolhe a mão instantaneamente, antes mesmo de tomar consciência da dor ou pensar no que fazer. Essa resposta rápida e involuntária é chamada de:", "alternativas": {"A": "Movimento voluntário consciente.", "B": "Ato reflexo.", "C": "Sinapse muscular voluntária.", "D": "Paralisia nervosa temporária.", "E": "Digestão reflexa."}, "resposta_correta": "B", "justificativa": "O ato reflexo é uma resposta involuntária e automática a um estímulo, processada na medula espinhal para proteger rapidamente o corpo contra lesões, sem depender do comando do cérebro.", "possui_imagem": true},
  {"id": 75, "uid": "CIEN-6-075", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sistema Locomotor", "dificuldade": "Fácil", "enunciado": "O movimento do corpo humano depende da integração direta entre o sistema nervoso e o sistema locomotor. As estruturas resistentes que conectam os músculos esqueléticos aos ossos são os:", "alternativas": {"A": "Tendões.", "B": "Ligamentos.", "C": "Neurônios motores.", "D": "Cartilagens articulares.", "E": "Vasos capilares."}, "resposta_correta": "A", "justificativa": "Os tendões são cordões fibrosos ricos em colágeno que fixam os músculos aos ossos, transmitindo a força da contração muscular para gerar movimento das alavancas ósseas.", "possui_imagem": false},
  {"id": 76, "uid": "CIEN-6-076", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Drogas Psicoativas: Conceito", "dificuldade": "Fácil", "enunciado": "Substâncias químicas que alteram o funcionamento do sistema nervoso central, modificando a percepção, o humor, a consciência e o comportamento de um indivíduo, são classificadas como:", "alternativas": {"A": "Substâncias psicoativas.", "B": "Antibióticos de amplo espectro.", "C": "Vitaminas lipossolúveis.", "D": "Hormônios digestivos.", "E": "Sais minerais inorgânicos."}, "resposta_correta": "A", "justificativa": "Drogas psicoativas são substâncias naturais ou sintéticas que afetam a neurotransmissão no encéfalo, provocando alterações comportamentais, cognitivas e emocionais.", "possui_imagem": false},
  {"id": 77, "uid": "CIEN-6-077", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Impacto do Álcool no Sistema Nervoso", "dificuldade": "Fácil", "enunciado": "O consumo de bebidas alcoólicas afeta o sistema nervoso central, tornando os reflexos mais lentos e prejudicando a coordenação motora. Por essa razão, as leis de trânsito proíbem rigorosamente dirigir após beber. No cérebro, o álcool atua principalmente como um:", "alternativas": {"A": "Estimulante de reflexos rápidos.", "B": "Depressor do sistema nervoso central.", "C": "Nutriente essencial para os neurônios.", "D": "Regulador da pressão ocular.", "E": "Antitoxina hepática."}, "resposta_correta": "B", "justificativa": "O álcool atua como uma substância depressora do sistema nervoso central, reduzindo a velocidade de propagação dos impulsos nervosos e inibindo funções cognitivas e motoras.", "possui_imagem": false},
  {"id": 78, "uid": "CIEN-6-078", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Estrutura do Neurônio: Prolongamentos", "dificuldade": "Fácil", "enunciado": "Em um neurônio típico, os prolongamentos curtos e ramificados que recebem os estímulos e sinais provenientes de outros neurônios são chamados de:", "alternativas": {"A": "Dendritos.", "B": "Axônios.", "C": "Células da glia.", "D": "Sinapses.", "E": "Gânglios."}, "resposta_correta": "A", "justificativa": "Os dendritos são extensões ramificadas do corpo celular cuja função primordial é receber sinais aferentes de neurônios vizinhos ou de receptores sensoriais.", "possui_imagem": true},
  {"id": 79, "uid": "CIEN-6-079", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Medula Espinhal", "dificuldade": "Fácil", "enunciado": "A medula espinhal é um cordão de tecido nervoso localizado dentro de qual estrutura esquelética protetora?", "alternativas": {"A": "Caixa torácica.", "B": "Coluna vertebral.", "C": "Bacia pélvica.", "D": "Crânio.", "E": "Omoplata."}, "resposta_correta": "B", "justificativa": "A medula espinhal estende-se pelo canal vertebral, sendo circundada e protegida pelas vértebras da coluna vertebral.", "possui_imagem": false},
  {"id": 80, "uid": "CIEN-6-080", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sentido do Olfato: Receptores", "dificuldade": "Fácil", "enunciado": "Para que sintamos o cheiro de uma flor ou de um perfume, é necessário que substâncias químicas dispersas no ar entrem pelo nariz e se dissolvam no muco nasal, atingindo:", "alternativas": {"A": "As cordas vocais.", "B": "As células receptoras olfatórias no teto da cavidade nasal.", "C": "O esôfago.", "D": "O tímpano.", "E": "O cristalino dos olhos."}, "resposta_correta": "B", "justificativa": "O epitélio olfatório, localizado na região superior da cavidade nasal, contém milhões de neurônios receptores olfatórios equipados com cílios que detectam moléculas químicas odoríferas.", "possui_imagem": true},
  {"id": 81, "uid": "CIEN-6-081", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Receptores da Pele", "dificuldade": "Fácil", "enunciado": "Na pele, existem receptores sensoriais especializados chamados nociceptores. Eles têm a importante função biológica de captar estímulos de:", "alternativas": {"A": "Luminosidade excessiva.", "B": "Dor (estímulos nocivos ou lesivos aos tecidos).", "C": "Vibrações sonoras graves.", "D": "Gosto amargo de toxinas.", "E": "Pressão atmosférica espacial."}, "resposta_correta": "B", "justificativa": "Os nociceptores são terminações nervosas livres que respondem a estímulos potencialmente danosos aos tecidos, gerando a sensação protetora de dor.", "possui_imagem": true},
  {"id": 82, "uid": "CIEN-6-082", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Articulações e Movimento", "dificuldade": "Fácil", "enunciado": "No sistema esquelético, o ponto de encontro entre dois ou mais ossos que possibilita a flexão dos membros (como o joelho e o cotovelo) é denominado:", "alternativas": {"A": "Vértebra.", "B": "Articulação.", "C": "Medula espinhal.", "D": "Miócito.", "E": "Fibrila muscular."}, "resposta_correta": "B", "justificativa": "As articulações sinoviais móveis unem peças esqueléticas e, juntamente com a cartilagem e o líquido sinovial, permitem movimentos angulares e de rotação do corpo.", "possui_imagem": true},
  {"id": 83, "uid": "CIEN-6-083", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Função do Bulbo Encefálico", "dificuldade": "Fácil", "enunciado": "O bulbo raquidiano (parte do tronco encefálico) desempenha funções vitais automáticas no corpo humano. Entre elas, destaca-se o controle involuntário de:", "alternativas": {"A": "Pensamentos filosóficos e criatividade artística.", "B": "Batimentos cardíacos e movimentos respiratórios.", "C": "Memorização de números de telefone.", "D": "Expressões faciais aprendidas na infância.", "E": "Leitura de palavras escritas."}, "resposta_correta": "B", "justificativa": "O bulbo e o tronco encefálico contêm centros reguladores vitais do sistema nervoso autônomo, controlando frequência cardíaca, respiração, deglutição, vômito e tosse.", "possui_imagem": false},
  {"id": 84, "uid": "CIEN-6-084", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Dependência Química", "dificuldade": "Fácil", "enunciado": "O uso continuado de drogas como a nicotina (presente no tabaco) costuma levar ao estado em que a pessoa sente uma necessidade incontrolável de consumir a substância para se sentir 'normal'. Esse fenômeno é chamado de:", "alternativas": {"A": "Digestão química.", "B": "Dependência (química/psicológica).", "C": "Ato reflexo incondicionado.", "D": "Imunidade adquirida.", "E": "Miopia neurológica."}, "resposta_correta": "B", "justificativa": "A dependência química ocorre quando o cérebro se adapta bioquimicamente à presença contínua da substância psicoativa, gerando compulsão, tolerância e sintomas de abstinência quando o uso cessa.", "possui_imagem": false},
  {"id": 85, "uid": "CIEN-6-085", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Circuito do Arco Reflexo", "dificuldade": "Médio", "enunciado": "Quando o médico bate suavemente com um martelinho de borracha no tendão patelar abaixo do joelho de um paciente, a perna se estende involuntariamente (reflexo patelar). O caminho correto percorrido pelo impulso nervoso nesse arco reflexo é:", "alternativas": {"A": "Receptor -> Cérebro -> Cerebelo -> Músculo da perna.", "B": "Receptor sensorial -> Neurônio sensitivo -> Medula espinhal -> Neurônio motor -> Músculo efetuador.", "C": "Neurônio motor -> Medula -> Cérebro -> Neurônio sensitivo -> Joelho.", "D": "Músculo -> Nervo craniano -> Olho -> Medula -> Tendão.", "E": "Cerebelo -> Tronco encefálico -> Medula -> Neurônio sensitivo -> Osso."}, "resposta_correta": "B", "justificativa": "O arco reflexo clássico é composto por: receptor sensorial -> neurônio sensitivo (aferente) -> centro integrador na medula espinhal (com ou sem interneurônio) -> neurônio motor (eferente) -> órgão efetuador (músculo da coxa).", "possui_imagem": true},
  {"id": 86, "uid": "CIEN-6-086", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Bainha de Mielina e Condução Saltatória", "dificuldade": "Médio", "enunciado": "O axônio de muitos neurônios humanos é revestido por uma camada lipídica isolante chamada bainha de mielina, intercalada pelos nós de Ranvier. A principal função biológica dessa bainha é:", "alternativas": {"A": "Armazenar nutrientes para alimentar o cérebro durante o sono.", "B": "Aumentar significativamente a velocidade de propagação do impulso nervoso através da condução saltatória.", "C": "Impedir que o neurônio receba sangue oxigenado.", "D": "Substituir o núcleo celular caso o corpo do neurônio seja danificado.", "E": "Produzir lágrimas e secreções nasais contínuas."}, "resposta_correta": "B", "justificativa": "A bainha de mielina atua como isolante elétrico biológico; o potencial de ação salta entre os nós de Ranvier desprovidos de mielina, acelerando drasticamente a condução do sinal nervoso.", "possui_imagem": false},
  {"id": 87, "uid": "CIEN-6-087", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Transmissão Sináptica e Neurotransmissores", "dificuldade": "Médio", "enunciado": "Quando o impulso elétrico atinge o final do axônio de um neurônio pré-sináptico, ele não pode pular o espaço microscópico da fenda sináptica diretamente. Como a mensagem é transmitida para a célula seguinte?", "alternativas": {"A": "Pela liberação de neurotransmissores químicos que se difundem na fenda e se ligam a receptores específicos na membrana pós-sináptica.", "B": "Por uma faísca de alta voltagem que queima a fenda sináptica.", "C": "Pelo crescimento imediato de um novo osso que une os dois neurônios.", "D": "Por meio da troca de núcleos celulares entre os dois neurônios.", "E": "Pela expulsão de toda a água de dentro do neurônio pré-sináptico."}, "resposta_correta": "A", "justificativa": "Ao chegar ao terminal axônico, o impulso elétrico estimula a exocitose de vesículas com neurotransmissores (como dopamina, acetilcolina, serotonina) na fenda sináptica, que se ligam a receptores na célula receptora.", "possui_imagem": false},
  {"id": 88, "uid": "CIEN-6-088", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Distribuição dos Receptores Táteis na Pele", "dificuldade": "Médio", "enunciado": "Se encostarmos duas pontas de compasso separadas por apenas 2 milímetros na ponta do dedo indicador, uma pessoa de olhos vendados percebe claramente dois pontos distintos. No entanto, se o mesmo teste for feito na pele das costas, a pessoa sente apenas um único ponto de contato. A explicação biológica para isso é:", "alternativas": {"A": "A pele das costas não possui células vivas.", "B": "A densidade de receptores táteis é muito maior nas pontas dos dedos do que nas costas, propiciando campos receptivos menores e maior resolução tátil.", "C": "Os neurônios das costas não conseguem enviar mensagens para o encéfalo.", "D": "A ponta dos dedos possui os menores ossos do corpo que sentem o toque.", "E": "A pele das costas é mais fria, o que paralisa temporariamente todos os nervos."}, "resposta_correta": "B", "justificativa": "A sensibilidade tátil varia pelo corpo. Regiões de alta exploração tátil (como pontas dos dedos e lábios) têm grande concentração de mecanorreceptores e grande representação no córtex somatossensorial, enquanto áreas como as costas possuem receptores mais dispersos.", "possui_imagem": false},
  {"id": 89, "uid": "CIEN-6-089", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Mecanismo da Audição na Cóclea", "dificuldade": "Médio", "enunciado": "Na orelha interna, as vibrações mecânicas transmitidas pelos ossículos fazem vibrar a linfa (líquido interno) no interior de uma estrutura em espiral chamada cóclea. A conversão da vibração física em impulsos elétricos nervosos é realizada por:", "alternativas": {"A": "Células ciliadas do órgão de Corti, cujos cílios se dobram com o movimento do líquido, abrindo canais iônicos.", "B": "Ossículos microscópicos que quebram as ondas sonoras em pedaços de ar.", "C": "Glândulas sudoríparas que produzem cera no interior da cóclea.", "D": "Neurônios olfatórios que descem pelo fundo do ouvido.", "E": "Gotículas de gordura que flutuam no tímpano."}, "resposta_correta": "A", "justificativa": "Na cóclea, as ondas mecânicas no fluido fazem vibrar a membrana basilar, defletindo os estereocílios das células ciliadas sensoriais. Essa deformação mecânica gera despolarização e impulsos no nervo auditivo.", "possui_imagem": false},
  {"id": 90, "uid": "CIEN-6-090", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Tuba Auditiva e Pressão", "dificuldade": "Médio", "enunciado": "Ao descer uma serra íngreme de carro ou viajar de avião durante o pouso, é comum sentir uma sensação de 'ouvido entupido' e dor, que alivia ao bocejar ou engolir saliva. A estrutura anatômica responsável por igualar a pressão entre a orelha média e o ambiente externo é a:", "alternativas": {"A": "Tuba auditiva (antiga trompa de Eustáquio).", "B": "Cóclea espiralada.", "C": "Bainha de mielina.", "D": "Célula olfatória.", "E": "Janela oval."}, "resposta_correta": "A", "justificativa": "A tuba auditiva conecta a cavidade da orelha média à faringe. Ao engolir ou bocejar, ela se abre, permitindo o fluxo de ar para equilibrar a pressão em ambos os lados da membrana timpânica.", "possui_imagem": false},
  {"id": 91, "uid": "CIEN-6-091", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Canais Semicirculares e Labirintite", "dificuldade": "Médio", "enunciado": "Uma pessoa que gira várias vezes em torno de si mesma e para repentinamente continua sentindo que o ambiente ao seu redor ainda está girando (tontura). Isso acontece porque:", "alternativas": {"A": "O cérebro congelou devido ao movimento circular.", "B": "O líquido presente dentro dos canais semicirculares da orelha interna continua em movimento por inércia, estimulando as células ciliadas mesmo após a pessoa parar.", "C": "O ar atmosférico entrou nos pulmões com força excessiva.", "D": "Os ossos das pernas ficaram desencaixados temporariamente.", "E": "A luz do ambiente foi refletida com atraso pelas pupilas."}, "resposta_correta": "B", "justificativa": "A endolinfa nos canais semicirculares possui inércia. Ao frear o corpo, o líquido continua se deslocando momentaneamente, curvando as cúpulas e enviando sinais conflitantes de rotação ao cérebro.", "possui_imagem": false},
  {"id": 92, "uid": "CIEN-6-092", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Classificação das Drogas: Efeitos no SNC", "dificuldade": "Médio", "enunciado": "As drogas psicoativas são frequentemente divididas em três grupos principais segundo sua ação no Sistema Nervoso Central: depressoras, estimulantes e perturbadoras (alucinógenas). Assinale a alternativa que relaciona corretamente o grupo ao seu efeito predominante:", "alternativas": {"A": "Estimulantes: diminuem a atividade cerebral, causam sonolência e lentidão nos reflexos.", "B": "Depressoras: aumentam a agitação motora, provocam insônia e aceleram os batimentos cardíacos.", "C": "Perturbadoras: distorcem a percepção sensorial da realidade, provocando ilusões e alucinações visuais e auditivas.", "D": "Alucinógenas: melhoram a precisão motora e curam distúrbios da fala.", "E": "Depressoras: produzem exclusivamente visões místicas sem afetar a coordenação."}, "resposta_correta": "C", "justificativa": "Drogas perturbadoras (alucinógenos como LSD, maconha em certas doses) alteram a percepção do tempo, espaço e sentidos. As estimulantes aumentam a atividade neural, e as depressoras reduzem-na.", "possui_imagem": false},
  {"id": 93, "uid": "CIEN-6-093", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Ação Antagônica de Músculos no Braço", "dificuldade": "Médio", "enunciado": "Para dobrar o antebraço em direção ao ombro (flexão), o músculo bíceps braquial se contrai, enquanto o músculo tríceps braquial relaxa. Para esticar o braço (extensão), ocorre o inverso: o tríceps se contrai e o bíceps relaxa. Esse tipo de funcionamento muscular coordenado é chamado de:", "alternativas": {"A": "Ação muscular antagônica.", "B": "Ação muscular involuntária reflexa.", "C": "Atrofia muscular contínua.", "D": "Movimento peristáltico esquelético.", "E": "Sinapse óssea terminal."}, "resposta_correta": "A", "justificativa": "Músculos esqueléticos esqueléticos frequentemente operam em pares antagônicos: enquanto um se contrai (agonista) para produzir determinado movimento articular, o oposto se relaxa (antagonista), permitindo controle refinado.", "possui_imagem": false},
  {"id": 94, "uid": "CIEN-6-094", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Sistema Nervoso Autônomo e Estresse", "dificuldade": "Médio", "enunciado": "Diante de uma situação de perigo iminente (como se deparar com um cachorro bravo solto), o corpo humano ativa instantaneamente a resposta de 'luta ou fuga': a frequência cardíaca dispara, as pupilas dilatam e a respiração se torna ofegante. Essa reação automática é coordenada principalmente por qual divisão do sistema nervoso?", "alternativas": {"A": "Sistema Nervoso Somático voluntário.", "B": "Divisão Simpática do Sistema Nervoso Autônomo.", "C": "Divisão Parassimpática do Sistema Nervoso Autônomo.", "D": "Medula óssea vermelha.", "E": "Células da glia da pele."}, "resposta_correta": "B", "justificativa": "O sistema nervoso autônomo simpático prepara o organismo para responder a situações de emergência ('luta ou fuga'), liberando noradrenalina/adrenalina, elevando a circulação sanguínea nos músculos e aumentando o estado de alerta.", "possui_imagem": false},
  {"id": 95, "uid": "CIEN-6-095", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Tolerância a Drogas Psicoativas", "dificuldade": "Médio", "enunciado": "Com o uso repetido de certas substâncias químicas psicoativas, o usuário frequentemente percebe que a mesma dose inicial não produz mais o efeito desejado, necessitando de quantidades cada vez maiores da substância para atingir a mesma sensação. Esse mecanismo neurobiológico é denominado:", "alternativas": {"A": "Dependência psicológica pura.", "B": "Tolerância farmacológica.", "C": "Ato reflexo condicionado.", "D": "Desidratação celular.", "E": "Mielinização progressiva."}, "resposta_correta": "B", "justificativa": "A tolerância desenvolve-se quando os neurônios ajustam sua sensibilidade à droga (por exemplo, diminuindo o número de receptores na membrana pós-sináptica), exigindo doses crescentes para obter o mesmo efeito inicial.", "possui_imagem": false},
  {"id": 96, "uid": "CIEN-6-096", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Papel da Medula Espinhal em Lesões", "dificuldade": "Médio", "enunciado": "Um acidente com fratura grave nas vértebras da coluna na região dorsal (torácica) pode causar paralisia permanente nas pernas (paraplegia). Isso ocorre porque a lesão na medula espinhal:", "alternativas": {"A": "Destrói os ossos do fêmur e da tíbia instantaneamente.", "B": "Interrompe as vias nervosas ascendentes e descendentes que transmitem mensagens elétricas entre o cérebro e os membros inferiores.", "C": "Impede a respiração celular das células musculares dos braços.", "D": "Destrói o cerebelo e o bulbo na caixa craniana.", "E": "Faz o sangue deixar de circular no coração."}, "resposta_correta": "B", "justificativa": "A medula espinhal é a grande rodovia de feixes de axônios motores e sensitivos. Uma secção ou compressão grave interrompe a comunicação entre o encéfalo e os nervos espinhais abaixo do nível da lesão.", "possui_imagem": false},
  {"id": 97, "uid": "CIEN-6-097", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Adaptação dos Receptores Olfatórios", "dificuldade": "Médio", "enunciado": "Ao entrar em uma sala com um aroma forte de desinfetante ou ao passar perfume no corpo pela manhã, sentimos intensamente a fragrância nos primeiros minutos. Pouco tempo depois, quase não percebemos mais o cheiro, embora outra pessoa que acabe de entrar na sala sinta o odor de imediato. Esse fenômeno é conhecido como:", "alternativas": {"A": "Fadiga ou adaptação sensorial dos receptores olfatórios.", "B": "Destruição irreversível dos cílios nasais.", "C": "Paralisia dos nervos sensitivos da face.", "D": "Falta de oxigênio no cérebro.", "E": "Transformação química do perfume em água líquida."}, "resposta_correta": "A", "justificativa": "Os receptores sensoriais (especialmente olfatórios e táteis) passam por adaptação sensorial: diante de um estímulo constante e contínuo, a frequência de disparos de potenciais de ação diminui consideravelmente, poupando a atenção do cérebro.", "possui_imagem": false},
  {"id": 98, "uid": "CIEN-6-098", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Quimiorreceptores: Gustação e Olfato", "dificuldade": "Médio", "enunciado": "Tanto o sentido do olfato quanto o sentido da gustação pertencem à mesma categoria funcional de sentidos, pois seus órgãos receptores respondem a estímulos da mesma natureza física/química. Esses sentidos são classificados como:", "alternativas": {"A": "Fotorreceptores, pois necessitam de luz para funcionar.", "B": "Mecanorreceptores, pois detectam apenas forças de atrito físico.", "C": "Quimiorreceptores, pois são estimulados por substâncias químicas dissolvidas no muco nasal ou na saliva.", "D": "Termorreceptores, pois apenas medem a temperatura dos alimentos.", "E": "Barorreceptores, pois medem a pressão arterial da cabeça."}, "resposta_correta": "C", "justificativa": "Tanto as papilas gustativas quanto o epitélio olfatório são formados por quimiorreceptores: células especializadas que captam compostos químicos em solução aquosa (saliva ou muco).", "possui_imagem": false},
  {"id": 99, "uid": "CIEN-6-099", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "O Sabor Umami", "dificuldade": "Médio", "enunciado": "Identificado no início do século XX pelo cientista japonês Kikunae Ikeda, o sabor umami (palavra que significa 'delicioso' ou 'saboroso') é hoje amplamente aceito como o quinto gosto básico. Ele é desencadeado principalmente pela presença nos alimentos de:", "alternativas": {"A": "Grandes quantidades de açúcar refinado e mel.", "B": "Íons hidrogênio (H+) característicos de ácidos cítricos.", "C": "Glutamato e nucleotídeos, encontrados naturalmente em carnes, queijos maturados, tomates maduros e cogumelos.", "D": "Cloreto de sódio puro de salmoura marinha.", "E": "Substâncias amargas venenosas produzidas por plantas."}, "resposta_correta": "C", "justificativa": "O umami é ativado por aminoácidos, em particular o ácido glutâmico (glutamato monossódico). Alimentos ricos em proteínas como carnes, queijo parmesão, cogumelos e tomate ativam fortemente esses receptores.", "possui_imagem": false},
  {"id": 100, "uid": "CIEN-6-100", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Coordenação Motora e Bebidas Alcoólicas", "dificuldade": "Médio", "enunciado": "Durante testes de sobriedade realizados por policiais de trânsito, solicita-se ao condutor suspeito de embriaguez que caminhe em linha reta pé ante pé ou que toque a ponta do nariz com o indicador de olhos fechados. A dificuldade em executar essas tarefas sob efeito de álcool evidencia prejuízo específico em qual órgão encefálico?", "alternativas": {"A": "Cerebelo.", "B": "Bulbo raquidiano.", "C": "Hipófise.", "D": "Medula óssea.", "E": "Meninge dura-máter."}, "resposta_correta": "A", "justificativa": "O cerebelo é altamente sensível à ação inibitória do álcool. Sua disfunção temporária resulta em ataxia (perda de coordenação motora fina), marcha cambaleante e incapacidade de estimar distâncias corporais (dismetria).", "possui_imagem": false},
  {"id": 101, "uid": "CIEN-6-101", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Dor como Mecanismo Protetor", "dificuldade": "Médio", "enunciado": "Indivíduos que nascem com uma condição genética rara chamada 'insensibilidade congênita à dor' são incapazes de sentir qualquer tipo de dor física. Embora pareça uma vantagem à primeira vista, essas pessoas sofrem com frequência queimaduras graves, mordidas na própria língua e fraturas ósseas não tratadas. Esse fato comprova cientificamente que a dor:", "alternativas": {"A": "É um defeito biológico que a evolução humana ainda não eliminou.", "B": "É um mecanismo adaptativo e protetor fundamental que alerta o organismo sobre danos aos tecidos e evita lesões maiores.", "C": "Não tem qualquer relação com o sistema nervoso central.", "D": "É uma ilusão psicológica gerada unicamente pela imaginação.", "E": "Ocorre apenas quando os ossos entram em combustão."}, "resposta_correta": "B", "justificativa": "A dor é um mecanismo fisiológico crucial para a sobrevivência: ela sinaliza traumas e ameaças à integridade física, promovendo reflexos de fuga e comportamentos de repouso para cicatrização.", "possui_imagem": false},
  {"id": 102, "uid": "CIEN-6-102", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Nervos Cranianos vs. Espinhais", "dificuldade": "Médio", "enunciado": "O Sistema Nervoso Periférico é formado por nervos que se conectam ao SNC. Os nervos que partem diretamente do encéfalo e inervam estruturas da cabeça e pescoço (como olhos, língua e ouvidos) e os que partem da medula espinhal para os membros e tronco são chamados, respectivamente, de:", "alternativas": {"A": "Nervos espinhais e nervos cranianos.", "B": "Nervos cranianos e nervos espinhais.", "C": "Nervos sensitivos e gânglios linfáticos.", "D": "Nervos simpáticos e nervos do cerebelo.", "E": "Nervos motores e artérias coronárias."}, "resposta_correta": "B", "justificativa": "Existem 12 pares de nervos cranianos (que emergem do encéfalo) e 31 pares de nervos espinhais (que emergem da medula espinhal ao longo da coluna vertebral).", "possui_imagem": false},
  {"id": 103, "uid": "CIEN-6-103", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Células da Glia", "dificuldade": "Médio", "enunciado": "No tecido nervoso, além dos neurônios, existem células fundamentais que superam os neurônios em número, atuando no suporte físico, nutrição metabólica, defesa imunológica e produção da bainha de mielina. Esse grupo de células é conhecido coletivamente como:", "alternativas": {"A": "Miócitos esqueléticos.", "B": "Glíócitos (células da glia ou neuroglia).", "C": "Plaquetas sanguíneas.", "D": "Condrócitos articulares.", "E": "Osteoblastos medulares."}, "resposta_correta": "B", "justificativa": "A neuróglia (células da glia) inclui astrócitos (nutrição e suporte), oligodendrócitos e células de Schwann (mielinização), e micróglia (fagocitose e defesa imunológica).", "possui_imagem": false},
  {"id": 104, "uid": "CIEN-6-104", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Ação da Cafeína no Cérebro", "dificuldade": "Médio", "enunciado": "A cafeína, substância presente no café, chás e refrigerantes de cola, é amplamente consumida para afastar a sonolência e aumentar o estado de alerta. Em nível celular no cérebro, ela atua principalmente:", "alternativas": {"A": "Destruindo as sinapses entre os neurônios motores.", "B": "Bloqueando os receptores de adenosina (uma molécula que se acumula ao longo do dia e induz o sono), impedindo que ela avise ao cérebro que o corpo está cansado.", "C": "Congelando o bulbo raquidiano para desacelerar a respiração.", "D": "Aumentando a espessura do crânio para evitar lesões.", "E": "Substituindo a glicose como combustível exclusivo das células da glia."}, "resposta_correta": "B", "justificativa": "A adenosina liga-se a receptores neuronais promovendo relaxamento e sono. A cafeína tem estrutura semelhante e atua como antagonista competitivo desses receptores, impedindo a ação da adenosina e mantendo o estado de vigília.", "possui_imagem": false},
  {"id": 105, "uid": "CIEN-6-105", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Músculos Involuntários vs. Voluntários", "dificuldade": "Médio", "enunciado": "O sistema nervoso comanda diferentes tipos de tecidos musculares no organismo. Enquanto os músculos esqueléticos ligados aos ossos possuem contração voluntária (sob comando consciente), o músculo cardíaco do coração e a musculatura lisa dos órgãos digestórios possuem contração:", "alternativas": {"A": "Involuntária, controlada de forma automática pelo sistema nervoso autônomo sem necessidade de controle consciente.", "B": "Voluntária, dependendo da decisão consciente da pessoa a cada batimento cardíaco.", "C": "Exclusivamente mecânica, sem nenhuma intervenção de impulsos nervosos.", "D": "Esporádica, ocorrendo apenas durante o sono profundo.", "E": "Consciente apenas quando a pessoa pratica esportes."}, "resposta_correta": "A", "justificativa": "O músculo estriado cardíaco e os músculos lisos dos órgãos viscerais são inervados pelo sistema nervoso autônomo e respondem a estímulos hormonais e reflexos involuntários, garantindo funções vitais sem controle consciente.", "possui_imagem": false},
  {"id": 106, "uid": "CIEN-6-106", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Mecanismo Iônico do Impulso Nervoso", "dificuldade": "Difícil", "enunciado": "O impulso nervoso é uma onda de alteração elétrica que se propaga rapidamente pela membrana do axônio (potencial de ação). Em repouso, a membrana do neurônio é polarizada (positiva por fora e negativa por dentro). Quando um estímulo atinge o limiar de excitação, ocorre a despolarização inicial da membrana provocada pela:", "alternativas": {"A": "Saída em massa de elétrons livres para o sangue.", "B": "Abertura de canais de sódio que permitem a entrada rápida de íons sódio (Na+) com carga positiva para o interior da célula.", "C": "Entrada de moléculas de gordura da bainha de mielina no núcleo celular.", "D": "Destruição imediata da membrana plasmática do axônio.", "E": "Saída de todas as proteínas do citoplasma para o meio extracelular."}, "resposta_correta": "B", "justificativa": "A despolarização do axônio é deflagrada pela abertura de canais iônicos de sódio dependentes de voltagem; o afluxo de Na+ a favor de seu gradiente eletroquímico inverte temporariamente a polaridade da membrana.", "possui_imagem": false},
  {"id": 107, "uid": "CIEN-6-107", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Agentes Tóxicos e Bloqueio de Neurotransmissores", "dificuldade": "Difícil", "enunciado": "O veneno 'curare', utilizado tradicionalmente por indígenas na ponta de flechas para caça, e certos venenos de serpentes causam paralisia muscular flácida total e asfixia. Isso ocorre porque essas substâncias bloqueiam os receptores de acetilcolina na junção neuromuscular. A consequência celular desse bloqueio é:", "alternativas": {"A": "Os músculos se contraem tão fortemente que quebram os próprios ossos.", "B": "O impulso nervoso chega ao final do neurônio motor, mas o músculo não recebe o sinal químico para se contrair, resultando em paralisia dos músculos respiratórios como o diafragma.", "C": "O sangue para de coagular instantaneamente na circulação.", "D": "Os neurônios sensoriais da pele perdem a bainha de mielina em segundos.", "E": "O coração explode devido ao excesso de energia muscular."}, "resposta_correta": "B", "justificativa": "A acetilcolina é o neurotransmissor que deflagra a contração das fibras musculares esqueléticas. O bloqueio competitivo de seus receptores na placa motora impede a transmissão do estímulo excitatório, paralisando os músculos respiratórios.", "possui_imagem": false},
  {"id": 108, "uid": "CIEN-6-108", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Circuitos Neurais: Interneurônios no Arco Reflexo", "dificuldade": "Difícil", "enunciado": "Em muitos arcos reflexos protetores (como puxar o pé ao pisar em um espinho pontiagudo), o circuito neural envolve três tipos de neurônios: sensitivo, interneurônio (associativo) e motor. Qual é o papel biológico desempenhado pelo interneurônio no interior da substância cinzenta da medula espinhal?", "alternativas": {"A": "Conectar o sinal do neurônio sensitivo ao neurônio motor apropriado e, simultaneamente, enviar colaterais que sobem ao encéfalo para que a pessoa tome consciência do fato.", "B": "Produzir ossículos que absorvem o impacto mecânico do espinho.", "C": "Bombear sangue oxigenado para o pé machucado.", "D": "Impedir que a dor chegue à medula para não sobrecarregar o corpo.", "E": "Substituir o receptor mecânico da pele danificado pelo espinho."}, "resposta_correta": "A", "justificativa": "O interneurônio medular atua como estação integradora: ele retransmite o estímulo reflexo diretamente aos neurônios motores locais para a resposta motora imediata, enquanto vias colaterais ascendem ao cérebro para interpretação e memória do evento.", "possui_imagem": false},
  {"id": 109, "uid": "CIEN-6-109", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Mecanismo da Dopamina no Circuito de Recompensa", "dificuldade": "Difícil", "enunciado": "Drogas de alto poder de dependência (como a cocaína e a nicotina) sequestram o chamado 'circuito de recompensa cerebral' no encéfalo. Elas causam uma sensação artificial intensa de prazer principalmente porque:", "alternativas": {"A": "Aumentam temporariamente a disponibilidade do neurotransmissor dopamina nas fendas sinápticas de áreas encefálicas ligadas ao prazer e motivação.", "B": "Destroem o cerebelo e o bulbo nos primeiros cinco minutos de uso.", "C": "Aumentam a espessura da pele para evitar a dor física.", "D": "Transformam todos os neurônios do cérebro em células musculares.", "E": "Neutralizam a circulação sanguínea no sistema nervoso."}, "resposta_correta": "A", "justificativa": "A dopamina é o neurotransmissor central nas vias mesolímbicas de recompensa. Drogas como cocaína inibem a recaptação de dopamina, mantendo os receptores hiperestimulados e promovendo adaptações neuroplásticas que levam ao vício.", "possui_imagem": false},
  {"id": 110, "uid": "CIEN-6-110", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Perda Auditiva por Ruído e Células Ciliadas", "dificuldade": "Difícil", "enunciado": "O uso frequente de fones de ouvido em volume excessivo (acima de 85 decibéis) por longos períodos provoca perda auditiva neurossensorial irreversível. Por que esse tipo de surdez geralmente não tem cura?", "alternativas": {"A": "Porque o tímpano se transforma em osso maciço.", "B": "Porque a exposição prolongada a sons intensos danifica e mata as células ciliadas da cóclea, que não se regeneram em seres humanos.", "C": "Porque o pavilhão auricular cai da cabeça com o excesso de vibração.", "D": "Porque a tuba auditiva fecha permanentemente o canal nasal.", "E": "Porque o cérebro esquece o idioma que a pessoa escutava."}, "resposta_correta": "B", "justificativa": "As células ciliadas da cóclea humana são mecanorreceptores altamente especializados que não realizam divisão celular nem se regeneram após a morte provocada por trauma acústico contínuo.", "possui_imagem": false},
  {"id": 111, "uid": "CIEN-6-111", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Cinestesia e Propriocepção", "dificuldade": "Difícil", "enunciado": "Mesmo de olhos completamente fechados no escuro, somos capazes de saber com precisão se nosso braço está esticado ou dobrado, ou se estamos em pé ou sentados. Esse sentido corporal interno é a propriocepção (ou cinestesia), cujos receptores específicos encontram-se localizados em:", "alternativas": {"A": "Músculos, tendões e cápsulas articulares (fusos musculares e órgãos tendinosos de Golgi).", "B": "Papilas gustativas da ponta da língua.", "C": "Teto da cavidade nasal junto ao bulbo olfatório.", "D": "Córnea e íris do olho.", "E": "Canais lacrimais e glândulas salivares."}, "resposta_correta": "A", "justificativa": "Os proprioceptores (como fusos neuromusculares e órgãos tendíneos de Golgi) monitoram constantemente o grau de estiramento muscular, a tensão nos tendões e a angulação das articulações, informando a posição corporal ao SNC.", "possui_imagem": false},
  {"id": 112, "uid": "CIEN-6-112", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Síndrome de Abstinência", "dificuldade": "Difícil", "enunciado": "Quando um indivíduo dependente de álcool ou sedativos interrompe abruptamente o uso da substância, ele pode apresentar tremores intensos, taquicardia, sudorese, alucinações e convulsões (síndrome de abstinência). A causa fisiológica desse quadro é:", "alternativas": {"A": "A falta de água nos rins causada pela interrupção da bebida.", "B": "Um estado de hiperexcitabilidade de rebote do sistema nervoso central, que havia reduzido seus próprios mecanismos inibitórios para compensar a depressão constante causada pela droga.", "C": "A entrada de ar atmosférico dentro da caixa craniana.", "D": "A transformação do sangue venoso em ácido clorídrico.", "E": "A destruição total dos nervos periféricos durante o repouso."}, "resposta_correta": "B", "justificativa": "Para manter a homeostase contra a sedação crônica da droga, o cérebro diminui receptores inibitórios (como GABA) e aumenta receptores excitatórios (como glutamato). Sem a droga depressora, o sistema entra em hiperatividade descontrolada (efeito rebote).", "possui_imagem": false},
  {"id": 113, "uid": "CIEN-6-113", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Placidez e Rigidez: Toxina Botulínica e Tétano", "dificuldade": "Difícil", "enunciado": "A toxina botulínica impede a liberação de acetilcolina nas sinapses neuromusculares, causando paralisia flácida (músculos moles). Já a toxina tetânica bloqueia a liberação de neurotransmissores inibitórios na medula, gerando paralisia espástica (músculos contraídos e travados). A comparação desses dois mecanismos demonstra que:", "alternativas": {"A": "O sistema nervoso precisa apenas de sinais excitatórios para funcionar.", "B": "O controle muscular e a movimentação normal dependem do equilíbrio preciso entre sinais estimulatórios e sinais inibitórios no sistema nervoso.", "C": "As toxinas bacterianas alimentam os neurônios para gerar força excessiva.", "D": "Todos os neurotransmissores do corpo humano causam contração muscular contínua.", "E": "Os músculos esqueléticos se movem sem nenhuma influência de neurotransmissores."}, "resposta_correta": "B", "justificativa": "O funcionamento motor coordenado exige tanto a excitação das vias motoras quanto a inibição ativa de músculos antagonistas; o desequilíbrio por ausência de excitação gera paralisia flácida e por ausência de inibição gera contrações tetânicas sustentadas.", "possui_imagem": false},
  {"id": 114, "uid": "CIEN-6-114", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Barreira Hematoencefálica", "dificuldade": "Difícil", "enunciado": "Os vasos sanguíneos que irrigam o encéfalo humano possuem endotélio com junções de oclusão extremamente unidas, envolvidas por prolongamentos de astrócitos (barreira hematoencefálica). Essa estrutura biológica tem a função de:", "alternativas": {"A": "Impedir que o oxigênio e a glicose cheguem aos neurônios encefálicos.", "B": "Proteger o tecido cerebral sensível contra toxinas, patógenos e variações bruscas de substâncias presentes na corrente sanguínea.", "C": "Transformar sangue arterial em linfa auditiva continuamente.", "D": "Substituir as meninges na sustentação mecânica dos ossos do crânio.", "E": "Permitir que qualquer vírus entre livremente no cérebro."}, "resposta_correta": "B", "justificativa": "A barreira hematoencefálica atua como um filtro fisiológico seletivo, permitindo a passagem de nutrientes essenciais (glicose, O2) e pequenas moléculas lipossolúveis, enquanto barra macromoléculas polares, bactérias e substâncias neurotóxicas do sangue.", "possui_imagem": false},
  {"id": 115, "uid": "CIEN-6-115", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Potencial de Ação e Lei do Tudo ou Nada", "dificuldade": "Difícil", "enunciado": "Na fisiologia do neurônio, o disparo de um potencial de ação obedece à 'Lei do Tudo ou Nada'. Isso significa que:", "alternativas": {"A": "Se o estímulo não atingir o limiar mínimo, o potencial de ação não é gerado; se atingir ou superar o limiar, o potencial de ação ocorre com amplitude máxima e constante.", "B": "Estímulos mais fortes geram impulsos elétricos com voltagem muito maior do que estímulos fracos.", "C": "O neurônio descarrega impulsos apenas quando todo o corpo humano está em movimento.", "D": "O impulso viaja de forma alternada, ora pelo axônio, ora pela corrente sanguínea.", "E": "Se o neurônio disparar uma vez, ele é consumido e morre logo em seguida."}, "resposta_correta": "A", "justificativa": "O potencial de ação é uma resposta estereotipada: uma vez atingido o limiar de despolarização, ele é disparado integralmente com magnitude constante; a intensidade do estímulo original é codificada pela frequência de disparos, e não pela voltagem do pico.", "possui_imagem": false},
  {"id": 116, "uid": "CIEN-6-116", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Reflexo Pupilar e Tronco Encefálico", "dificuldade": "Difícil", "enunciado": "Ao incidir uma lanterna acesa nos olhos de uma pessoa em ambiente escuro, a pupila se contrai rapidamente (miose). Esse reflexo fotomotor pupilar é mediado pelo tronco encefálico e por nervos cranianos. A importância clínica de testar esse reflexo em pacientes desacordados após traumatismo craniano é:", "alternativas": {"A": "Avaliar se o paciente possui bom grau de alfabetização.", "B": "Verificar a integridade funcional do tronco encefálico e das vias neurais básicas em situações de coma ou emergência neurológica.", "C": "Medir a quantidade de cálcio presente nos ossos da face.", "D": "Checar se os dentes do paciente sofreram fraturas no acidente.", "E": "Testar se os receptores gustativos da língua ainda funcionam."}, "resposta_correta": "B", "justificativa": "O reflexo pupilar é mediado pelo nervo óptico (aferente), núcleos no mesencéfalo e nervo oculomotor (eferente parassimpático). Sua ausência ou assimetria é um sinal crítico de compressão do tronco encefálico ou lesão neurológica grave.", "possui_imagem": false},
  {"id": 117, "uid": "CIEN-6-117", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Plasticidade Neural", "dificuldade": "Difícil", "enunciado": "Pacientes que sofrem um acidente vascular cerebral (AVC) e perdem os movimentos de um lado do corpo frequentemente conseguem recuperar parte significativa das funções motoras após meses de fisioterapia intensiva. A capacidade biológica do sistema nervoso de reorganizar suas conexões neurais e formar novas sinapses em resposta ao aprendizado e reabilitação é chamada de:", "alternativas": {"A": "Mielinização reversa.", "B": "Neuroplasticidade (ou plasticidade neural).", "C": "Arco reflexo crônico.", "D": "Fadiga neuromuscular congênita.", "E": "Atrofia cerebral progressiva."}, "resposta_correta": "B", "justificativa": "A neuroplasticidade é a propriedade do sistema nervoso de remodelar sua estrutura e conexões sinápticas ao longo da vida, permitindo aprendizado, consolidação de memórias e recuperação de déficits após lesões encefálicas.", "possui_imagem": false},
  {"id": 118, "uid": "CIEN-6-118", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Integração Sensorial: Quimioestesia e Pimenta", "dificuldade": "Difícil", "enunciado": "A sensação ardente e picante provocada pelo consumo de pimenta (capsaicina) não é detectada pelas papilas gustativas de sabores, mas sim por receptores térmicos de calor e dor (TRPV1) inervados pelo nervo trigêmeo na boca. Por essa razão, ao comer uma pimenta muito forte, o corpo reage com:", "alternativas": {"A": "Sensação de congelamento e tremor muscular pelo frio.", "B": "Sensação ilusória de queimação, sudorese e aumento da salivação, pois o cérebro interpreta o estímulo como calor perigoso real.", "C": "Perda temporária de todos os ossos da mandíbula.", "D": "Crescimento instantâneo de pelos na língua.", "E": "Destruição imediata das células do cerebelo."}, "resposta_correta": "B", "justificativa": "A capsaicina liga-se aos receptores TRPV1, os mesmos canais ativados por temperaturas superiores a 43 ºC (calor lesivo). O cérebro interpreta o sinal como queimadura térmica, deflagrando respostas de vasodilatação e sudorese.", "possui_imagem": false},
  {"id": 119, "uid": "CIEN-6-119", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Mielinização e Doenças Desmielinizantes", "dificuldade": "Difícil", "enunciado": "Na esclerose múltipla, o próprio sistema imunológico do indivíduo ataca e destrói partes da bainha de mielina dos axônios no SNC. Como consequência celular direta desse processo autoimune:", "alternativas": {"A": "A velocidade de condução dos impulsos nervosos cai drasticamente ou o sinal é bloqueado, gerando déficits motores, visuais e sensoriais.", "B": "Os ossos do esqueleto se tornam mais flexíveis que a cartilagem.", "C": "O sangue arterial para de transportar gás oxigênio aos tecidos.", "D": "A pele deixa de produzir células queratinizadas.", "E": "O estômago passa a produzir suco pancreático na boca."}, "resposta_correta": "A", "justificativa": "A perda da bainha de mielina compromete o isolamento elétrico e a condução saltatória nos nós de Ranvier, causando dissipação da corrente, retardo na velocidade do impulso ou falha completa de transmissão axonal.", "possui_imagem": false},
  {"id": 120, "uid": "CIEN-6-120", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Alavancas Biomecânicas no Sistema Locomotor", "dificuldade": "Difícil", "enunciado": "No movimento de elevação do corpo sobre a ponta dos pés (ao apoiar os dedos no chão para alcançar um objeto alto), o ponto de apoio (fulcro) fica na ponta dos pés, a força de resistência é o peso corporal aplicado através do tornozelo, e a força potente é aplicada pelo músculo da panturrilha através do tendão de Aquiles. Essa configuração biomecânica é um exemplo de alavanca:", "alternativas": {"A": "Interfixa (de primeira classe).", "B": "Inter-resistente (de segunda classe), onde a resistência fica entre o ponto de apoio e a força potente.", "C": "Interpotente (de terceira classe), que sempre perde vantagem mecânica de força.", "D": "Magnética sem atrito ósseo.", "E": "Hidráulica pura sem intervenção esquelética."}, "resposta_correta": "B", "justificativa": "Ao ficar na ponta dos pés, o apoio está nas articulações metatarsofalângicas, a resistência (peso corporal) atua no meio (tíbia/tálus) e a potência atua posteriormente (tríceps sural via tendão calcâneo), configurando alavanca inter-resistente com vantagem mecânica de força.", "possui_imagem": false},
  {"id": 121, "uid": "CIEN-6-121", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Ilusão Tátil de Weber e Densidade Receptiva", "dificuldade": "Difícil", "enunciado": "Ao deslizar as duas pontas de um compasso com abertura constante sobre a pele, partindo do antebraço e chegando até a palma da mão e a ponta dos dedos, a pessoa tem a nítida sensação de que as pontas do compasso estão se afastando e se tornando mais distantes entre si. Essa ilusão sensorial é explicada por:", "alternativas": {"A": "A deformação física da ferramenta de metal pelo calor da mão.", "B": "O aumento progressivo na densidade de mecanorreceptores e na resolução cortical à medida que se aproxima das extremidades dos dedos, fazendo com que mais receptores independentes sejam estimulados simultaneamente.", "C": "A perda da capacidade de raciocínio da pessoa durante o teste.", "D": "O arrefecimento do antebraço em relação aos dedos da mão.", "E": "A presença de células olfatórias na palma da mão."}, "resposta_correta": "B", "justificativa": "Na ilusão de Weber, como os campos receptivos na ponta dos dedos são muito menores e mais densos do que no antebraço, um estímulo com a mesma distância física estimula proporcionalmente mais campos corticais distintos, dando a percepção subjetiva de maior distância.", "possui_imagem": false},
  {"id": 122, "uid": "CIEN-6-122", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Equilíbrio Estático vs. Dinâmico na Orelha Interna", "dificuldade": "Difícil", "enunciado": "A orelha interna detecta dois tipos de equilíbrio: o equilíbrio dinâmico (rotação da cabeça) e o equilíbrio estático (aceleração linear e gravidade, como em um elevador ou carro arrancando). As estruturas responsáveis por detectar, respectivamente, rotações angulares e acelerações lineares são:", "alternativas": {"A": "Canais semicirculares e órgãos otolíticos (utrículo e sáculo).", "B": "Tímpano e pavilhão auricular.", "C": "Cóclea e tuba auditiva.", "D": "Martelo e bigorna.", "E": "Estribo e membrana basilar."}, "resposta_correta": "A", "justificativa": "Os três canais semicirculares orientados nos eixos tridimensionais captam acelerações angulares (rotações). O utrículo e o sáculo contêm otólitos (cristais de carbonato de cálcio) sobre uma membrana gelatinosa que detectam a gravidade e acelerações lineares (equilíbrio estático).", "possui_imagem": false},
  {"id": 123, "uid": "CIEN-6-123", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Efeito da Nicotina no Sistema Cardiovascular e Nervoso", "dificuldade": "Difícil", "enunciado": "A nicotina atua ligando-se a receptores colinérgicos nicotínicos no sistema nervoso central e periférico. Além de liberar dopamina nas vias de recompensa, ela estimula a medula da glândula adrenal a liberar adrenalina no sangue. Essa liberação hormonal secundária provoca:", "alternativas": {"A": "Queda drástica da pressão arterial e bradicardia profunda imediata.", "B": "Aumento da frequência cardíaca, elevação da pressão arterial e vasoconstrição periférica, sobrecarregando o sistema cardiovascular.", "C": "Relaxamento completo de todos os vasos sanguíneos e sonolência contínua.", "D": "Eliminação de todo o colesterol presente no organismo.", "E": "Crescimento acelerado dos dentes e unhas."}, "resposta_correta": "B", "justificativa": "A estimulação simpática provocada pela nicotina e pela liberação de adrenalina gera taquicardia, aumento da resistência vascular periférica e hipertensão momentânea, sendo um dos principais fatores de risco para infartos e derrames em fumantes.", "possui_imagem": false},
  {"id": 124, "uid": "CIEN-6-124", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Processamento Central da Gustação e Olfato no Córtex", "dificuldade": "Difícil", "enunciado": "Diferente da maioria dos outros sentidos humanos (como visão, audição e tato), que passam obrigatoriamente por uma estação de retransmissão no tálamo antes de atingir o córtex cerebral primário, as vias do sentido do olfato possuem uma via direta com o sistema límbico (amígdala e hipocampo). Essa particularidade anatômica explica por que:", "alternativas": {"A": "Os odores são os únicos estímulos que conseguem quebrar ossos do crânio.", "B": "Determinados cheiros são capazes de evocar memórias emocionais vívidas e nostálgicas de forma quase instantânea e inconsciente.", "C": "O olfato é o sentido mais fraco e menos desenvolvido de todos os vertebrados.", "D": "O nariz humano não consegue sentir o cheiro de comida quente.", "E": "As pessoas cegas perdem completamente o olfato nos primeiros meses de vida."}, "resposta_correta": "B", "justificativa": "As projeções diretas do trato olfatório para a amígdala (emoções) e hipocampo (memória), contornando o filtro talâmico inicial, conferem ao olfato um elo neurobiológico singular com memórias afetivas profundas e respostas emocionais imediatas.", "possui_imagem": false},
  {"id": 125, "uid": "CIEN-6-125", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Inibição Lateral no Sistema Nervoso", "dificuldade": "Difícil", "enunciado": "Quando uma pequena ponta de agulha toca a pele, o neurônio sensorial mais central dispara em frequência máxima, mas neurônios vizinhos ligeiramente estimulados são ativamente inibidos por interneurônios inibitórios locais. Esse mecanismo de 'inibição lateral' tem como função essencial:", "alternativas": {"A": "Aumentar a dor até que o indivíduo desmaie.", "B": "Aumentar o contraste e a precisão espacial na localização exata do estímulo tátil no cérebro.", "C": "Impedir que qualquer impulso elétrico chegue à medula espinhal.", "D": "Transformar o estímulo mecânico em luz fluorescente na pele.", "E": "Fazer com que a pele ao redor da picada pare de sangrar imediatamente."}, "resposta_correta": "B", "justificativa": "A inibição lateral é um princípio computacional biológico do sistema nervoso que silencia sinais colaterais mais fracos ao redor do ponto de estimulação máxima, acentuando as bordas e a acuidade espacial da percepção sensorial.", "possui_imagem": false},
  {"id": 126, "uid": "CIEN-6-126", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 15: Sistema Nervoso e Sentidos", "tema": "Integração Neuro-Músculo-Esquelética: Reflexo Miomático e Tônus", "dificuldade": "Difícil", "enunciado": "Mesmo quando estamos sentados em repouso absoluto, nossos músculos esqueléticos posturais mantêm um estado contínuo de contração parcial involuntária chamado 'tônus muscular'. O tônus muscular é sustentado permanentemente por:", "alternativas": {"A": "Disparos assíncronos e contínuos de neurônios motores na medula espinhal ativados por sinais dos fusos neuromusculares e do cerebelo.", "B": "Rigidez provocada pelo congelamento das proteínas musculares em repouso.", "C": "Circulação de toxinas alimentares que travam as fibras de actina e miosina.", "D": "Falta total de oxigênio nas células musculares durante o dia.", "E": "Pressão da gravidade que esmaga os músculos contra as vértebras."}, "resposta_correta": "A", "justificativa": "O tônus muscular é mantido por arcos reflexos espinhais contínuos monitorados pelos fusos musculares e coordenados pelo cerebelo e tronco encefálico, assegurando a postura e preparando o músculo para respostas rápidas sem que haja fadiga extrema.", "possui_imagem": false},
  {"id": 127, "uid": "CIEN-6-127", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Anatomia Ocular: Pupila e Íris", "dificuldade": "Fácil", "enunciado": "Ao entrar em um quarto escuro, a abertura circular no centro do olho por onde a luz penetra aumenta de tamanho para permitir maior entrada de luminosidade. Essa abertura e o anel colorido que a controla são chamados, respectivamente, de:", "alternativas": {"A": "Retina e córnea.", "B": "Pupila e íris.", "C": "Cristalino e esclera.", "D": "Nervo óptico e humor vítreo.", "E": "Pálpebra e conjuntiva."}, "resposta_correta": "B", "justificativa": "A pupila é o orifício central de entrada de luz e a íris é a estrutura muscular pigmentada (que dá cor aos olhos) responsável por controlar o diâmetro da pupila.", "possui_imagem": true},
  {"id": 128, "uid": "CIEN-6-128", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Anatomia Ocular: Meios Transparentes", "dificuldade": "Fácil", "enunciado": "A membrana transparente situada na parte mais externa e anterior do globo ocular, que funciona como a primeira lente do olho e protege as estruturas internas, é a:", "alternativas": {"A": "Córnea.", "B": "Retina.", "C": "Esclera.", "D": "Coroide.", "E": "Fóvea."}, "resposta_correta": "A", "justificativa": "A córnea é a camada transparente convexa anterior do olho humano, responsável pela maior parte da refração inicial da luz que penetra no globo ocular.", "possui_imagem": true},
  {"id": 129, "uid": "CIEN-6-129", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Anatomia Ocular: Cristalino", "dificuldade": "Fácil", "enunciado": "No interior do olho humano, logo atrás da íris, existe uma lente natural transparente e flexível que altera sua forma para focar objetos próximos ou distantes. Essa estrutura é o:", "alternativas": {"A": "Cristalino (ou lente).", "B": "Nervo óptico.", "C": "Bastonete.", "D": "Ponto cego.", "E": "Humor aquoso."}, "resposta_correta": "A", "justificativa": "O cristalino é a lente biológica biconvexa que realiza a acomodação visual, ajustando a distância focal pela ação dos músculos ciliares.", "possui_imagem": true},
  {"id": 130, "uid": "CIEN-6-130", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Receptores Visuais: Retina", "dificuldade": "Fácil", "enunciado": "A camada interna no fundo do olho que funciona como a tela onde as imagens são formadas e que contém as células sensíveis à luz (fotorreceptores) é a:", "alternativas": {"A": "Esclera.", "B": "Retina.", "C": "Íris.", "D": "Córnea.", "E": "Pupila."}, "resposta_correta": "B", "justificativa": "A retina é o tecido neurossensorial que reveste o fundo do olho, transformando estímulos luminosos em impulsos elétricos encaminhados ao cérebro.", "possui_imagem": true},
  {"id": 131, "uid": "CIEN-6-131", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Fotorreceptores: Cones e Bastonetes", "dificuldade": "Fácil", "enunciado": "Na retina existem dois tipos de células fotorreceptoras. As células responsáveis pela visão das cores e por detalhes nítidos sob boa iluminação e as células responsáveis pela visão em preto e branco sob baixa luminosidade são, respectivamente:", "alternativas": {"A": "Cones e bastonetes.", "B": "Bastonetes e cones.", "C": "Neurônios e glóbulos brancos.", "D": "Cristalinos e pupilas.", "E": "Miócitos e condrócitos."}, "resposta_correta": "A", "justificativa": "Os cones são fotorreceptores ativados em condições de claridade (visão fotópica) que distinguem cores; os bastonetes são extremamente sensíveis à luz e operam na penumbra (visão escotópica), sem distinguir cores.", "possui_imagem": true},
  {"id": 132, "uid": "CIEN-6-132", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Formação da Imagem no Olho", "dificuldade": "Fácil", "enunciado": "A imagem projetada pelos raios de luz na retina de um olho humano com visão normal é:", "alternativas": {"A": "Direita, virtual e do mesmo tamanho do objeto.", "B": "Invertida, real e menor que o objeto original.", "C": "Inclinada e com as cores invertidas pelo cristalino.", "D": "Apenas em preto e branco, sendo colorida pelas pálpebras.", "E": "Maior que o objeto original e projetada fora do olho."}, "resposta_correta": "B", "justificativa": "As propriedades ópticas convergentes da córnea e do cristalino produzem na retina uma imagem real, invertida (de cabeça para baixo) e menor do que o objeto observado; o cérebro posteriormente processa e desinverte essa imagem.", "possui_imagem": false},
  {"id": 133, "uid": "CIEN-6-133", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Comunicação com o Cérebro: Nervo Óptico", "dificuldade": "Fácil", "enunciado": "Os impulsos nervosos elétricos gerados na retina são transmitidos ao cérebro para serem interpretados como imagens através de qual via nervosa?", "alternativas": {"A": "Nervo ciático.", "B": "Nervo óptico.", "C": "Medula óssea.", "D": "Tuba auditiva.", "E": "Nervo olfatório."}, "resposta_correta": "B", "justificativa": "O nervo óptico (segundo par de nervos cranianos) reúne os axônios das células ganglionares da retina e conduz os sinais visuais até o córtex visual occipital no cérebro.", "possui_imagem": false},
  {"id": 134, "uid": "CIEN-6-134", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Tipos de Lentes: Convergentes", "dificuldade": "Fácil", "enunciado": "Uma lente de vidro que é mais espessa no centro e tem bordas finas, capaz de concentrar os raios de luz paralelos que a atravessam em um único ponto focal (como uma lupa), é classificada como:", "alternativas": {"A": "Lente convergente.", "B": "Lente divergente.", "C": "Espelho plano.", "D": "Lente plana sem curvatura.", "E": "Prisma opaco."}, "resposta_correta": "A", "justificativa": "Lentes de bordas finas (biconvexas, plano-convexas) em meio aéreo fazem os raios luminosos incidentes convergirem para um foco real, sendo denominadas lentes convergentes.", "possui_imagem": true},
  {"id": 135, "uid": "CIEN-6-135", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Tipos de Lentes: Divergentes", "dificuldade": "Fácil", "enunciado": "Uma lente que apresenta bordas mais grossas e centro mais fino, fazendo com que os raios paralelos de luz se espalhem e se afastem ao atravessá-la, é denominada:", "alternativas": {"A": "Lente convergente.", "B": "Lente divergente.", "C": "Lente cilíndrica de aumento.", "D": "Espelho esférico côncavo.", "E": "Filtro polarizador."}, "resposta_correta": "B", "justificativa": "Lentes de bordas grossas (bicôncavas, plano-côncavas) provocam o espalhamento (divergência) dos raios de luz refratados, sendo chamadas de lentes divergentes.", "possui_imagem": true},
  {"id": 136, "uid": "CIEN-6-136", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Defeitos da Visão: Miopia", "dificuldade": "Fácil", "enunciado": "Um estudante que tem dificuldade para enxergar com nitidez as anotações do professor na lousa ao fundo da sala de aula, mas lê livros bem de perto sem nenhum esforço, provavelmente tem:", "alternativas": {"A": "Miopia.", "B": "Hipermetropia.", "C": "Estrabismo.", "D": "Conjuntivite.", "E": "Glaucoma."}, "resposta_correta": "A", "justificativa": "A miopia caracteriza-se pela dificuldade em focalizar objetos distantes, mantendo-se a boa visão para objetos próximos.", "possui_imagem": true},
  {"id": 137, "uid": "CIEN-6-137", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Correção da Miopia", "dificuldade": "Fácil", "enunciado": "Para corrigir a miopia e permitir que a pessoa enxergue com clareza objetos distantes, os oftalmologistas receitam óculos com lentes do tipo:", "alternativas": {"A": "Convergentes.", "B": "Divergentes.", "C": "Planos sem grau.", "D": "Bifocais opacas.", "E": "Espelhadas reflexivas."}, "resposta_correta": "B", "justificativa": "Como no olho míope a imagem se forma antes da retina (convergência excessiva ou globo ocular longo), utilizam-se lentes divergentes para espalhar ligeiramente os raios de luz antes de atingirem a córnea, deslocando o foco para a retina.", "possui_imagem": true},
  {"id": 138, "uid": "CIEN-6-138", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Defeitos da Visão: Hipermetropia", "dificuldade": "Fácil", "enunciado": "A pessoa que enxerga com facilidade paisagens distantes na estrada, mas sente cansaço visual, dor de cabeça e visão embaçada ao tentar ler letras pequenas de perto em um livro, apresenta:", "alternativas": {"A": "Hipermetropia.", "B": "Miopia.", "C": "Catarata precoce.", "D": "Daltonismo congênito.", "E": "Ponto cego expandido."}, "resposta_correta": "A", "justificativa": "A hipermetropia caracteriza-se pela dificuldade de focalizar objetos próximos, enquanto objetos distantes são vistos com relativa nitidez.", "possui_imagem": true},
  {"id": 139, "uid": "CIEN-6-139", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Correção da Hipermetropia", "dificuldade": "Fácil", "enunciado": "A hipermetropia é corrigida pelo uso de óculos ou lentes de contato do tipo:", "alternativas": {"A": "Divergentes.", "B": "Convergentes.", "C": "Cilíndricas neutras.", "D": "Completamente escuras.", "E": "Lentes de aumento divergentes."}, "resposta_correta": "B", "justificativa": "No olho hipermétrope, o globo ocular é mais curto ou a refração é fraca, fazendo a imagem se formar teoricamente atrás da retina. A lente convergente soma convergência aos raios de luz, adiantando o foco para sobre a retina.", "possui_imagem": true},
  {"id": 140, "uid": "CIEN-6-140", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Presbiopia ou Vista Cansada", "dificuldade": "Fácil", "enunciado": "É muito comum pessoas com mais de 40 a 45 anos começarem a afastar o jornal, cardápios ou o celular para conseguir ler o texto. Essa perda gradual da capacidade de focar de perto associada ao envelhecimento natural do olho é chamada de:", "alternativas": {"A": "Miopia congênita.", "B": "Presbiopia (vista cansada).", "C": "Daltonismo tardio.", "D": "Astigmatismo juvenil.", "E": "Descolamento de córnea."}, "resposta_correta": "B", "justificativa": "A presbiopia decorre da perda progressiva de elasticidade do cristalino e da diminuição da força dos músculos ciliares ao longo dos anos, prejudicando a acomodação para perto.", "possui_imagem": true},
  {"id": 141, "uid": "CIEN-6-141", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Patologias Oculares: Catarata", "dificuldade": "Fácil", "enunciado": "A catarata é uma condição visual frequente em idosos que deixa a visão progressivamente nublada, como se a pessoa estivesse olhando através de um vidro embaçado. Essa doença é causada por:", "alternativas": {"A": "Quebra dos ossículos da orelha média.", "B": "Perda de transparência (opacificação) do cristalino.", "C": "Destruição do nervo óptico por bactérias.", "D": "Mudança definitiva da cor da íris para preto.", "E": "Perfuração mecânica da córnea."}, "resposta_correta": "B", "justificativa": "A catarata consiste na opacificação do cristalino devido à alteração nas proteínas da lente, impedindo a passagem nítida dos raios de luz até a retina.", "possui_imagem": false},
  {"id": 142, "uid": "CIEN-6-142", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Causas e Características do Daltonismo", "dificuldade": "Fácil", "enunciado": "O daltonismo é uma alteração visual de origem genética e hereditária na qual o indivíduo apresenta dificuldade para distinguir certas cores, mais comumente entre:", "alternativas": {"A": "Preto e branco.", "B": "Vermelho e verde.", "C": "Amarelo e dourado.", "D": "Azul e roxo escuro.", "E": "Prata e cinza."}, "resposta_correta": "B", "justificativa": "O daltonismo (discromatopsia) decorre de anomalias nos pigmentos visuais de determinados tipos de cones na retina, sendo a confusão entre tons de vermelho e verde a forma mais prevalente.", "possui_imagem": false},
  {"id": 143, "uid": "CIEN-6-143", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "O Ponto Cego do Olho", "dificuldade": "Fácil", "enunciado": "Existe uma pequena região no fundo da retina humana onde não somos capazes de detectar nenhum raio de luz, chamada de 'ponto cego'. Esse ponto existe porque:", "alternativas": {"A": "É o local exato onde o nervo óptico se conecta e sai da retina, não havendo fotorreceptores (cones ou bastonetes) nessa área.", "B": "A íris projeta uma sombra permanente sobre aquele pedaço da retina.", "C": "O sangue arterial queima os neurônios daquela região durante a infância.", "D": "A córnea não consegue focar a luz azul no centro do olho.", "E": "O cérebro desliga a visão daquele ponto para economizar energia."}, "resposta_correta": "A", "justificativa": "O disco óptico (ponto cego) é o ponto de convergência de todos os axônios das células ganglionares para formar o nervo óptico; como não há cones nem bastonetes nessa região, qualquer luz que incida ali não é captada.", "possui_imagem": true},
  {"id": 144, "uid": "CIEN-6-144", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Higiene e Saúde Ocular: Conjuntivite", "dificuldade": "Fácil", "enunciado": "A conjuntivite é uma inflamação frequente nos olhos caracterizada por vermelhidão, coceira, sensação de areia e secreção amarelada. Uma medida básica essencial para prevenir o contágio da conjuntivite infecciosa é:", "alternativas": {"A": "Lavar frequentemente as mãos e evitar compartilhar toalhas de rosto e maquiagens.", "B": "Olhar diretamente para lâmpadas ultravioleta acesas.", "C": "Usar óculos escuros de pessoas doentes para proteger a vista.", "D": "Esfregar os olhos com força sempre que sentir coceira.", "E": "Ficar sem piscar os olhos durante o dia."}, "resposta_correta": "A", "justificativa": "A conjuntivite bacteriana e viral é transmitida pelo contato direto com secreções oculares através de mãos contaminadas e objetos de uso compartilhado. A higiene das mãos e não compartilhar toalhas é a principal prevenção.", "possui_imagem": false},
  {"id": 145, "uid": "CIEN-6-145", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Luz e Refração no Cotidiano", "dificuldade": "Fácil", "enunciado": "Ao colocar um canudinho ou uma colher dentro de um copo de vidro transparente com água, quem olha de lado tem a nítida impressão de que o canudo está quebrado ou torto na superfície da água. Esse fenômeno é causado pela:", "alternativas": {"A": "Reflexão total da luz no vidro.", "B": "Refração da luz, que sofre mudança de velocidade e desvio na trajetória ao passar do ar para a água.", "C": "Decomposição da luz em um arco-íris invisível.", "D": "Dilatação térmica instantânea do plástico do canudo.", "E": "Absorção de 100% da luz pela água líquida."}, "resposta_correta": "B", "justificativa": "A refração ocorre quando a luz passa de um meio transparente para outro com diferente densidade óptica (do ar para a água), sofrendo alteração de velocidade e desvio em sua direção de propagação, gerando a ilusão de quebra.", "possui_imagem": true},
  {"id": 146, "uid": "CIEN-6-146", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Proteção Natural dos Olhos", "dificuldade": "Fácil", "enunciado": "O olho humano conta com estruturas anexas fundamentais para sua proteção e lubrificação diária. As pálpebras, os cílios e as glândulas lacrimais têm como funções principais, respectivamente:", "alternativas": {"A": "Focar objetos, filtrar cores e produzir a esclera.", "B": "Espalhar lágrimas ao piscar, reter poeira/partículas do ar e produzir fluido lubrificante e bactericida.", "C": "Aumentar o grau dos óculos, dilatar a pupila e absorver luz solar.", "D": "Conectar o olho ao cérebro, mudar a cor da íris e resfriar a córnea.", "E": "Substituir o cristalino quando este envelhece."}, "resposta_correta": "B", "justificativa": "As pálpebras protegem mecanicamente e distribuem o filme lacrimal; os cílios barram a entrada de poeira e partículas suspensas no ar; e a lágrima contém lisozima, lubrificando e protegendo quimicamente o olho.", "possui_imagem": false},
  {"id": 147, "uid": "CIEN-6-147", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Ilusões de Óptica e Cinema", "dificuldade": "Fácil", "enunciado": "Quando assistimos a um filme no cinema ou a uma animação na televisão, temos a nítida sensação de ver pessoas se movendo de forma contínua e suave, quando na verdade estamos vendo uma rápida sucessão de fotos estáticas (cerca de 24 a 60 quadros por segundo). Esse efeito se deve a uma característica da visão humana chamada:", "alternativas": {"A": "Ponto cego estendido.", "B": "Persistência retiniana (ou persistência da visão).", "C": "Fadiga permanente dos cones.", "D": "Miopia temporária do cérebro.", "E": "Refração excessiva da luz projetada."}, "resposta_correta": "B", "justificativa": "A persistência retiniana faz com que uma imagem permaneça gravada na retina e na memória sensorial por uma fração de segundo (cerca de 1/16 s). A projeção de quadros estáticos em alta velocidade faz com que as imagens se fundam na mente, criando a percepção de movimento contínuo.", "possui_imagem": false},
  {"id": 148, "uid": "CIEN-6-148", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Mecanismo da Acomodação Visual", "dificuldade": "Médio", "enunciado": "Para que possamos alternar o foco da leitura de um livro a 25 cm de distância para uma árvore situada a 50 metros de distância, o olho realiza a acomodação visual. O que acontece com os músculos ciliares e com o cristalino ao olharmos para um objeto próximo?", "alternativas": {"A": "Os músculos ciliares relaxam e o cristalino fica mais fino e achatado.", "B": "Os músculos ciliares se contraem, afrouxando os ligamentos suspensores e fazendo o cristalino ficar mais espesso e curvo, aumentando sua convergência.", "C": "O cristalino sai temporariamente de trás da íris e vai para a frente da córnea.", "D": "A retina se move fisicamente para a frente do globo ocular.", "E": "A pupila se fecha completamente impedindo a passagem de luz."}, "resposta_correta": "B", "justificativa": "Na visão de perto, os músculos ciliares se contraem, reduzindo a tensão na zônula de Zinn; com isso, a elasticidade intrínseca do cristalino faz com que ele se torne mais convexo e espesso, encurtando a distância focal para convergir os raios divergentes de objetos próximos.", "possui_imagem": false},
  {"id": 149, "uid": "CIEN-6-149", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Causa Óptica da Miopia", "dificuldade": "Médio", "enunciado": "Em um olho míope não corrigido, os raios de luz provenientes de um objeto situado no infinito (distante) entram paralelamente e:", "alternativas": {"A": "Convergem e formam o foco exatamente sobre a retina.", "B": "Convergem precocemente, formando a imagem nítida antes (na frente) da retina, de modo que a luz chega à retina já desfocada.", "C": "Não sofrem refração e atravessam o fundo do crânio em linha reta.", "D": "Convergem em um ponto teórico localizado atrás da retina.", "E": "São refletidos de volta para o ar pela superfície da íris."}, "resposta_correta": "B", "justificativa": "A miopia ocorre quando o globo ocular é mais alongado no sentido anteroposterior ou a curvatura da córnea/cristalino é acentuada demais. Como o poder refrativo é excessivo, os raios convergem antes de atingir a retina.", "possui_imagem": false},
  {"id": 150, "uid": "CIEN-6-150", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Causa Óptica da Hipermetropia", "dificuldade": "Médio", "enunciado": "Em um olho hipermétrope não corrigido, ao tentar observar um objeto próximo sem esforço de acomodação:", "alternativas": {"A": "A imagem nítida se formaria teoricamente atrás da retina, pois a convergência do olho é insuficiente ou o globo ocular é curto demais.", "B": "A imagem se forma na frente da retina como em um olho míope.", "C": "Os raios de luz são transformados em impulsos mecânicos de som na córnea.", "D": "O cristalino perde totalmente a capacidade de receber sangue.", "E": "A córnea torna-se completamente opaca impedindo a passagem de luz."}, "resposta_correta": "A", "justificativa": "Na hipermetropia, o diâmetro anteroposterior do globo ocular é encurtado ou os meios refratores convergem pouco a luz; assim, o plano focal dos raios fica situado atrás do plano da retina.", "possui_imagem": false},
  {"id": 151, "uid": "CIEN-6-151", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Astigmatismo e Superfícies Assimétricas", "dificuldade": "Médio", "enunciado": "O astigmatismo é uma anomalia refrativa que faz com que a pessoa veja imagens borradas ou com sombras tanto de perto quanto de longe. A causa física do astigmatismo é:", "alternativas": {"A": "A curvatura irregular e não homogênea da córnea ou do cristalino, semelhante à superfície de uma bola de futebol americano em vez de uma esfera perfeita.", "B": "A morte de todos os bastonetes da retina na primeira infância.", "C": "O excesso de melanina na íris de pessoas de olhos castanhos.", "D": "A quebra definitiva do nervo óptico em duas metades.", "E": "A falta de produção de lágrimas pelas glândulas lacrimais."}, "resposta_correta": "A", "justificativa": "O astigmatismo é causado por assimetria na curvatura da córnea (ou do cristalino), apresentando meridianos com diferentes raios de curvatura, o que impede a convergência de todos os raios de luz para um único ponto focal.", "possui_imagem": false},
  {"id": 152, "uid": "CIEN-6-152", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Correção do Astigmatismo", "dificuldade": "Médio", "enunciado": "Para corrigir o astigmatismo e compensar as diferentes curvaturas dos meridianos da córnea, utilizam-se lentes oftálmicas especiais denominadas:", "alternativas": {"A": "Lentes exclusivamente biconvexas sem eixo.", "B": "Lentes cilíndricas ou tóricas, que possuem diferentes curvaturas em diferentes eixos de orientação.", "C": "Lentes esféricas de diâmetro universal.", "D": "Lentes de aumento com bordas completamente opacas.", "E": "Prismas coloridos com filtro ultravioleta puro."}, "resposta_correta": "B", "justificativa": "Lentes cilíndricas ou tóricas refratam a luz de maneira diferenciada ao longo de eixos ortogonais específicos, compensando o erro refrativo assimétrico da córnea astigmata.", "possui_imagem": false},
  {"id": 153, "uid": "CIEN-6-153", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Fisiologia dos Cones e Teoria Tricromática", "dificuldade": "Médio", "enunciado": "A visão em cores da espécie humana baseia-se na teoria tricromática. Isso significa que na retina normal existem três tipos principais de cones sensíveis predominantemente a comprimentos de onda de luz correspondentes às cores:", "alternativas": {"A": "Amarelo, ciano e magenta.", "B": "Vermelho, verde e azul.", "C": "Preto, branco e cinza.", "D": "Laranja, marrom e violeta.", "E": "Infravermelho, ultravioleta e luz visível."}, "resposta_correta": "B", "justificativa": "Os seres humanos possuem visão tricromática gerada por três populações de cones dotados de diferentes fotopigmentos (opsinas): cones L (pico no vermelho), cones M (pico no verde) e cones S (pico no azul). A combinação dos sinais desses três tipos gera a percepção de todo o espectro visível.", "possui_imagem": false},
  {"id": 154, "uid": "CIEN-6-154", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Glaucoma e Pressão Intraocular", "dificuldade": "Médio", "enunciado": "O glaucoma é considerado uma das principais causas de cegueira irreversível no mundo. Ele costuma se desenvolver silenciosamente e está associado a:", "alternativas": {"A": "Diminuição drástica do tamanho da pupila na luz solar.", "B": "Aumento anormal da pressão interna do olho pelo acúmulo de humor aquoso, levando à compressão e morte gradual das fibras do nervo óptico.", "C": "Ressecamento das pálpebras por falta de lágrimas.", "D": "Inflamação dos músculos ciliares que movem o cristalino.", "E": "Inversão do fluxo de sangue na artéria da retina."}, "resposta_correta": "B", "justificativa": "O humor aquoso é produzido no corpo ciliar e drenado no ângulo da câmara anterior. Se a drenagem for obstruída, a pressão intraocular eleva-se, comprimindo a lâmina crivosa e lesando irreversivelmente os axônios do nervo óptico.", "possui_imagem": false},
  {"id": 155, "uid": "CIEN-6-155", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Cirurgia de Catarata", "dificuldade": "Médio", "enunciado": "Atualmente, a medicina oftalmológica consegue reverter a cegueira causada pela catarata por meio de uma cirurgia relativamente rápida e segura. Nesse procedimento:", "alternativas": {"A": "Todo o globo ocular é retirado e substituído por um olho de vidro biônico.", "B": "O cristalino opaco e esbranquiçado é fragmentado e aspirado, sendo implantada no mesmo local uma lente intraocular artificial transparente.", "C": "A córnea é costurada sobre a íris para impedir a entrada de bactérias.", "D": "O nervo óptico é reconectado diretamente às pálpebras.", "E": "A retina é raspada para remover o excesso de cones defeituosos."}, "resposta_correta": "B", "justificativa": "A facoemulsificação utiliza ultrassom para fragmentar o cristalino opacificado pela catarata, aspirando-o e inserindo uma lente intraocular (LIO) de polímero transparente no saco capsular.", "possui_imagem": false},
  {"id": 156, "uid": "CIEN-6-156", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Fóvea Central e Acuidade Visual", "dificuldade": "Médio", "enunciado": "Ao ler um texto no papel ou ao reconhecer o rosto de um amigo no meio da multidão, direcionamos o olhar para que os raios de luz incidam exatamente sobre uma região central microscópica da retina chamada fóvea (ou fóvea central). A altíssima nitidez visual nessa região deve-se a:", "alternativas": {"A": "A ausência total de células vivas nessa área do olho.", "B": "A concentração máxima e exclusiva de cones densamente compactados, sem a sobreposição de outras camadas celulares da retina.", "C": "A presença de milhões de bastonetes que detectam luz ultravioleta.", "D": "O fato de ser a região onde a esclera se torna transparente.", "E": "O acúmulo de melanina que bloqueia a luz solar direta."}, "resposta_correta": "B", "justificativa": "A fóvea central é o ponto de maior acuidade visual (visão detalhada) do olho humano, caracterizada por uma altíssima densidade de cones e proporção de 1 cone para 1 célula ganglionar, maximizando a resolução espacial.", "possui_imagem": false},
  {"id": 157, "uid": "CIEN-6-157", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Reflexo Fotomotor Pupilar: Miose e Midríase", "dificuldade": "Médio", "enunciado": "A variação do diâmetro da pupila é um mecanismo reflexo essencial para o funcionamento do olho. A contração da pupila em ambientes claros e sua dilatação em ambientes com pouca luz recebem, respectivamente, os nomes técnicos de:", "alternativas": {"A": "Miopia e hipermetropia.", "B": "Miose e midríase.", "C": "Astigmatismo e presbiopia.", "D": "Refração e reflexão.", "E": "Acomodação e convergência."}, "resposta_correta": "B", "justificativa": "A redução do diâmetro pupilar desencadeada pelo sistema parassimpático em ambientes iluminados é chamada de miose; o aumento do diâmetro mediado pelo simpático no escuro é denominado midríase.", "possui_imagem": false},
  {"id": 158, "uid": "CIEN-6-158", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Visão Binocular e Percepção de Profundidade", "dificuldade": "Médio", "enunciado": "Seres humanos e animais predadores possuem os dois olhos posicionados na parte frontal da face. Ter dois olhos voltados para a frente proporciona a 'visão binocular' (estereoscópica), cuja principal vantagem perceptiva é:", "alternativas": {"A": "Enxergar o que acontece exatamente atrás da própria cabeça.", "B": "Permitir a percepção refinada de profundidade e a estimativa precisa de distâncias tridimensionais, devido à sobreposição dos campos visuais dos dois olhos.", "C": "Ver em cores durante a noite escura sem nenhuma fonte de luz.", "D": "Duplicar a velocidade da luz que entra no cristalino.", "E": "Permitir que um olho durma enquanto o outro permanece acordado."}, "resposta_correta": "B", "justificativa": "Com olhos frontais, os campos visuais se sobrepõem; a ligeira disparidade horizontal entre as imagens captadas por cada olho é combinada no córtex visual, gerando a estereopsia (percepção tridimensional de relevo e profundidade).", "possui_imagem": false},
  {"id": 159, "uid": "CIEN-6-159", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Lentes de Contato e Curvatura da Córnea", "dificuldade": "Médio", "enunciado": "Lentes de contato gelatinosas ou rígidas são colocadas diretamente sobre a superfície da córnea, separadas apenas por uma película microscópica de lágrima. Elas conseguem corrigir erros refrativos como miopia e astigmatismo porque:", "alternativas": {"A": "Modificam a primeira superfície de refração da luz antes que ela penetre no interior do globo ocular, ajustando o trajeto dos raios luminosos.", "B": "Aumentam a quantidade de sangue que circula dentro do cristalino.", "C": "Mudam a cor da íris para tons mais claros que absorvem menos luz.", "D": "Destroem a esclera para diminuir o tamanho do olho.", "E": "Emitem raios laser invisíveis que queimam os fotorreceptores da retina."}, "resposta_correta": "A", "justificativa": "A lente de contato apoia-se sobre o filme lacrimal pré-corneano e substitui a interface ar-córnea por uma nova superfície óptica regular com curvatura calculada, corrigindo a convergência ou astigmatismo do olho.", "possui_imagem": false},
  {"id": 160, "uid": "CIEN-6-160", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Comportamento da Luz: Meios Ópticos", "dificuldade": "Médio", "enunciado": "Para que uma pessoa possa enxergar com nitidez, a luz precisa atravessar sucessivamente quatro meios transparentes do olho humano antes de atingir a retina. A ordem correta percorrida pela luz é:", "alternativas": {"A": "Retina -> Nervo óptico -> Cristalino -> Córnea.", "B": "Córnea -> Humor aquoso -> Cristalino -> Humor vítreo.", "C": "Cristalino -> Córnea -> Pupila -> Íris.", "D": "Esclera -> Humor vítreo -> Retina -> Humor aquoso.", "E": "Pupila -> Córnea -> Retina -> Nervo óptico."}, "resposta_correta": "B", "justificativa": "O trajeto óptico da luz inicia-se na córnea, atravessa a câmara anterior preenchida por humor aquoso, passa pelo orifício pupilar, atravessa o cristalino e segue pelo humor vítreo até convergir na retina.", "possui_imagem": false},
  {"id": 161, "uid": "CIEN-6-161", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Cirurgia Refrativa a Laser (LASIK / PRK)", "dificuldade": "Médio", "enunciado": "Muitos adultos com miopia ou astigmatismo optam por realizar cirurgias refrativas a laser para deixar de usar óculos. O princípio técnico desse procedimento é:", "alternativas": {"A": "Remover o cristalino natural e não colocar nada no lugar.", "B": "Remodelar com precisão microscópica a curvatura da córnea, alterando seu poder de refração para que a luz passe a convergir exatamente sobre a retina.", "C": "Trocar os cones da retina por bastonetes de visão noturna.", "D": "Cortar o nervo óptico para diminuir a sensibilidade à luz.", "E": "Costurar a íris na esclera para aumentar a pupila permanentemente."}, "resposta_correta": "B", "justificativa": "A cirurgia refrativa utiliza feixes de excimer laser para fotoablacionar porções estromais da córnea, aplainando-a no caso de miopia ou corrigindo assimetrias no astigmatismo, ajustando o poder dióptrico corneano.", "possui_imagem": false},
  {"id": 162, "uid": "CIEN-6-162", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Adaptação ao Escuro e Rodopsina", "dificuldade": "Médio", "enunciado": "Ao entrar em uma sala de cinema escura durante o dia, inicialmente não conseguimos enxergar quase nada. Após cerca de 10 a 20 minutos sentados no escuro, passamos a enxergar com razoável nitidez o contorno das poltronas e das pessoas ao redor. Esse processo de adaptação visual ao escuro é explicado biologicamente por:", "alternativas": {"A": "A reconstituição e acúmulo do fotopigmento rodopsina nos bastonetes da retina, que havia sido temporariamente esgotado pela luz brilhante do lado de fora.", "B": "O crescimento de novos olhos na face da pessoa durante a sessão.", "C": "A transformação espontânea da íris em uma lente transparente de aumento.", "D": "A paralisação definitiva do nervo óptico no escuro.", "E": "O aquecimento do humor vítreo pelo calor corporal."}, "resposta_correta": "A", "justificativa": "Em ambientes muito iluminados, a rodopsina dos bastonetes é 'branqueada' (descorada quimicamente pela quebra fotolítica). Na penumbra, a rodopsina é lentamente resintetizada e regenerada, aumentando a sensibilidade luminosa dos bastonetes em até milhares de vezes.", "possui_imagem": false},
  {"id": 163, "uid": "CIEN-6-163", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Visão das Cores em Animais", "dificuldade": "Médio", "enunciado": "Diferente dos humanos, que possuem três tipos de cones, muitos pássaros e insetos (como abelhas) possuem quatro tipos de cones, conseguindo enxergar a luz ultravioleta. Por outro lado, a maioria dos cães e gatos possui apenas dois tipos de cones (visão dicromática). Com base nessas informações, é correto concluir que:", "alternativas": {"A": "Todos os animais enxergam o mundo exatamente da mesma forma que os humanos.", "B": "A capacidade de perceber cores e faixas do espectro eletromagnético varia entre as espécies de acordo com os tipos de fotorreceptores presentes na retina e suas adaptações ecológicas.", "C": "Cães e gatos são completamente cegos e não enxergam objetos em movimento.", "D": "Abelhas não dependem de luz para localizar flores nos jardins.", "E": "Pássaros possuem cristalinos de vidro que absorvem ondas sonoras."}, "resposta_correta": "B", "justificativa": "A percepção cromática é determinada pelos fotopigmentos dos cones selecionados evolutivamente; animais dicromatas (como canídeos) veem espectros mais restritos, enquanto tetracromatas (aves e insetos) captam radiações como o UV, essenciais para forrageamento e comunicação.", "possui_imagem": false},
  {"id": 164, "uid": "CIEN-6-164", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Óculos Escuros e Proteção Ultravioleta (UV)", "dificuldade": "Médio", "enunciado": "Usar óculos de sol falsificados ou sem filtro de proteção contra raios ultravioleta (UV) pode ser mais prejudicial aos olhos do que não usar óculos escuros. Isso acontece porque:", "alternativas": {"A": "As lentes escuras sem filtro enganam o olho: a escuridão faz a pupila dilatar (midríase), permitindo que uma quantidade ainda maior de radiação UV nociva entre e queime a retina e o cristalino.", "B": "Os óculos falsificados aumentam a temperatura do ar ao redor do nariz.", "C": "O plástico comum atrai bactérias devoradoras de córnea.", "D": "As lentes escuras congelam as glândulas lacrimais impedindo o piscar.", "E": "A luz ultravioleta só existe quando usamos óculos de sol."}, "resposta_correta": "A", "justificativa": "A lente escura reduz a luminosidade visível, induzindo a dilatação reflexa da pupila. Se a lente não bloquear os comprimentos de onda ultravioleta (UVA e UVB), a pupila dilatada permitirá a entrada de doses muito maiores de radiação UV diretamente sobre o cristalino (risco de catarata precoce) e retina (degeneração macular).", "possui_imagem": false},
  {"id": 165, "uid": "CIEN-6-165", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Importância da Vitamina A na Visão", "dificuldade": "Médio", "enunciado": "A deficiência nutricional grave de vitamina A na infância pode causar 'cegueira noturna' (dificuldade de enxergar em ambientes com pouca luz) e ressecamento extremo da córnea (xeroftalmia). A vitamina A é essencial para a visão porque:", "alternativas": {"A": "É um componente químico indispensável para a síntese do retinal, molécula que compõe os pigmentos visuais (como a rodopsina) nos fotorreceptores da retina.", "B": "Atua como o combustível queimado pela córnea para produzir luz própria.", "C": "Substitui a água do humor vítreo quando o indivíduo fica com sede.", "D": "É a responsável exclusiva pela cor verde ou azul da íris.", "E": "Destrói o excesso de neurônios no nervo óptico."}, "resposta_correta": "A", "justificativa": "A vitamina A (retinol) é o precursor bioquímico do 11-cis-retinal, o cromóforo que se liga às opsinas formando a rodopsina dos bastonetes e as iodopsinas dos cones. Sua carência compromete primeiramente a função dos bastonetes no escuro.", "possui_imagem": false},
  {"id": 166, "uid": "CIEN-6-166", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Grau das Lentes: Conceito de Dioptria", "dificuldade": "Médio", "enunciado": "Na receita de óculos prescrita por um oftalmologista, a potência das lentes é medida em 'graus' (unidade física chamada dioptria, cujo símbolo é D). Uma receita médica que indica '-2,50 D' no olho direito e '+3,00 D' no olho esquerdo indica, respectivamente, a necessidade de lentes:", "alternativas": {"A": "Convergente de 2,5 graus e divergente de 3,0 graus.", "B": "Divergente de 2,5 dioptrias (para miopia) e convergente de 3,0 dioptrias (para hipermetropia).", "C": "Cilíndricas neutras sem foco definido para ambos os olhos.", "D": "Planos com proteção solar sem alteração de foco.", "E": "Bifocais opacas para cegueira temporária."}, "resposta_correta": "B", "justificativa": "Por convenção óptica e médica, vergências negativas (-) indicam lentes divergentes (utilizadas na correção da miopia), enquanto vergências positivas (+) indicam lentes convergentes (utilizadas na correção da hipermetropia e presbiopia).", "possui_imagem": false},
  {"id": 167, "uid": "CIEN-6-167", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Ilusões de Óptica e Processamento Cerebral", "dificuldade": "Médio", "enunciado": "Em muitas ilusões de óptica clássicas (como duas linhas retas idênticas em que uma parece maior que a outra devido a setas nas pontas - Ilusão de Müller-Lyer), os olhos captam a luz perfeitamente, mas a nossa mente percebe tamanhos diferentes. Isso demonstra que:", "alternativas": {"A": "Os olhos são órgãos defeituosos que nunca funcionam corretamente.", "B": "Enxergar não é apenas captar luz com a retina, mas envolve a interpretação e reconstrução ativa da imagem pelo cérebro com base em pistas contextuais e memórias prévias.", "C": "As setas de metal deformaram o papel fisicamente durante o olhar.", "D": "O nervo óptico quebra o sinal de luz antes que ele chegue ao cérebro.", "E": "A retina dos seres humanos não possui cones suficientes para medir linhas."}, "resposta_correta": "B", "justificativa": "A visão é um processo perceptivo complexo: a retina transduz fótons em sinais elétricos brutos, mas é o córtex cerebral que interpreta perspectivas, sombras, bordas e profundidade, podendo gerar erros de julgamento (ilusões de óptica cognitivas).", "possui_imagem": false},
  {"id": 168, "uid": "CIEN-6-168", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Lentes Biconvexas como Lupas", "dificuldade": "Médio", "enunciado": "Quando uma pessoa utiliza uma lupa (lente convergente) para observar pequenos insetos no jardim, ela deve posicionar o inseto a uma distância menor que a distância focal da lente. Nessa situação, a imagem observada pelo olho através da lupa é:", "alternativas": {"A": "Real, invertida e menor que o inseto.", "B": "Virtual, direita (não invertida) e ampliada (maior que o inseto).", "C": "Projetada no chão de cabeça para baixo e do mesmo tamanho.", "D": "Em preto e branco e com as patas do inseto distorcidas.", "E": "Invisível para o olho humano."}, "resposta_correta": "B", "justificativa": "Quando um objeto real é posicionado entre o foco principal e o centro óptico de uma lente convergente, os raios refratados divergem e seus prolongamentos formam uma imagem virtual, direita e maior, caracterizando o funcionamento típico de uma lupa de mão.", "possui_imagem": false},
  {"id": 169, "uid": "CIEN-6-169", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Óptica Fisiológica: Equação das Lentes e Distância Focal", "dificuldade": "Difícil", "enunciado": "A convergência de uma lente (medida em dioptrias, D) é o inverso de sua distância focal em metros (D = 1/f). Sabendo disso, uma lente de óculos receitada para um paciente tem distância focal f = -0,5 metro. Qual é a vergência dessa lente e para qual anomalia visual ela foi prescrita?", "alternativas": {"A": "+2,0 D, prescrita para hipermetropia.", "B": "-2,0 D, prescrita para miopia.", "C": "-0,5 D, prescrita para astigmatismo.", "D": "+0,5 D, prescrita para presbiopia.", "E": "-5,0 D, prescrita para catarata congênita."}, "resposta_correta": "B", "justificativa": "Cálculo da vergência: D = 1 / f = 1 / (-0,5 m) = -2,0 dioptrias. O sinal negativo indica lente divergente, que tem distância focal virtual e é utilizada na correção óptica da miopia.", "possui_imagem": false},
  {"id": 170, "uid": "CIEN-6-170", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Fototransdução e Hiperpolarização na Retina", "dificuldade": "Difícil", "enunciado": "Diferente da maioria dos receptores sensoriais do corpo humano (que se despolarizam ao serem estimulados), os fotorreceptores da retina (cones e bastonetes) no escuro mantêm canais de sódio abertos e estão constantemente despolarizados, liberando neurotransmissores. Quando a luz atinge a rodopsina, ocorre:", "alternativas": {"A": "A abertura de canais de cálcio que queima o fotorreceptor.", "B": "A ativação de uma cascata de proteínas (transducina e fosfodiesterase) que fecha os canais de sódio, hiperpolarizando a membrana do fotorreceptor e reduzindo a liberação de glutamato.", "C": "A destruição total da retina por calor eletromagnético.", "D": "A entrada de luz solar líquida no citoplasma celular.", "E": "A transformação instantânea dos cones em células musculares ciliares."}, "resposta_correta": "B", "justificativa": "Na fototransdução, a absorção de fótons fotoisomeriza o retinal, ativando a transducina e a PDE, que degrada o GMPc. Sem GMPc, os canais de cátions fecham-se, hiperpolarizando o fotorreceptor. Essa redução na liberação de neurotransmissor sinaliza a presença de luz para as células bipolares.", "possui_imagem": false},
  {"id": 171, "uid": "CIEN-6-171", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Profundidade de Foco e Diâmetro Pupilar", "dificuldade": "Difícil", "enunciado": "Em dias extremamente ensolarados, uma pessoa que possui um grau leve de miopia ou astigmatismo frequentemente nota que consegue enxergar placas distantes com muito mais nitidez sem óculos do que em dias nublados ou à noite. A explicação física para esse aumento de nitidez na claridade é:", "alternativas": {"A": "A miose pupilar reflexa em ambiente iluminado reduz as aberrações ópticas esféricas e aumenta a profundidade de foco, funcionando como uma câmara escura de orifício estenopeico (pinhole).", "B": "A luz solar intensa diminui o comprimento do globo ocular em milímetros.", "C": "O calor do sol faz as lágrimas funcionarem como lentes divergentes permanentes.", "D": "A córnea absorve luz solar e dobra seu índice de refração instantaneamente.", "E": "O ar atmosférico quente afasta os raios de luz para fora do olho."}, "resposta_correta": "A", "justificativa": "Ao fechar a pupila (miose), o feixe luminoso que penetra no olho é restrito à porção central mais perfeita da córnea e do cristalino, eliminando raios marginais periféricos aberrantes e aumentando a profundidade de campo (efeito estenopeico).", "possui_imagem": false},
  {"id": 172, "uid": "CIEN-6-172", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Descolamento de Retina e Sintomas de Alerta", "dificuldade": "Difícil", "enunciado": "O descolamento de retina é uma emergência oftalmológica grave na qual a camada neurossensorial da retina se separa do epitélio pigmentar subjacente e da coroide vascular. O paciente costuma relatar sintomas característicos como 'flashes de luz repentinos' (fotopsias) e uma 'sombra escura tipo cortina' avançando sobre o campo visual. A urgência no tratamento cirúrgico existe porque:", "alternativas": {"A": "Sem o contato físico direto com a coroide, os fotorreceptores ficam desprovidos de oxigênio e nutrientes vitais, sofrendo morte celular irreversível em poucas horas ou dias.", "B": "A retina solta pode escorrer pela garganta através da tuba auditiva.", "C": "O humor vítreo se transforma em ácido clorídrico quando entra em contato com o ar.", "D": "O olho descolado se funde com os ossos da cavidade nasal.", "E": "A pálpebra para de piscar e endurece como pedra calcária."}, "resposta_correta": "A", "justificativa": "A coroide nutre as camadas externas da retina (incluindo fotorreceptores). A separação mecânica corta o aporte de oxigênio e glicose aos cones e bastonetes; a demora no reposicionamento cirúrgico culmina em necrose neural e perda visual permanente.", "possui_imagem": false},
  {"id": 173, "uid": "CIEN-6-173", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Cruzamento de Fibras no Quiasma Óptico", "dificuldade": "Difícil", "enunciado": "Os axônios dos nervos ópticos que partem de cada olho chegam à base do cérebro em uma estrutura chamada quiasma óptico. No quiasma óptico humano ocorre um cruzamento parcial fundamental: as fibras originadas da metade medial (nasal) da retina de cada olho cruzam para o lado oposto do cérebro, enquanto as fibras da metade lateral (temporal) continuam do mesmo lado. Esse arranjo neuroanatômico assegura que:", "alternativas": {"A": "O olho direito envie imagens apenas para os pés e o esquerdo para as mãos.", "B": "Todas as informações visuais provenientes do hemicampo visual esquerdo sejam processadas juntas no córtex visual do hemisfério cerebral direito, e vice-versa.", "C": "O cérebro enxergue apenas duas dimensões no espaço sem cores.", "D": "As pessoas cegas de nascença tenham audição superdesenvolvida.", "E": "As pálpebras pisquem de forma alternada a cada minuto."}, "resposta_correta": "B", "justificativa": "O cruzamento parcial no quiasma óptico direciona todos os estímulos luminosos provenientes do hemicampo visual direito para o hemisfério cerebral esquerdo e do hemicampo esquerdo para o hemisfério direito, viabilizando a integração binocular e o processamento coerente do espaço visual.", "possui_imagem": false},
  {"id": 174, "uid": "CIEN-6-174", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Mecanismo da Miopia por Esforço de Perto (Ambiente Moderno)", "dificuldade": "Difícil", "enunciado": "Estudos epidemiológicos globais recentes apontam um aumento alarmante nos índices de miopia em crianças e adolescentes que passam muitas horas por dia em ambientes fechados utilizando telas eletrônicas (smartphones e computadores) e pouco tempo expostos à luz solar natural externa. Cientificamente, a exposição à luz solar natural ajuda a prevenir o desenvolvimento da miopia porque:", "alternativas": {"A": "A luz solar estimula a síntese e liberação de dopamina na retina, neurotransmissor que atua como regulador biológico, inibindo o alongamento axial excessivo do globo ocular na infância.", "B": "O calor direto do sol queima a córnea, tornando-a perfeitamente plana.", "C": "Os raios UV destroem o cristalino antes que ele cresça demais.", "D": "A luz externa impede que o cérebro produza lágrimas.", "E": "O vento ao ar livre resfria a esclera, impedindo os olhos de se abrirem."}, "resposta_correta": "A", "justificativa": "A iluminação natural diurna (com intensidade na faixa de milhares de lux) estimula a liberação de dopamina retiniana, que atua como sinal 'stop' no crescimento do comprimento axial do globo ocular. Pouca luz solar associada ao esforço constante de acomodação para perto favorece o alongamento axial exagerado (miopia de desenvolvimento).", "possui_imagem": false},
  {"id": 175, "uid": "CIEN-6-175", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Aberração Cromática e Dispersão da Luz", "dificuldade": "Difícil", "enunciado": "Quando um feixe de luz branca incide sobre uma lente convergente de vidro simples, a luz azul refrata com um ângulo ligeiramente maior e foca um pouco mais perto da lente do que a luz vermelha. Esse fenômeno físico é a aberração cromática, que decorre do fato de que:", "alternativas": {"A": "A velocidade da luz no vácuo varia conforme a cor.", "B": "O índice de refração do material transparente varia de acordo com o comprimento de onda da luz (fenômeno da dispersão luminosa).", "C": "A luz vermelha não sofre refração em nenhum meio transparente.", "D": "O vidro da lente queima os fótons de cor azul.", "E": "As lentes esféricas não possuem foco para cores frias."}, "resposta_correta": "B", "justificativa": "O índice de refração de um meio dispersivo é maior para frequências mais altas (comprimentos de onda menores, como a luz violeta/azul) do que para frequências mais baixas (luz vermelha). Como o azul desvia mais que o vermelho, surgem diferentes focos para cada cor (aberração cromática).", "possui_imagem": false},
  {"id": 176, "uid": "CIEN-6-176", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Daltonismo Ligado ao Cromossomo X", "dificuldade": "Difícil", "enunciado": "O daltonismo do tipo vermelho-verde é uma condição genética recessiva ligada ao cromossomo sexual X. Devido a esse padrão de herança biológica, qual é a justificativa para o fato de o daltonismo ser muito mais frequente em homens (cerca de 8%) do que em mulheres (menos de 0,5%)?", "alternativas": {"A": "As mulheres não possuem fotorreceptores cones em suas retinas.", "B": "Os homens possuem apenas um cromossomo X (XY); portanto, se herdarem o gene mutado em seu único cromossomo X materno, manifestarão o daltonismo, enquanto mulheres (XX) necessitam herdar o gene mutado em dose dupla.", "C": "O gene do daltonismo só consegue ser ativado pelo hormônio testosterona.", "D": "Os homens passam mais tempo jogando videogames do que as mulheres.", "E": "O cromossomo Y destrói ativamente os cones verdes dos olhos masculinos."}, "resposta_correta": "B", "justificativa": "Como os genes para as opsinas sensíveis ao vermelho e verde situam-se no cromossomo X, os indivíduos do sexo masculino (hemizigotos XY) manifestam o fenótipo recessivo com apenas um alelo mutado; mulheres (XX) só são daltônicas se forem homozigotas recessivas.", "possui_imagem": false},
  {"id": 177, "uid": "CIEN-6-177", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Comparação: Olho Humano vs. Câmera Fotográfica", "dificuldade": "Difícil", "enunciado": "Em estudos de óptica biomédica, o olho humano é frequentemente comparado a uma câmera fotográfica digital moderna. Assinale a correlação rigorosa entre as estruturas anatômicas do olho e os componentes da câmera:", "alternativas": {"A": "Córnea/Cristalino: sistema de lentes objetivas; Íris/Pupila: diafragma e abertura; Retina: sensor digital (sensor CMOS/CCD).", "B": "Retina: diafragma; Córnea: bateria elétrica; Cristalino: cartão de memória.", "C": "Íris: sensor de luz; Pupila: lente biconvexa; Nervo óptico: flash fotográfico.", "D": "Esclera: zoom óptico; Coroide: obturador; Bastonetes: lentes de contato.", "E": "Cristalino: fio de energia; Retina: botão de disparo; Pupila: carcaça externa."}, "resposta_correta": "A", "justificativa": "A córnea e o cristalino compõem o sistema óptico dióptrico refrator (objetiva); a íris ajusta a abertura da pupila controlando a luminosidade admitida (diafragma); a retina com seus milhões de píxeis biológicos (fotorreceptores) atua como o sensor fotossensível; e o nervo óptico atua como o cabo de transmissão de dados ao processador (cérebro).", "possui_imagem": false},
  {"id": 178, "uid": "CIEN-6-178", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Músculos Oculomotores e Estrabismo", "dificuldade": "Difícil", "enunciado": "O alinhamento e os movimentos precisos de cada globo ocular na órbita são controlados por seis músculos extrínsecos do olho (quatro retos e dois oblíquos). Quando há um desequilíbrio na força ou na inervação desses músculos, os olhos apontam para direções diferentes (estrabismo). Se o estrabismo não for corrigido precocemente em crianças pequenas, o cérebro pode suprimir ativamente a imagem do olho desviado para evitar visão dupla (diplopia), gerando uma condição irreversível chamada:", "alternativas": {"A": "Ambliopia (ou 'olho preguiçoso').", "B": "Presbiopia precoce congênita.", "C": "Catarata juvenil bilateral.", "D": "Astigmatismo macular degenerativo.", "E": "Miopia noturna crônica."}, "resposta_correta": "A", "justificativa": "No período crítico de plasticidade visual da infância, se um olho envia imagens desalinhadas ou borradas, o córtex visual passa a ignorar o sinal desse olho para evitar a diplopia, atrofiando o desenvolvimento das vias neurais e instalando a ambliopia definitiva.", "possui_imagem": false},
  {"id": 179, "uid": "CIEN-6-179", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Reflexão Interna Total e Fibras Ópticas na Medicina", "dificuldade": "Difícil", "enunciado": "Endoscópios médicos utilizados para examinar o interior do estômago ou do intestino contêm feixes flexíveis de fibras ópticas de vidro. A luz entra por uma ponta e percorre curvas fechadas dentro do cabo sem escapar pelas laterais até iluminar o órgão interno. O princípio óptico que mantém a luz confinada dentro do núcleo da fibra de vidro é a:", "alternativas": {"A": "Reflexão interna total, que ocorre quando a luz viaja de um meio mais refringente para um menos refringente com ângulo superior ao ângulo limite.", "B": "Absorção de todos os comprimentos de onda pelas paredes do cabo.", "C": "Difração contínua provocada pela gravidade estomacal.", "D": "Transformação da luz em ondas de rádio moduladas.", "E": "Fusão térmica do núcleo de vidro sob alta pressão."}, "resposta_correta": "A", "justificativa": "A fibra óptica possui núcleo com índice de refração maior que a casca. Quando a luz atinge a interface núcleo-casca com ângulo de incidência superior ao ângulo limite (crítico), ela sofre reflexão interna total consecutiva, propagando-se por toda a extensão da fibra sem perda luminosa.", "possui_imagem": false},
  {"id": 180, "uid": "CIEN-6-180", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Lentes Bifocais e Multifocais", "dificuldade": "Difícil", "enunciado": "Um paciente de 55 anos que já era míope desde a adolescência desenvolveu presbiopia decorrente da idade. Ao consultar o oftalmologista, este prescreveu lentes multifocais progressivas. A vantagem dessas lentes para esse paciente é:", "alternativas": {"A": "Permitir que a pessoa enxergue no escuro sem precisar acender as luzes da casa.", "B": "Apresentar uma variação gradual e contínua do poder dióptrico ao longo da lente, integrando a correção para visão de longe (topo da lente), meia distância (centro) e perto (base), sem linhas visíveis divisórias.", "C": "Bloquear 100% da luz solar para curar a miopia em duas semanas.", "D": "Aumentar o tamanho do globo ocular para transformá-lo em olho normal.", "E": "Substituir o cristalino cirurgicamente sem necessidade de operação."}, "resposta_correta": "B", "justificativa": "Lentes multifocais combinam diferentes curvaturas calculadas matematicamente em sua superfície: a porção superior compensa o erro para longe (miopia com potência negativa), a porção intermediária atende distâncias como telas de computador, e a porção inferior adiciona convergência positiva para leitura próxima.", "possui_imagem": false},
  {"id": 181, "uid": "CIEN-6-181", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Olho Emetrope e Mecânica Visual", "dificuldade": "Difícil", "enunciado": "Um olho sem nenhum erro de refração é denominado cientificamente na medicina de 'olho emétrope'. Em repouso acomodativo (olhando para o horizonte ou infinito), o olho emétrope apresenta:", "alternativas": {"A": "Os músculos ciliares totalmente contraídos e a pupila dilatada ao máximo.", "B": "Os raios luminosos paralelos convergindo com precisão matemática exatamente sobre a camada de fotorreceptores da retina sem necessidade de esforço muscular do cristalino.", "C": "Uma imagem virtual localizada 1 metro à frente da córnea.", "D": "A esclera operando como fotorreceptor secundário de luz amarela.", "E": "Necessidade de lentes convexas de pelo menos +1 dioptria para focar paisagens."}, "resposta_correta": "B", "justificativa": "Por definição, a emetropia é o estado refrativo ideal no qual a potência óptica combinada da córnea e do cristalino em repouso corresponde perfeitamente ao comprimento anteroposterior do globo ocular (cerca de 24 mm), focando objetos distantes na retina sem esforço acomodativo.", "possui_imagem": false},
  {"id": 182, "uid": "CIEN-6-182", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Degeneração Macular Relacionada à Idade (DMRI)", "dificuldade": "Difícil", "enunciado": "A mácula lútea é a região nobre da retina que circunda a fóvea, responsável pela visão central nítida necessária para leitura e direção de veículos. Na Degeneração Macular Relacionada à Idade (DMRI), o indivíduo afetado perde progressivamente a:", "alternativas": {"A": "Visão periférica, mantendo apenas a visão central em forma de túnel.", "B": "Visão central de alta resolução, passando a enxergar uma mancha escura ou distorção ondulada no centro do campo visual, enquanto a visão periférica permanece relativamente preservada.", "C": "Capacidade de mover os músculos das pálpebras para cima e para baixo.", "D": "Sensibilidade à dor física provocada por cortes na pele.", "E": "Capacidade de ouvir frequências agudas de som."}, "resposta_correta": "B", "justificativa": "A DMRI compromete seletivamente as células da mácula na retina central. O paciente desenvolve escotoma central (mancha cega central) e metamorfopsia (linhas retas vistas como onduladas), conservando a visão periférica dos bastonetes.", "possui_imagem": false},
  {"id": 183, "uid": "CIEN-6-183", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Miopia Axial vs. Miopia Refrativa (ou de Curvatura)", "dificuldade": "Difícil", "enunciado": "A miopia pode ser classificada etiologicamente em 'miopia axial' ou 'miopia de curvatura/refrativa'. A diferença biomecânica entre essas duas formas de miopia reside em:", "alternativas": {"A": "Na miopia axial, o globo ocular possui comprimento anteroposterior maior que o normal; na miopia de curvatura, o globo ocular tem tamanho normal, mas a curvatura da córnea ou cristalino é excessivamente acentuada (poder dióptrico muito alto).", "B": "Na miopia axial, a pessoa não enxerga cores; na de curvatura, não enxerga formas.", "C": "A miopia axial afeta apenas o olho esquerdo e a de curvatura afeta apenas o direito.", "D": "A miopia de curvatura é causada por bactérias e a axial é causada por fungos.", "E": "A miopia axial tem cura com colírios hidratantes simples."}, "resposta_correta": "A", "justificativa": "Em ambos os casos a imagem forma-se à frente da retina, mas na miopia axial a causa primária é anatômica (globo ocular longo, mais comum em altos míopes), enquanto na miopia de curvatura a causa é a refringência exagerada dos meios ópticos com dimensões oculares normais.", "possui_imagem": false},
  {"id": 184, "uid": "CIEN-6-184", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Espessura de Borda em Lentes de Grau", "dificuldade": "Difícil", "enunciado": "Ao confeccionar óculos para um paciente com miopia severa de -8,00 dioptrias e outro para um paciente com hipermetropia alta de +8,00 dioptrias, o técnico de óptica laboratorial observa um padrão marcante nas bordas e no centro dessas lentes. Esse padrão consiste em:", "alternativas": {"A": "Ambas as lentes possuem espessura perfeitamente uniforme em toda a extensão.", "B": "A lente para miopia (-8 D) é muito fina no centro e extremamente grossa nas bordas laterais (divergente); a lente para hipermetropia (+8 D) é espessa no centro e fina nas bordas (convergente).", "C": "A lente para miopia é oca por dentro e cheia de líquido aquoso.", "D": "A lente para hipermetropia é feita de borracha opaca flexível.", "E": "A lente para miopia possui bordas microscópicas invisíveis a olho nu."}, "resposta_correta": "B", "justificativa": "Lentes divergentes (potência negativa para miopia) têm perfil côncavo, com espessura mínima no centro óptico e espessura máxima nas bordas perimétricas. Lentes convergentes (potência positiva para hipermetropia) são convexas, com centro bojudinho e bordas finas.", "possui_imagem": false},
  {"id": 185, "uid": "CIEN-6-185", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Ilusão das Pós-Imagens e Exaustão de Fotopigmentos", "dificuldade": "Difícil", "enunciado": "Se fixarmos o olhar em um quadrado vermelho brilhante por 60 segundos sem desviar os olhos e, em seguida, olharmos imediatamente para uma parede branca lisa, enxergaremos nitidamente um quadrado de cor verde-azulada (ciano) flutuando diante dos olhos por alguns segundos. Esse fenômeno fisiológico de pós-imagem negativa ocorre porque:", "alternativas": {"A": "A parede branca emite radiação ciano quando olhada por humanos.", "B": "Os cones sensíveis ao vermelho sofrem fadiga e exaustão temporária de seus fotopigmentos após estimulação prolongada; ao olhar para a luz branca (que contém todas as cores), os cones verdes e azuis respondem normalmente, gerando a percepção da cor complementar.", "C": "A retina congela a imagem física no cristalino como uma fotografia queimada.", "D": "O cérebro esquece o que é a cor vermelha durante o teste.", "E": "O nervo óptico inverte as conexões elétricas a cada 30 segundos."}, "resposta_correta": "B", "justificativa": "A estimulação prolongada e estática 'descolora' e esgota os fotopigmentos dos cones L (vermelhos), dessensibilizando-os temporariamente. Ao olhar para o fundo branco neutro, os cones M (verdes) e S (azuis) não fatigados disparam com muito mais intensidade relativa, projetando a cor complementar ciano.", "possui_imagem": false},
  {"id": 186, "uid": "CIEN-6-186", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Índice de Refração e Lei de Snell no Olho", "dificuldade": "Difícil", "enunciado": "O índice de refração do ar é aproximadamente 1,00, o da córnea é cerca de 1,38, o do humor aquoso é 1,33, o do cristalino varia entre 1,40 e 1,42 e o do humor vítreo é 1,34. Com base nesses valores físicos, a maior mudança de velocidade e o maior desvio angular da luz ao entrar no olho ocorrem na interface:", "alternativas": {"A": "Cristalino - Humor vítreo.", "B": "Ar - Córnea, devido à maior diferença relativa entre os índices de refração dos dois meios contíguos (de 1,00 para 1,38).", "C": "Humor aquoso - Cristalino.", "D": "Humor vítreo - Retina.", "E": "Retina - Nervo óptico."}, "resposta_correta": "B", "justificativa": "A magnitude do desvio refrativo depende da razão entre os índices de refração dos meios (Lei de Snell). O salto do ar (n = 1,0) para a córnea (n = 1,38) representa a maior descontinuidade óptica de todo o sistema visual, sendo a superfície corneana responsável por cerca de dois terços de todo o poder refrativo do olho humano (cerca de 40 a 43 dioptrias de um total de 60 D).", "possui_imagem": false},
  {"id": 187, "uid": "CIEN-6-187", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Tonometria e Dano Isquêmico no Glaucoma", "dificuldade": "Difícil", "enunciado": "Em consultas de rotina ao oftalmologista, é realizado o exame de tonometria (sopro de ar ou toque suave na córnea) para medir a pressão intraocular (PIO), cujo valor normal situa-se entre 10 e 21 mmHg. Por que o controle da pressão intraocular é tão rigoroso na prevenção da cegueira?", "alternativas": {"A": "Porque a pressão alta faz os olhos saltarem para fora da cabeça e caírem no chão.", "B": "Porque valores sustentados de PIO acima de 21 mmHg comprimem os microvasos que nutrem as fibras nervosas do disco óptico, causando isquemia, degeneração axonal progressiva e perda irreversível do campo visual periférico.", "C": "Porque a pressão alta faz a lágrima se tornar ácida como vinagre.", "D": "Porque o glaucoma altera a cor da íris para tons fluorescentes perigosos.", "E": "Porque o olho humano precisa manter pressão negativa (vácuo) para focar."}, "resposta_correta": "B", "justificativa": "A hipertensão ocular persistente gera estresse mecânico sobre a lâmina crivosa e hipoperfusão (isquemia) microvascular na cabeça do nervo óptico, induzindo apoptose de células ganglionares e escavação do disco óptico, levando à perda progressiva do campo visual (glaucoma).", "possui_imagem": false},
  {"id": 188, "uid": "CIEN-6-188", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 16: Visão e Lentes", "tema": "Princípio das Lentes de Fresnell e Faróis Náuticos", "dificuldade": "Difícil", "enunciado": "Em faróis náuticos antigos e em certas lentes modernas de aumento finas, utiliza-se a invenção do físico Augustin Fresnel (lente de Fresnel), que substituiu a curvatura espessa e pesada de uma lente convergente clássica por anéis concêntricos prismáticos estreitos com a mesma curvatura superficial. Essa engenharia óptica comprova que:", "alternativas": {"A": "A espessura interna do vidro é a única responsável pelo foco da luz.", "B": "A refração e o desvio dos raios luminosos ocorrem estritamente nas superfícies limítrofes de entrada e saída da lente, permitindo remover a maior parte da massa intermediária do vidro sem perder o poder de convergência focal.", "C": "A luz não precisa de lentes para ser focada em longas distâncias marítimas.", "D": "Faróis utilizam apenas espelhos planos sem nenhuma curvatura óptica.", "E": "Lentes de Fresnel funcionam apenas sob a água do mar."}, "resposta_correta": "B", "justificativa": "A refração ocorre exclusivamente na interface onde há mudança de meio (ar-vidro e vidro-ar). A porção interna do material de uma lente volumosa atua apenas como condutor sem alterar o ângulo de refração; a lente de Fresnel mantém a curvatura superficial em anéis concêntricos finos, reduzindo drasticamente o peso e a absorção de luz.", "possui_imagem": false},
  {"id": 189, "uid": "CIEN-6-189", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Movimento de Rotação da Terra", "dificuldade": "Fácil", "enunciado": "A Terra realiza um movimento contínuo girando em torno de seu próprio eixo imaginário. Esse movimento é denominado:", "alternativas": {"A": "Translação.", "B": "Rotação.", "C": "Nutação.", "D": "Precessão.", "E": "Órbita elíptica."}, "resposta_correta": "B", "justificativa": "A rotação é o movimento que a Terra realiza girando em torno de seu próprio eixo, completando uma volta a cada aproximadamente 24 horas.", "possui_imagem": true},
  {"id": 190, "uid": "CIEN-6-190", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Consequências da Rotação", "dificuldade": "Fácil", "enunciado": "A principal consequência direta do movimento de rotação da Terra para o nosso dia a dia é a:", "alternativas": {"A": "Sucessão das quatro estações do ano.", "B": "Alternância diária entre os dias e as noites.", "C": "Ocorrência de eclipses solares mensais.", "D": "Variação das fases da Lua.", "E": "Mudança da temperatura entre os polos e o equador."}, "resposta_correta": "B", "justificativa": "À medida que a Terra gira em torno de seu eixo, diferentes regiões de sua superfície ficam alternadamente voltadas para o Sol (dia) e opostas ao Sol (noite).", "possui_imagem": false},
  {"id": 191, "uid": "CIEN-6-191", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Duração da Rotação", "dificuldade": "Fácil", "enunciado": "O tempo aproximado que a Terra leva para dar uma volta completa em torno de seu próprio eixo de rotação é de:", "alternativas": {"A": "12 horas.", "B": "24 horas (1 dia).", "C": "30 dias (1 mês).", "D": "365 dias (1 ano).", "E": "48 horas."}, "resposta_correta": "B", "justificativa": "O período de rotação da Terra em relação ao Sol (dia solar médio) é de exatamente 24 horas, base do nosso calendário diário.", "possui_imagem": false},
  {"id": 192, "uid": "CIEN-6-192", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Movimento de Translação da Terra", "dificuldade": "Fácil", "enunciado": "O movimento que a Terra realiza ao se deslocar no espaço ao redor do Sol em uma órbita quase circular é chamado de:", "alternativas": {"A": "Rotação.", "B": "Translação.", "C": "Gravitação.", "D": "Eclipsamento.", "E": "Refração solar."}, "resposta_correta": "B", "justificativa": "A translação é o movimento orbital que a Terra executa ao redor do Sol, percorrendo uma órbita elíptica ao longo de aproximadamente um ano.", "possui_imagem": true},
  {"id": 193, "uid": "CIEN-6-193", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Duração da Translação e Ano Bissexto", "dificuldade": "Fácil", "enunciado": "A Terra demora aproximadamente 365 dias e 6 horas para completar uma volta ao redor do Sol. Para compensar essas 6 horas que sobram a cada ano no calendário civil, a cada quatro anos é criado o chamado 'ano bissexto', no qual:", "alternativas": {"A": "O mês de fevereiro ganha um dia a mais, passando a ter 29 dias.", "B": "O mês de dezembro ganha dois dias a mais de férias escolares.", "C": "O dia solar passa a ter 25 horas em vez de 24 horas.", "D": "O mês de julho é cancelado do calendário.", "E": "O inverno dura um mês a menos em todo o planeta."}, "resposta_correta": "A", "justificativa": "Como 6 horas x 4 anos = 24 horas (1 dia completo), a cada quatro anos adiciona-se o dia 29 de fevereiro ao calendário civil, totalizando 366 dias no ano bissexto.", "possui_imagem": false},
  {"id": 194, "uid": "CIEN-6-194", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "O Instrumento Gnômon", "dificuldade": "Fácil", "enunciado": "Um dos instrumentos astronômicos mais antigos criados pela humanidade para estudar o movimento aparente do Sol e marcar o tempo é o gnômon. Em sua forma mais simples, o gnômon consiste em:", "alternativas": {"A": "Uma luneta de vidro com lentes divergentes.", "B": "Uma haste reta fixada verticalmente em uma superfície plana e nivelada exposta à luz do sol.", "C": "Um espelho côncavo que reflete a luz das estrelas à noite.", "D": "Uma bússola magnética com agulha de ferro flutuante.", "E": "Um pêndulo de chumbo pendurado no teto."}, "resposta_correta": "B", "justificativa": "O gnômon tradicional é composto basicamente por uma vareta ou coluna vertical cravada perpendicularmente sobre um piso plano horizontal iluminado pelo Sol, cuja sombra projeta dados astronômicos.", "possui_imagem": true},
  {"id": 195, "uid": "CIEN-6-195", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Variação Diária da Sombra do Gnômon", "dificuldade": "Fácil", "enunciado": "Ao observar a sombra projetada por um poste ou por uma haste vertical (gnômon) ao longo de um dia ensolarado e limpo, nota-se que o comprimento da sombra:", "alternativas": {"A": "Permanece exatamente igual do nascer ao pôr do sol.", "B": "É muito longa no início da manhã, atinge seu menor tamanho por volta do meio-dia solar e volta a ficar longa no final da tarde.", "C": "É minúscula pela manhã e atinge seu maior tamanho ao meio-dia.", "D": "Desaparece completamente durante toda a manhã e só surge à tarde.", "E": "Aponta sempre para o leste durante o dia inteiro."}, "resposta_correta": "B", "justificativa": "Pela manhã e no fim da tarde, o Sol está baixo no horizonte e seus raios incidem inclinados, gerando sombras extensas. Ao meio-dia solar, o Sol atinge sua maior altura aparente no céu (zênite local), tornando a sombra mínima.", "possui_imagem": true},
  {"id": 196, "uid": "CIEN-6-196", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Movimento Aparente do Sol", "dificuldade": "Fácil", "enunciado": "Todos os dias temos a nítida impressão visual de que o Sol 'nasce' no lado leste, cruza o céu e 'se põe' no lado oeste. Essa trajetória observada no céu é chamada de 'movimento aparente do Sol' porque:", "alternativas": {"A": "É o Sol que está girando ao redor da Terra parada no centro do universo.", "B": "É a Terra que está girando em torno de seu próprio eixo (de oeste para leste), criando a ilusão de que o Sol se move no sentido oposto.", "C": "A atmosfera empurra o Sol com ventos solares diários.", "D": "As nuvens cobrem o Sol pela manhã e o descobrem à tarde.", "E": "O Sol viaja em linha reta pelo espaço a cada 12 horas."}, "resposta_correta": "B", "justificativa": "Como o referencial do observador está na superfície terrestre em rotação de oeste para leste, os astros no céu (Sol, estrelas) parecem mover-se no sentido contrário (de leste para oeste). Trata-se de um movimento aparente.", "possui_imagem": false},
  {"id": 197, "uid": "CIEN-6-197", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Pontos Cardeais e Orientação Básica", "dificuldade": "Fácil", "enunciado": "Se você estiver em um descampado no início da manhã e apontar o braço direito para o lado onde o Sol está nascendo (aproximadamente o Leste), à sua frente, às suas costas e no seu braço esquerdo estarão, respectivamente, os pontos cardeais:", "alternativas": {"A": "Norte, Sul e Oeste.", "B": "Sul, Norte e Oeste.", "C": "Oeste, Leste e Norte.", "D": "Norte, Oeste e Sul.", "E": "Sul, Oeste e Leste."}, "resposta_correta": "A", "justificativa": "Pela convenção clássica dos pontos cardeais: braço direito para o Leste (nascente aproximado), braço esquerdo para o Oeste (poente), à frente fica o Norte e às costas fica o Sul.", "possui_imagem": true},
  {"id": 198, "uid": "CIEN-6-198", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "As Quatro Estações do Ano", "dificuldade": "Fácil", "enunciado": "Ao longo do período de translação da Terra, ocorrem alterações climáticas cíclicas e periódicas conhecidas como estações do ano. Quais são as quatro estações do ano?", "alternativas": {"A": "Verão, seca, chuva e tempestade.", "B": "Primavera, verão, outono e inverno.", "C": "Janeiro, abril, julho e outubro.", "D": "Equinócio, solstício, rotação e translação.", "E": "Calor, umidade, vento e geada."}, "resposta_correta": "B", "justificativa": "As quatro estações astronômicas canônicas da Terra são primavera, verão, outono e inverno.", "possui_imagem": true},
  {"id": 199, "uid": "CIEN-6-199", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Oposição de Estações entre Hemisférios", "dificuldade": "Fácil", "enunciado": "Quando no Hemisfério Sul (onde fica a maior parte do Brasil) estamos comemorando as festas de fim de ano no verão em dezembro, no Hemisfério Norte (onde ficam países como Estados Unidos e Japão) a estação do ano é o:", "alternativas": {"A": "Verão também.", "B": "Inverno.", "C": "Outono.", "D": "Primavera.", "E": "Clima polar de seca."}, "resposta_correta": "B", "justificativa": "Devido à inclinação do eixo terrestre, quando um hemisfério está inclinado em direção ao Sol (recebendo mais insolação - verão), o outro hemisfério oposto está inclinado para longe do Sol (recebendo menos insolação - inverno).", "possui_imagem": true},
  {"id": 200, "uid": "CIEN-6-200", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Conceito de Equinócio", "dificuldade": "Fácil", "enunciado": "Duas vezes ao ano ocorrem os chamados 'equinócios' (em março e setembro). A palavra equinócio tem origem no latim e significa 'noites iguais'. Nessa data astronômica especial:", "alternativas": {"A": "O Sol não se põe durante 24 horas em todo o planeta.", "B": "O dia claro e a noite escura têm praticamente a mesma duração (12 horas cada) em todo o planeta.", "C": "A Terra fica na distância mais distante possível do Sol.", "D": "A Lua cheia se funde com o Sol no meio do dia.", "E": "O planeta para de girar por algumas horas."}, "resposta_correta": "B", "justificativa": "Nos equinócios, a luz solar incide perpendicularmente sobre a linha do Equador e os dois hemisférios são iluminados simetricamente, fazendo com que o período diurno e noturno durem aproximadamente 12 horas em toda a Terra.", "possui_imagem": true},
  {"id": 201, "uid": "CIEN-6-201", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Conceito de Solstício", "dificuldade": "Fácil", "enunciado": "O solstício de verão em um determinado hemisfério marca:", "alternativas": {"A": "O dia mais frio de todo o ano naquele hemisfério.", "B": "O dia mais longo do ano (com maior período de luz solar) e a noite mais curta.", "C": "A noite mais longa do ano e o dia mais curto.", "D": "A data em que o Sol nasce exatamente no Polo Sul.", "E": "O momento em que a Lua passa na frente do Sol."}, "resposta_correta": "B", "justificativa": "No solstício de verão, o hemisfério atinge sua inclinação angular máxima em direção ao Sol, ocorrendo o dia com maior número de horas de luminosidade e a noite mais curta do ano.", "possui_imagem": true},
  {"id": 202, "uid": "CIEN-6-202", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Relógio de Sol", "dificuldade": "Fácil", "enunciado": "O relógio de sol é um aperfeiçoamento prático do gnômon. Ele permite estimar as horas do dia a partir de:", "alternativas": {"A": "A temperatura do metal da haste aquecido pelo calor do sol.", "B": "A posição e a direção da sombra projetada pela haste sobre uma escala graduada numerada.", "C": "A quantidade de poeira cósmica acumulada sobre a pedra.", "D": "A velocidade do vento ao redor da coluna central.", "E": "A cor da luz solar refletida em um espelho plano."}, "resposta_correta": "B", "justificativa": "À medida que o Sol muda sua posição aparente de leste para oeste durante o dia, a sombra da haste gira ao longo do mostrador graduado, indicando a passagem das horas solares.", "possui_imagem": true},
  {"id": 203, "uid": "CIEN-6-203", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Eixo de Rotação da Terra", "dificuldade": "Fácil", "enunciado": "O eixo imaginário em torno do qual a Terra gira durante o movimento de rotação passa exatamente por quais dois pontos geográficos da superfície do planeta?", "alternativas": {"A": "Trópico de Câncer e Trópico de Capricórnio.", "B": "Polo Norte geográfico e Polo Sul geográfico.", "C": "Linha do Equador e Meridiano de Greenwich.", "D": "Oceano Atlântico e Oceano Pacífico.", "E": "Floresta Amazônica e Deserto do Saara."}, "resposta_correta": "B", "justificativa": "O eixo de rotação terrestre é uma linha imaginária reta que atravessa o centro da Terra de um extremo a outro, conectando os polos geográficos Norte e Sul.", "possui_imagem": true},
  {"id": 204, "uid": "CIEN-6-204", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "A Sombra ao Meio-Dia Solar", "dificuldade": "Fácil", "enunciado": "Em qualquer dia do ano, o momento em que a sombra projetada por um gnômon vertical atinge o menor comprimento do dia corresponde ao:", "alternativas": {"A": "Amanhecer no horizonte.", "B": "Meio-dia solar (momento em que o Sol atinge sua altura máxima no céu).", "C": "Pôr do sol no horizonte oeste.", "D": "Meia-noite astronômica.", "E": "Momento do café da tarde às 16 horas."}, "resposta_correta": "B", "justificativa": "O meio-dia solar local ocorre quando o Sol culmina no meridiano do observador, atingindo o ponto mais alto de sua trajetória no céu naquele dia, momento em que a sombra da haste é a mais curta possível.", "possui_imagem": false},
  {"id": 205, "uid": "CIEN-6-205", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Iluminação da Terra pelo Sol", "dificuldade": "Fácil", "enunciado": "Como a Terra possui formato esférico (geoide) e a luz do Sol se propaga em linha reta no espaço, o Sol ilumina a superfície terrestre:", "alternativas": {"A": "Em 100% da área do planeta ao mesmo tempo.", "B": "Apenas na metade (hemisfério) voltada para ele a cada instante, enquanto a outra metade permanece na escuridão.", "C": "Apenas nos polos, deixando o centro da Terra sempre no escuro.", "D": "De dentro para fora, através de vulcões submarinos.", "E": "Exclusivamente durante os finais de semana."}, "resposta_correta": "B", "justificativa": "Sendo a Terra um corpo esférico opaco iluminado por uma fonte de luz externa distante, apenas metade de sua superfície pode ser atingida pelos raios solares simultaneamente, delimitando o dia e a noite pelo círculo de iluminação.", "possui_imagem": true},
  {"id": 206, "uid": "CIEN-6-206", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Comprimento das Sombras no Inverno vs. Verão", "dificuldade": "Fácil", "enunciado": "Se compararmos o comprimento da menor sombra do dia (ao meio-dia solar) projetada por um mesmo gnômon em duas épocas diferentes na cidade de São Paulo, verificaremos que:", "alternativas": {"A": "A sombra ao meio-dia é mais longa no inverno do que no verão.", "B": "A sombra ao meio-dia é mais longa no verão do que no inverno.", "C": "O gnômon não projeta sombra alguma durante o inverno.", "D": "O tamanho da sombra é rigorosamente o mesmo em todos os dias do ano.", "E": "No inverno a sombra aponta para o céu em vez de para o chão."}, "resposta_correta": "A", "justificativa": "No inverno, o Sol passa mais baixo no horizonte ao meio-dia, projetando raios mais oblíquos e sombras mais longas. No verão, o Sol passa mais alto (próximo do zênite), projetando sombras bem menores ao meio-dia.", "possui_imagem": true},
  {"id": 207, "uid": "CIEN-6-207", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Sentido de Rotação da Terra", "dificuldade": "Fácil", "enunciado": "Quando observada do espaço sideral olhando de cima para o Polo Norte geográfico, a Terra gira em torno de seu eixo no sentido:", "alternativas": {"A": "Horário (de leste para oeste).", "B": "Anti-horário (de oeste para leste).", "C": "De sul para norte.", "D": "De cima para baixo em linha reta.", "E": "Aleatório, invertendo de sentido a cada semana."}, "resposta_correta": "B", "justificativa": "O sentido de rotação da Terra é de oeste para leste, o que corresponde ao sentido anti-horário quando visualizado a partir do Polo Norte celeste.", "possui_imagem": false},
  {"id": 208, "uid": "CIEN-6-208", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Uso do Gnômon na Antiguidade", "dificuldade": "Fácil", "enunciado": "Civilizações antigas como egípcios, babilônios, chineses e gregos utilizavam o gnômon principalmente para:", "alternativas": {"A": "Prever chuvas com barômetros a vácuo.", "B": "Determinar os pontos cardeais, identificar as estações do ano e medir a passagem do tempo.", "C": "Localizar minas de ouro no subsolo através de magnetismo.", "D": "Medir a profundidade dos oceanos.", "E": "Fabricar espelhos de vidro transparentes."}, "resposta_correta": "B", "justificativa": "Ao acompanhar a trajetória e o tamanho das sombras projetadas pelo gnômon ao longo dos dias e meses, os astrônomos antigos estabeleceram calendários agrícolas, definiram solstícios/equinócios e orientaram cidades segundo os pontos cardeais.", "possui_imagem": false},
  {"id": 209, "uid": "CIEN-6-209", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Causa Real das Estações do Ano", "dificuldade": "Médio", "enunciado": "Muitas pessoas acreditam erroneamente que o verão ocorre porque a Terra está 'mais perto do Sol' e o inverno porque ela está 'mais longe do Sol'. A verdadeira explicação científica para a existência das estações do ano é:", "alternativas": {"A": "A velocidade da rotação da Terra, que fica mais rápida no verão.", "B": "A inclinação do eixo de rotação da Terra (cerca de 23,5º) em relação ao plano de sua órbita combinada com o movimento de translação ao redor do Sol.", "C": "As explosões solares periódicas que aquecem a atmosfera a cada seis meses.", "D": "A presença da Lua, que bloqueia os ventos frios no verão.", "E": "A fumaça das queimadas e vulcões que esfria a Terra no inverno."}, "resposta_correta": "B", "justificativa": "A órbita da Terra é quase circular (excentricidade mínima, variando apenas 3% entre afélio e periélio). A causa real e primária das estações é a inclinação de 23,5º do eixo de rotação terrestre associada à translação, determinando variações angulares na incidência solar e na duração do dia em cada hemisfério.", "possui_imagem": true},
  {"id": 210, "uid": "CIEN-6-210", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Ângulo de Incidência dos Raios Solares", "dificuldade": "Médio", "enunciado": "No verão de um determinado hemisfério, os raios solares incidem de maneira mais perpendicular (mais reta) sobre a superfície, enquanto no inverno incidem de maneira mais inclinada (oblíqua). Por que a incidência mais perpendicular aquece mais o solo?", "alternativas": {"A": "Porque a luz solar perpendicular contém átomos de fogo concentrados.", "B": "Porque a mesma quantidade de energia solar concentra-se em uma área menor de solo e atravessa uma camada menor de atmosfera, gerando maior densidade de calor por metro quadrado.", "C": "Porque raios inclinados não conseguem passar pelas nuvens.", "D": "Porque no inverno a gravidade do solo repele os raios de luz.", "E": "Porque o Sol se torna uma estrela azul durante o verão."}, "resposta_correta": "B", "justificativa": "Raios solares verticais concentram seu feixe energético sobre uma área restrita e sofrem menor atenuação atmosférica. Raios oblíquos espalham a mesma energia por uma superfície muito mais extensa e atravessam uma coluna maior de ar, aquecendo menos o solo.", "possui_imagem": false},
  {"id": 211, "uid": "CIEN-6-211", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Determinação da Linha Norte-Sul pelo Gnômon", "dificuldade": "Médio", "enunciado": "Um método astronômico milenar para determinar com precisão a direção Norte-Sul geográfica em qualquer lugar da Terra consiste em cravar uma haste vertical (gnômon) no chão e marcar a ponta de sua sombra ao longo do dia. A reta que une a base da haste à ponta da sombra no instante em que ela atinge o seu menor comprimento do dia aponta exatamente para a:", "alternativas": {"A": "Linha Leste-Oeste.", "B": "Linha Norte-Sul geográfica (meridiano local).", "C": "Direção da Linha do Equador.", "D": "Posição da Lua cheia daquela noite.", "E": "Direção do centro da Terra."}, "resposta_correta": "B", "justificativa": "A sombra mínima ocorre no meio-dia solar verdadeiro, quando o Sol transita pelo meridiano celeste do local. Nesse momento exato, a sombra projeta-se perfeitamente alinhada sobre a linha meridiana Norte-Sul geográfica.", "possui_imagem": false},
  {"id": 212, "uid": "CIEN-6-212", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Trajetória Aparente do Sol no Hemisfério Sul", "dificuldade": "Médio", "enunciado": "Para um observador localizado na cidade de Curitiba (ao sul do Trópico de Capricórnio), ao olhar para o céu durante o meio-dia solar ao longo de todo o ano, o Sol estará sempre culminando na direção:", "alternativas": {"A": "Sul do céu.", "B": "Norte do céu.", "C": "Leste do céu.", "D": "Oeste do céu.", "E": "Exatamente no zênite em todos os dias do ano."}, "resposta_correta": "B", "justificativa": "Como Curitiba está em latitude subtropical sul (cerca de 25º S), ao sul do Trópico de Capricórnio (23,5º S), o Sol atinge sua altura máxima diária sempre inclinado para a porção Norte do céu. Consequentemente, a sombra do gnômon ao meio-dia aponta sempre para o Sul.", "possui_imagem": false},
  {"id": 213, "uid": "CIEN-6-213", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Sol da Meia-Noite e Noite Polar", "dificuldade": "Médio", "enunciado": "Nas regiões situadas acima do Círculo Polar Ártico ou abaixo do Círculo Polar Antártico, ocorrem fenômenos astronômicos extremos: durante o solstício de verão local, o Sol não se põe no horizonte por 24 horas ('Sol da meia-noite'); no solstício de inverno, o Sol não nasce por 24 horas ('Noite polar'). Esse fenômeno é explicado por:", "alternativas": {"A": "A forma cúbica dos polos terrestres.", "B": "A inclinação do eixo terrestre, que faz com que a calota polar fique voltada inteiramente para o Sol no verão e fique na sombra completa da Terra no inverno durante a rotação.", "C": "A ausência de atmosfera gasosa nas regiões frias do planeta.", "D": "O congelamento do movimento de translação da Terra durante o inverno.", "E": "A interferência magnética que atrai o Sol para os polos."}, "resposta_correta": "B", "justificativa": "Devido à inclinação de 23,5º, durante os meses em torno do solstício de verão de um polo, toda a região polar permanece no lado iluminado pelo Sol durante as 24 horas de rotação diária; no inverno oposto, ela permanece inteiramente na sombra da própria Terra.", "possui_imagem": false},
  {"id": 214, "uid": "CIEN-6-214", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Solstício de Verão no Brasil: Data e Efeitos", "dificuldade": "Médio", "enunciado": "No Brasil e em todo o Hemisfério Sul, o solstício de verão ocorre anualmente por volta dos dias 21 ou 22 de dezembro. Nesse momento astronômico específico:", "alternativas": {"A": "Os raios solares atingem o zênite perpendicularmente sobre o Trópico de Capricórnio (latitude 23,5º S).", "B": "Os raios solares incidem perpendicularmente sobre o Trópico de Câncer.", "C": "A Terra atinge o ponto de maior afastamento do Sol em sua órbita (afélio).", "D": "A duração da noite em São Paulo é maior do que a duração do dia claro.", "E": "O Sol nasce exatamente no ponto cardeal Oeste."}, "resposta_correta": "A", "justificativa": "No solstício de dezembro, a declinação solar é máxima no Sul (-23,5º), atingindo perpendicularmente o Trópico de Capricórnio ao meio-dia solar, marcando o início astronômico do verão no Hemisfério Sul.", "possui_imagem": false},
  {"id": 215, "uid": "CIEN-6-215", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Equinócios de Outono e Primavera: Trajetória do Sol", "dificuldade": "Médio", "enunciado": "Em apenas dois dias do ano (durante os equinócios de março e setembro), o Sol nasce RIGOROSAMENTE sobre o ponto cardeal Leste exato e se põe no ponto cardeal Oeste exato em qualquer localidade da Terra (exceto nos polos). Nos outros dias do ano:", "alternativas": {"A": "O Sol nasce e se põe sempre no mesmo ponto exato do horizonte sem variação.", "B": "O Sol nasce com desvios angulares para o nordeste (no verão do norte/inverno do sul) ou para o sudeste (no verão do sul/inverno do norte).", "C": "O Sol nasce no ponto cardeal Norte e se põe no ponto cardeal Sul.", "D": "O Sol nasce à meia-noite e se põe ao meio-dia.", "E": "O Sol não se põe no horizonte em nenhum país."}, "resposta_correta": "B", "justificativa": "O nascer rigoroso no ponto cardeal Leste (azimute 90º) e ocaso no Oeste (azimute 270º) só ocorre nos equinócios. Nos demais dias, a posição do nascente desloca-se sazonalmente para o Norte (de abril a agosto) ou para o Sul (de outubro a fevereiro).", "possui_imagem": false},
  {"id": 216, "uid": "CIEN-6-216", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Periélio e Afélio: Desmistificando Distâncias", "dificuldade": "Médio", "enunciado": "A Terra passa pelo periélio (ponto mais próximo do Sol, a cerca de 147 milhões de km) no início de janeiro e passa pelo afélio (ponto mais distante do Sol, a cerca de 152 milhões de km) no início de julho. Sabendo que em janeiro é pleno inverno no Hemisfério Norte, esse fato astronômico comprova indiscutivelmente que:", "alternativas": {"A": "A distância entre a Terra e o Sol é o fator determinante que causa o frio do inverno no mundo todo.", "B": "A variação na distância Terra-Sol ao longo da órbita elíptica NÃO é a causa das estações do ano, sendo a inclinação do eixo o fator preponderante.", "C": "A órbita da Terra é uma elipse extremamente esticada como a de um cometa.", "D": "Em janeiro o Hemisfério Norte não recebe nenhuma luz do Sol.", "E": "O afélio e o periélio acontecem apenas a cada dez anos."}, "resposta_correta": "B", "justificativa": "Se a distância ao Sol fosse a causa das estações, todo o planeta teria verão e inverno ao mesmo tempo. O fato de o Hemisfério Norte estar no inverno mais frio em janeiro (quando a Terra está no periélio) prova que a distância orbital é secundária frente à inclinação axial.", "possui_imagem": false},
  {"id": 217, "uid": "CIEN-6-217", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Experimento Histórico de Eratóstenes", "dificuldade": "Médio", "enunciado": "No século III a.C., o astrônomo grego Eratóstenes mediu com impressionante precisão a circunferência da Terra sem sair do Egito. Para isso, ele utilizou a comparação das sombras de gnômons ao meio-dia do solstício de verão em duas cidades:", "alternativas": {"A": "Roma e Atenas.", "B": "Siena (atual Assuã), onde o Sol não projetava sombra no fundo de um poço, e Alexandria, onde o gnômon projetava uma sombra correspondente a cerca de 7,2º.", "C": "Cairo e Jerusalém, medindo a velocidade da luz em espelhos planos.", "D": "Esparta e Constantinopla, usando relógios mecânicos de pêndulo.", "E": "Londres e Paris, cronometrando o canto dos pássaros."}, "resposta_correta": "B", "justificativa": "Eratóstenes sabia que em Siena o Sol estava a pino (zênite) no solstício. Medindo a sombra de um gnômon em Alexandria na mesma data e hora, obteve uma inclinação de 7,2º (1/50 de 360º). Multiplicando a distância entre as cidades por 50, calculou o perímetro da Terra com erro inferior a 5%.", "possui_imagem": false},
  {"id": 218, "uid": "CIEN-6-218", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Método dos Círculos Indianos para Alinhamento", "dificuldade": "Médio", "enunciado": "Para traçar os pontos cardeais com um gnômon com precisão, utiliza-se a técnica dos círculos concêntricos: desenha-se um círculo no chão ao redor da base da haste. Pela manhã, marca-se o ponto A onde a ponta da sombra toca o círculo. À tarde, marca-se o ponto B onde a sombra toca o mesmo círculo novamente. A reta que une os pontos A e B define:", "alternativas": {"A": "A linha Norte-Sul geográfica.", "B": "A linha Leste-Oeste (com A indicando oeste e B indicando leste da sombra).", "C": "A latitude exata da cidade.", "D": "A altitude do terreno em relação ao nível do mar.", "E": "A declinação magnética da bússola."}, "resposta_correta": "B", "justificativa": "Como as sombras têm comprimentos idênticos nos dois momentos simétricos antes e depois do meio-dia, o segmento que conecta esses dois pontos é paralelo à linha Leste-Oeste verdadeira; a mediatriz perpendicular a esse segmento fornece a linha Norte-Sul meridiana.", "possui_imagem": false},
  {"id": 219, "uid": "CIEN-6-219", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Fusos Horários e Rotação Terrestre", "dificuldade": "Médio", "enunciado": "A Terra possui 360º de circunferência e completa uma rotação em aproximadamente 24 horas. Dividindo 360º por 24 horas, obtém-se 15º por hora. Esse cálculo matemático e astronômico é a base para:", "alternativas": {"A": "A divisão do planeta em 24 fusos horários de 15º de longitude cada.", "B": "O cálculo da velocidade dos ventos na linha do equador.", "C": "A medição da profundidade dos oceanos por sonar.", "D": "A definição da distância entre os continentes em quilômetros.", "E": "A determinação do número de semanas de cada mês."}, "resposta_correta": "A", "justificativa": "Cada fuso horário padrão abrange uma faixa longitudinal de 15º (360º / 24 h = 15º/h). A cada 15º de deslocamento para o leste, adianta-se uma hora no relógio civil; para o oeste, atrasa-se uma hora.", "possui_imagem": false},
  {"id": 220, "uid": "CIEN-6-220", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Variação Anual da Posição do Meio-Dia no Horizonte", "dificuldade": "Médio", "enunciado": "Se fotografarmos a posição do Sol no céu exatamente no mesmo horário civil (por exemplo, às 12h00) todos os dias ao longo de um ano a partir de uma câmera fixa, o Sol desenhará no céu uma figura em forma de '8' alongado. Essa figura celeste é conhecida como:", "alternativas": {"A": "Analema solar.", "B": "Órbita elíptica lunar.", "C": "Constelação zodiacal.", "D": "Equinócio de precessão.", "E": "Efeito estufa cósmico."}, "resposta_correta": "A", "justificativa": "O analema solar é a figura em formato de oito traçada pela posição do Sol ao longo do ano no mesmo horário médio, resultante da inclinação do eixo terrestre combinada com a excentricidade da órbita elíptica (equação do tempo).", "possui_imagem": false},
  {"id": 221, "uid": "CIEN-6-221", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Efeito da Latitude na Duração dos Dias", "dificuldade": "Médio", "enunciado": "Na linha do Equador terrestre (latitude 0º), a duração do dia claro e da noite ao longo do ano apresenta uma particularidade marcante quando comparada a cidades no extremo sul do Chile ou norte da Noruega. Essa particularidade é:", "alternativas": {"A": "No Equador, o verão dura 12 meses com 24 horas de sol contínuas.", "B": "No Equador, a duração do dia e da noite é praticamente constante durante todo o ano, com cerca de 12 horas de luz e 12 horas de escuridão todos os dias.", "C": "No Equador, a noite dura 20 horas no mês de julho.", "D": "No Equador, o Sol nunca nasce de manhã.", "E": "No Equador, os dias são sempre mais curtos que as noites em qualquer estação."}, "resposta_correta": "B", "justificativa": "Como o plano equatorial divide a esfera terrestre ao meio, o círculo de iluminação solar intercepta a linha do Equador sempre em duas metades iguais em qualquer época do ano, mantendo o fotoperíodo constante em cerca de 12 horas diárias.", "possui_imagem": false},
  {"id": 222, "uid": "CIEN-6-222", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Solstício de Inverno e a Menor Altura do Sol", "dificuldade": "Médio", "enunciado": "No solstício de inverno no Hemisfério Sul (por volta de 21 de junho), a trajetória aparente do Sol pelo céu ao longo do dia é:", "alternativas": {"A": "A mais alta e longa de todo o ano, nascendo no sudeste e se pondo no sudoeste.", "B": "A mais baixa e curta de todo o ano, nascendo no nordeste e se pondo no noroeste, produzindo o dia com menor número de horas de luz e a noite mais longa.", "C": "Exatamente igual à trajetória do solstício de verão.", "D": "Totalmente vertical, passando pelo zênite de todas as cidades brasileiras.", "E": "Completamente subterrânea, não havendo luz solar em nenhum estado do Brasil."}, "resposta_correta": "B", "justificativa": "No solstício de junho (inverno austral), o Sol tem sua declinação mais ao norte (+23,5º). No Hemisfério Sul, o arco aparente do Sol pelo céu é o mais baixo e mais curto do ano, resultando no menor período de luz solar (fotoperíodo mínimo).", "possui_imagem": false},
  {"id": 223, "uid": "CIEN-6-223", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Diferença entre Meio-Dia Solar e Meio-Dia Civil", "dificuldade": "Médio", "enunciado": "Quando o relógio de pulso marca exatamente 12h00 em Brasília, não significa necessariamente que seja o meio-dia solar verdadeiro (sombra mínima do gnômon) em todas as cidades daquele fuso horário. Essa diferença entre a hora civil e a hora solar local ocorre porque:", "alternativas": {"A": "Os relógios mecânicos e digitais atrasam 2 horas todos os dias no verão.", "B": "A hora civil é padronizada uniformemente para toda a extensão territorial do fuso horário com base no meridiano central (como o meridiano de 45º O para o horário de Brasília), enquanto o meio-dia solar depende da longitude local exata de cada cidade.", "C": "O Sol para de brilhar durante o almoço em algumas cidades.", "D": "A velocidade de rotação da Terra varia conforme a cidade é grande ou pequena.", "E": "A atmosfera impede que a luz do meio-dia chegue ao interior do país."}, "resposta_correta": "B", "justificativa": "O horário civil oficial é uma convenção política e administrativa unificada para toda a faixa do fuso horário; já o meio-dia solar verdadeiro é um evento puramente astronômico local que depende da longitude precisa do observador.", "possui_imagem": false},
  {"id": 224, "uid": "CIEN-6-224", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Horário de Verão: Conceito e Relação com a Astronomia", "dificuldade": "Médio", "enunciado": "Em muitos países e regiões de latitudes médias e altas, adota-se o 'horário de verão', adiantando os relógios em uma hora durante os meses mais quentes. A justificativa astronômica que viabiliza essa medida é:", "alternativas": {"A": "No verão, os dias claros têm maior duração que as noites, permitindo aproveitar mais a luz natural no final da tarde e economizar energia elétrica.", "B": "No verão, a Terra gira mais devagar, fazendo o dia durar 26 horas.", "C": "O horário de verão resfria a temperatura da atmosfera em 5 ºC.", "D": "As estrelas no céu brilham menos durante os meses de calor.", "E": "No verão, o Sol nasce às 14 horas da tarde."}, "resposta_correta": "A", "justificativa": "Em latitudes médias no verão, o solstício prolonga a claridade natural (o Sol nasce mais cedo e se põe mais tarde). Adiantar os relógios sincroniza o período de atividade humana com o período de iluminação solar vespertina.", "possui_imagem": false},
  {"id": 225, "uid": "CIEN-6-225", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Pontos Cardeais e Colaterais na Rosa dos Ventos", "dificuldade": "Médio", "enunciado": "A rosa dos ventos é a representação gráfica tradicional das direções de orientação espacial. Além dos quatro pontos cardeais (Norte, Sul, Leste, Oeste), existem os pontos colaterais intermediários. Quais são os pontos colaterais situados entre os cardeais correspondentes?", "alternativas": {"A": "Nordeste (NE), Sudeste (SE), Sudoeste (SO/SW) e Noroeste (NO/NW).", "B": "Zênite, Nadir, Horizonte e Meridiano.", "C": "Trópico, Equador, Polo e Círculo polar.", "D": "Leste-Norte, Sul-Oeste, Norte-Leste e Sul-Leste.", "E": "Ártico, Antártico, Atlântico e Pacífico."}, "resposta_correta": "A", "justificativa": "Os quatro pontos colaterais dividem os quadrantes cardeais a 45º: Nordeste (entre N e L), Sudeste (entre S e L), Sudoeste (entre S e O) e Noroeste (entre N e O).", "possui_imagem": false},
  {"id": 226, "uid": "CIEN-6-226", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Zênite e Nadir na Esfera Celeste", "dificuldade": "Médio", "enunciado": "Na astronomia posicional e no estudo do gnômon, utiliza-se a esfera celeste local. O ponto imaginário situado exatamente na vertical acima da cabeça de um observador (a 90º do horizonte) e o ponto oposto situado diretamente abaixo de seus pés são chamados, respectivamente, de:", "alternativas": {"A": "Nadir e Zênite.", "B": "Zênite e Nadir.", "C": "Polo e Equador.", "D": "Afélio e Periélio.", "E": "Solstício e Equinócio."}, "resposta_correta": "B", "justificativa": "O Zênite é a intersecção da vertical superior local com a esfera celeste (o ponto mais alto do céu sobre o observador). O Nadir é o ponto oposto diametralmente, na vertical descendente sob os pés do observador.", "possui_imagem": false},
  {"id": 227, "uid": "CIEN-6-227", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "O Gnômon e a Identificação dos Solstícios", "dificuldade": "Médio", "enunciado": "Se um astrônomo registrar diariamente o comprimento da menor sombra do meio-dia projetada por um gnômon durante um ano inteiro em uma cidade como São Paulo, ele identificará os solstícios de verão e de inverno observando, respectivamente:", "alternativas": {"A": "O dia em que a sombra do meio-dia for a mais curta de todo o ano e o dia em que ela for a mais longa de todo o ano.", "B": "O dia em que a sombra do meio-dia desaparecer à meia-noite e o dia em que o Sol congelar.", "C": "O dia com maior umidade do ar e o dia com menor temperatura do solo.", "D": "Dias em que a sombra apontar rigorosamente para o leste.", "E": "Dias em que a haste do gnômon dobrar de tamanho físico."}, "resposta_correta": "A", "justificativa": "No solstício de verão, o Sol atinge sua maior elevação angular ao meio-dia, projetando a sombra mínima anual. No solstício de inverno, o Sol passa na menor elevação angular ao meio-dia, gerando a maior sombra mínima anual.", "possui_imagem": false},
  {"id": 228, "uid": "CIEN-6-228", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Fuso Horário no Brasil", "dificuldade": "Médio", "enunciado": "O território brasileiro, devido à sua grande extensão longitudinal no sentido leste-oeste, abrange quatro fusos horários oficiais distintos a oeste do Meridiano de Greenwich (UTC-2, UTC-3, UTC-4 e UTC-5). O fuso horário de referência de Brasília, adotado pela maioria dos estados brasileiros (como São Paulo, Rio de Janeiro e Minas Gerais), corresponde a:", "alternativas": {"A": "UTC+0 (horário de Londres).", "B": "UTC-3 (três horas a menos em relação a Greenwich).", "C": "UTC-5 (cinco horas a menos em relação a Greenwich).", "D": "UTC+3 (três horas a mais em relação a Greenwich).", "E": "UTC-12 (doze horas a menos em relação a Greenwich)."}, "resposta_correta": "B", "justificativa": "O horário oficial de Brasília está no fuso UTC-3 (três horas atrasado em relação ao Tempo Universal Coordenado / meridiano de Greenwich de 0º).", "possui_imagem": false},
  {"id": 229, "uid": "CIEN-6-229", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Latitude e a Inclinação da Sombra do Gnômon", "dificuldade": "Médio", "enunciado": "Dois estudantes instalaram gnômons idênticos de 1 metro de altura e mediram a sombra ao meio-dia solar exatamente no dia do equinócio de primavera:\n- Estudante A: na cidade de Macapá (localizada exatamente sobre a Linha do Equador, latitude 0º).\n- Estudante B: na cidade de Porto Alegre (latitude aproximada de 30º S).\nO que eles observaram em relação ao comprimento da sombra no meio-dia solar nessa data?", "alternativas": {"A": "O estudante A observou uma sombra de 2 metros e o estudante B não observou sombra.", "B": "O estudante A observou sombra de comprimento zero (o Sol estava a pino no zênite, sem projetar sombra lateral), enquanto o estudante B observou uma sombra inclinada apontando para o sul.", "C": "Ambos observaram sombras de comprimento rigorosamente igual a 1 metro.", "D": "Nenhum dos dois observou sombra porque era dia de chuva.", "E": "A sombra do estudante A apontou para o oeste e a do estudante B para o leste."}, "resposta_correta": "B", "justificativa": "No equinócio, os raios solares atingem a Terra a 90º na linha do Equador (latitude 0º); portanto, em Macapá, o Sol culmina no zênite e a haste vertical não projeta sombra no chão plano. Em Porto Alegre (30º S), o Sol culmina a 60º do horizonte norte, projetando sombra voltada para o sul.", "possui_imagem": false},
  {"id": 230, "uid": "CIEN-6-230", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Trigonometria do Gnômon e Latitude Local", "dificuldade": "Difícil", "enunciado": "Em um dia de equinócio, um observador mede a altura de um gnômon vertical (h = 100 cm) e o comprimento de sua sombra projetada no chão plano exatamente ao meio-dia solar (s = 57,7 cm), com a sombra apontando para o Sul. Sabendo que a tangente do ângulo de inclinação zenital é dada por tan(Z) = s / h = 0,577 (cujo arco tangente é 30º), a latitude geográfica do observador é:", "alternativas": {"A": "30º Norte.", "B": "30º Sul.", "C": "60º Sul.", "D": "0º (Equador).", "E": "45º Norte."}, "resposta_correta": "B", "justificativa": "No equinócio, a declinação solar é 0º. Logo, a distância zenital ao meio-dia solar é igual à própria latitude do observador (Z = latitude). Como a sombra apontou para o Sul, o Sol culminou no Norte, o que situa o observador no Hemisfério Sul; portanto, latitude = 30º S.", "possui_imagem": false},
  {"id": 231, "uid": "CIEN-6-231", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Dia Sideral vs. Dia Solar Médio", "dificuldade": "Difícil", "enunciado": "O tempo que a Terra leva para completar uma rotação de 360º exatos em relação a estrelas fixas distantes é de aproximadamente 23 horas, 56 minutos e 4 segundos (dia sideral). No entanto, o dia solar médio civil tem 24 horas (cerca de 4 minutos a mais). Essa diferença de 4 minutos diários ocorre porque:", "alternativas": {"A": "Os relógios atômicos se descalibram devido à atração magnética da Lua.", "B": "Enquanto a Terra gira em torno de seu eixo, ela também se desloca cerca de 1º ao longo de sua órbita de translação ao redor do Sol; para que o Sol volte a culminar no mesmo meridiano, a Terra precisa girar aproximadamente 1º adicional (cerca de 4 minutos de rotação).", "C": "A atmosfera da Terra desacelera a velocidade da luz do Sol em 4 minutos.", "D": "O Sol se expande e se contrai diariamente no espaço.", "E": "O núcleo da Terra para de girar por 4 minutos toda noite."}, "resposta_correta": "B", "justificativa": "Como a Terra translada cerca de 360º em 365 dias (~1º por dia), após completar 360º de rotação em relação às estrelas (dia sideral), o Sol aparente ainda não se alinhou com o meridiano local; a Terra precisa girar mais ~1º (24 h / 360º = 4 min/grau) para completar o dia solar.", "possui_imagem": false},
  {"id": 232, "uid": "CIEN-6-232", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Cálculo Rigoroso do Experimento de Eratóstenes", "dificuldade": "Difícil", "enunciado": "Suponha que um grupo de escolas repita o experimento de Eratóstenes entre duas cidades localizadas no mesmo meridiano: uma cidade A, onde o Sol fica a pino (sombra zero) no solstício, e uma cidade B, onde a sombra de um gnômon vertical ao meio-dia solar forma um ângulo de 9º com a vertical. Se a distância terrestre em linha reta medida entre as cidades for de 1.000 km, qual é a estimativa calculada para a circunferência total da Terra?", "alternativas": {"A": "10.000 km.", "B": "40.000 km.", "C": "90.000 km.", "D": "360.000 km.", "E": "4.000 km."}, "resposta_correta": "B", "justificativa": "A circunferência completa da Terra equivale a 360º. A fração angular medida é 9º / 360º = 1/40 da circunferência. Se 1/40 da Terra corresponde a 1.000 km, o perímetro total é: C = 1.000 km x 40 = 40.000 km (valor extremamente próximo do real, que é ~40.075 km no equador).", "possui_imagem": false},
  {"id": 233, "uid": "CIEN-6-233", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "A Parada Aparente do Sol no Solstício", "dificuldade": "Difícil", "enunciado": "A palavra 'solstício' vem do latim solstitium, que significa 'sol parado'. Na perspectiva observacional de um gnômon, por que esse evento astronômico recebeu o nome de 'sol parado'?", "alternativas": {"A": "Porque a Terra interrompe completamente o movimento de translação por 48 horas.", "B": "Porque nas semanas próximas ao solstício, a altura máxima do Sol ao meio-dia e a posição do nascer/pôr do sol no horizonte variam tão lentamente que o Sol parece 'estacionar' na sua declinação extrema antes de inverter o sentido de seu movimento aparente anual.", "C": "Porque a sombra do gnômon congela no chão sem se mover durante o dia todo.", "D": "Porque o Sol deixa de emitir luz visível durante o solstício de inverno.", "E": "Porque a Lua cheia cobre o Sol mantendo-o estático no céu."}, "resposta_correta": "B", "justificativa": "Na aproximação dos solstícios, a derivada da declinação solar em relação ao tempo tende a zero (máximo ou mínimo na senoide anual). Ao longo de vários dias, o ponto de nascer no horizonte e a altura meridiana do Sol praticamente não variam perceptivelmente a olho nu, parecendo 'parados'.", "possui_imagem": false},
  {"id": 234, "uid": "CIEN-6-234", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Insolação e Massa de Ar Atmosférica", "dificuldade": "Difícil", "enunciado": "A atenuação da radiação solar ao atravessar a atmosfera terrestre é expressa em física atmosférica pelo conceito de 'massa de ar óptica' (AM). Quando o Sol está no zênite (raios a 90º), temos AM = 1,0. Quando o Sol está a apenas 30º acima do horizonte (como no meio-dia de inverno em altas latitudes), os raios atravessam o dobro da camada atmosférica (AM = 2,0). Isso implica que, além do espalhamento geométrico no solo, o frio do inverno é agravado porque:", "alternativas": {"A": "O ar frio do espaço sideral é sugado pela luz solar inclinada.", "B": "Os raios solares sofrem muito maior absorção e espalhamento por gases, poeira e aerossóis ao percorrer uma coluna muito mais espessa de atmosfera, reduzindo drasticamente a irradiação direta que atinge a superfície.", "C": "O ozônio atmosférico transforma os raios solares em nitrogênio líquido.", "D": "A atmosfera polar repele a gravidade dos fótons solares.", "E": "As moléculas de oxigênio entram em combustão espontânea no horizonte."}, "resposta_correta": "B", "justificativa": "Com ângulos solares baixos, o comprimento do caminho óptico através da atmosfera é proporcional a 1/sen(h). Uma coluna atmosférica maior dissipa e espalha proporcionalmente mais radiação por espalhamento Rayleigh e absorção por vapor de água e aerossóis.", "possui_imagem": false},
  {"id": 235, "uid": "CIEN-6-235", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Zona Intertropical e Dias Sem Sombra (Dia Zenital)", "dificuldade": "Difícil", "enunciado": "Localidades situadas dentro da faixa tropical do planeta (entre o Trópico de Câncer, 23,5º N, e o Trópico de Capricórnio, 23,5º S), como a cidade de Salvador (latitude 13º S), vivenciam um fenômeno singular duas vezes por ano conhecido como 'Dia do Sol Zenital' (ou 'Dia Sem Sombra'). Nesse dia:", "alternativas": {"A": "A Lua bloqueia o Sol durante todo o expediente de trabalho.", "B": "A declinação do Sol coincide com a latitude da cidade, de modo que o Sol passa rigorosamente pelo zênite (90º) ao meio-dia solar e objetos verticais perfeitamente retos não projetam sombra ao seu redor.", "C": "O Sol nasce no Norte e se põe no Sul sem cruzar o zênite.", "D": "A atmosfera fica 100% transparente permitindo ver estrelas ao meio-dia.", "E": "A sombra do gnômon se expande até cobrir a cidade inteira."}, "resposta_correta": "B", "justificativa": "Como a declinação solar aparente oscila ciclicamente entre +23,5º e -23,5º ao longo do ano, em qualquer ponto da zona intertropical o Sol atinge o zênite exato em duas datas específicas anuais, momento no qual uma haste vertical não projeta sombra no solo ao meio-dia solar.", "possui_imagem": false},
  {"id": 236, "uid": "CIEN-6-236", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "A Equação do Tempo no Relógio de Sol", "dificuldade": "Difícil", "enunciado": "Quem constrói um relógio de sol artesanal observa que, mesmo alinhado com perfeição, a hora indicada pela sombra do gnômon (tempo solar verdadeiro) pode adiantar em até cerca de 16 minutos (em novembro) ou atrasar em até 14 minutos (em fevereiro) em relação ao tempo medido por um relógio de quartzo uniforme. Essa discrepância periódica é descrita pela 'Equação do Tempo' e decorre de dois fatores físicos combinados:", "alternativas": {"A": "A velocidade da luz que varia no ar e o atrito dos continentes com os oceanos.", "B": "A excentricidade da órbita da Terra (2ª Lei de Kepler, velocidade orbital variável) e a inclinação de 23,5º do equador terrestre em relação ao plano da eclíptica.", "C": "A evaporação da água nos oceanos e o derretimento das geleiras polares.", "D": "O campo magnético da Terra que puxa a sombra do gnômon para o polo magnético.", "E": "A dilatação térmica do vidro dos relógios comuns de pulso."}, "resposta_correta": "B", "justificativa": "O tempo solar aparente é irregular por duas razões celestes: a velocidade orbital da Terra varia ao longo do ano pela elipse orbital (2ª Lei de Kepler) e o Sol se move na eclíptica inclinada, cuja projeção no equador celeste varia de ritmo ao longo das estações (analema).", "possui_imagem": false},
  {"id": 237, "uid": "CIEN-6-237", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Determinação da Hora Solar Local por Ângulo Horário", "dificuldade": "Difícil", "enunciado": "No mostrador de um relógio de sol equatorial (plano paralelo ao equador terrestre e gnômon apontado para o polo celeste), cada hora solar corresponde a um deslocamento angular da sombra de exatamente 15º. Se a sombra do gnômon se encontra deslocada 45º a leste da linha meridiana central, isso indica que a hora solar local é:", "alternativas": {"A": "09h00 (três horas antes do meio-dia solar).", "B": "15h00 (três horas após o meio-dia solar).", "C": "12h45 do meio-dia solar.", "D": "03h00 da madrugada astronômica.", "E": "18h00 do crepúsculo vespertino."}, "resposta_correta": "A", "justificativa": "Como a Terra gira 15º a cada 60 minutos, 45º / 15º = 3 horas. Pela manhã, o Sol está no leste e a sombra projeta-se no oeste (ou no mostrador equatorial, o ângulo horário é matutino correspondendo a 12h - 3h = 9h00 da manhã).", "possui_imagem": false},
  {"id": 238, "uid": "CIEN-6-238", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Movimentos Secundários da Terra: Precessão e Nutação", "dificuldade": "Difícil", "enunciado": "Além da rotação e da translação, a Terra executa outros movimentos orbitais lentos de longo prazo. O movimento de oscilação do eixo de rotação terrestre semelhante ao bamboleio de um pião que está perdendo velocidade, completando um ciclo a cada cerca de 25.770 anos, é denominado:", "alternativas": {"A": "Precessão dos equinócios.", "B": "Nutação polar lunar.", "C": "Translação elíptica acelerada.", "D": "Maré gravitacional solar.", "E": "Deriva continental de Wegener."}, "resposta_correta": "A", "justificativa": "A precessão dos equinócios é o movimento cônico lento do eixo de rotação da Terra gerado pelo torque gravitacional diferencial exercido pela Lua e pelo Sol sobre a protuberância equatorial do planeta, com período de aproximadamente 26 mil anos.", "possui_imagem": false},
  {"id": 239, "uid": "CIEN-6-239", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Pêndulo de Foucault e a Comprovação da Rotação", "dificuldade": "Difícil", "enunciado": "Em 1851, no Panteão de Paris, o físico Léon Foucault utilizou uma grande esfera de metal suspensa por um fio de 67 metros de comprimento (Pêndulo de Foucault) que oscilava livremente. Com o passar das horas, o plano de oscilação do pêndulo parecia girar lentamente no sentido horário, derrubando estacas de areia no chão. Esse experimento histórico foi a primeira demonstração direta em laboratório de que:", "alternativas": {"A": "A gravidade da Terra diminui durante o inverno europeu.", "B": "A Terra está girando em torno de seu próprio eixo, sendo o chão sob o pêndulo que gira enquanto o plano de oscilação permanece fixo no espaço inercial.", "C": "O pêndulo é atraído por ondas de rádio do Polo Norte.", "D": "A Terra é um disco plano sustentado por colunas gigantescas.", "E": "A atmosfera terrestre gira mais rápido do que a crosta continental."}, "resposta_correta": "B", "justificativa": "Pela conservação do momento angular em um referencial inercial, o plano de oscilação do pêndulo permanece constante no espaço; para um observador na Terra, o plano parece girar, demonstrando conclusivamente que o chão (a Terra) está rodando sob ele.", "possui_imagem": false},
  {"id": 240, "uid": "CIEN-6-240", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Achatamento Polar e Força Centrífuga", "dificuldade": "Difícil", "enunciado": "Devido à sua rápida rotação em torno do próprio eixo (cerca de 1.670 km/h na linha do Equador), a Terra não é uma esfera geométrica perfeita, mas sim um esferoide oblato (geoide). Essa rotação provoca:", "alternativas": {"A": "Um achatamento no equador e uma dilatação pontiaguda nos polos.", "B": "Um ligeiro achatamento nos polos e uma dilatação (abaulamento) equatorial gerada pela inércia/força centrífuga de rotação, fazendo com que o raio equatorial seja cerca de 21 km maior que o raio polar.", "C": "A transformação contínua de água dos mares em magma subterrâneo.", "D": "A atração de todos os satélites espaciais para a Groenlândia.", "E": "A perda da atmosfera gasosa sobre as florestas tropicais."}, "resposta_correta": "B", "justificativa": "A rotação de um corpo elástico e viscoso em torno de um eixo gera aceleração centrífuga máxima no equador e nula nos polos, produzindo o abaulamento da cintura equatorial e o consequente achatamento polar.", "possui_imagem": false},
  {"id": 241, "uid": "CIEN-6-241", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Declinação Solar e Faixa de Incidência Tropical", "dificuldade": "Difícil", "enunciado": "A declinação solar (δ) varia senoidalmente ao longo do ano entre os limites extremos de +23,5º e -23,5º. Qual é o fundamento astronômico exato que define as posições geográficas dos Trópicos de Câncer e de Capricórnio na superfície terrestre?", "alternativas": {"A": "São as latitudes onde a água do mar ferve durante o verão.", "B": "São as latitudes limite terrestres que correspondem exatamente à inclinação máxima do eixo de rotação da Terra (+23,5º e -23,5º), representando as fronteiras além das quais o Sol NUNCA atinge o zênite (90º) em nenhum dia do ano.", "C": "São as linhas por onde passam os cabos submarinos de internet de fibra óptica.", "D": "São as faixas onde a força da gravidade é exatamente igual a zero.", "E": "São as linhas imaginárias que separam a Terra em placas tectônicas."}, "resposta_correta": "B", "justificativa": "Os trópicos de Câncer (23º 26' N) e Capricórnio (23º 26' S) são rigorosamente definidos pela obliquidade da eclíptica (inclinação do eixo terrestre de ~23,5º). Fora da faixa intertropical (acima de Câncer ou abaixo de Capricórnio), o Sol jamais alcança o zênite astronômico.", "possui_imagem": false},
  {"id": 242, "uid": "CIEN-6-242", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Círculos Polares e Tangência da Luz Solar", "dificuldade": "Difícil", "enunciado": "Os Círculos Polares Ártico e Antártico localizam-se exatamente nas latitudes de 66,5º Norte e 66,5º Sul, respectivamente. A relação matemática entre essa latitude e a inclinação do eixo terrestre (23,5º) é dada por:", "alternativas": {"A": "66,5º é o dobro da inclinação do eixo terrestre.", "B": "66,5º é o ângulo complementar à inclinação do eixo (90º - 23,5º = 66,5º), representando a latitude limite a partir da qual o círculo de iluminação solar tangencia a superfície da Terra nos solstícios.", "C": "66,5º é o ponto em que a temperatura atinge o zero absoluto no inverno.", "D": "66,5º representa a velocidade do som no gelo marinho.", "E": "Não há relação matemática, foi uma escolha arbitrária de navegadores antigos."}, "resposta_correta": "B", "justificativa": "Como a inclinação do eixo é de 23,5º, o círculo de iluminação nos solstícios inclina-se 23,5º em relação aos polos. A latitude limite onde o Sol não se põe (ou não nasce) por pelo menos 24 horas consecutivas é dada pelo complemento angular: 90º - 23,5º = 66,5º.", "possui_imagem": false},
  {"id": 243, "uid": "CIEN-6-243", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "O Princípio de Funcionamento do Gnômon com Estilo Inclinado", "dificuldade": "Difícil", "enunciado": "Em um relógio de sol horizontal de precisão (que marca as horas solares corretas tanto no verão quanto no inverno), a haste de metal (chamada 'estilo' ou gnômon) não deve ser colocada a 90º perpendicular ao chão, mas sim inclinada em relação ao solo. O ângulo de inclinação do estilo deve ser rigorosamente igual a:", "alternativas": {"A": "45º em qualquer lugar do mundo.", "B": "A latitude geográfica do local onde o relógio de sol está instalado, apontando diretamente para o polo celeste.", "C": "A longitude da cidade dividida por 24 horas.", "D": "A temperatura média do ar da cidade no verão.", "E": "Zero graus, ficando deitado sobre o mostrador de pedra."}, "resposta_correta": "B", "justificativa": "Para que a sombra do estilo gire a uma taxa angular constante que não sofra distorção sazonal com a declinação solar ao longo dos meses, o estilo deve ser orientado paralelamente ao próprio eixo de rotação da Terra (estilo gnomônico), o que exige que sua inclinação seja igual à latitude local.", "possui_imagem": false},
  {"id": 244, "uid": "CIEN-6-244", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Fotoperíodo e Fisiologia Vegetal", "dificuldade": "Difícil", "enunciado": "A variação na duração do dia claro (fotoperíodo) provocada pela inclinação do eixo da Terra e pela translação não afeta apenas o clima, mas regula ciclos biológicos fundamentais. Muitas espécies de plantas conseguem florir apenas quando a duração do dia claro ultrapassa um valor crítico (plantas de dia longo) ou quando a noite atinge certa extensão (plantas de dia curto). Esse mecanismo adaptativo é mediado por:", "alternativas": {"A": "Células musculares ciliares nas pétalas das flores.", "B": "Fitocromos (pigmentos vegetais fotorreceptores que monitoram o fotoperíodo através da absorção de luz vermelha e vermelho-distante).", "C": "Neurônios sensitivos localizados nas raízes subterrâneas.", "D": "O congelamento do pólen no outono.", "E": "Átomos de ferro da terra que atraem abelhas."}, "resposta_correta": "B", "justificativa": "O fotoperiodismo vegetal baseia-se no sistema de fitocromos (Pr e Pfr). A duração da noite contínua dita a proporção de fitocromo ativo, sinalizando às plantas o momento fenológico ideal para floração e germinação conforme as estações do ano.", "possui_imagem": false},
  {"id": 245, "uid": "CIEN-6-245", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Velocidade Linear de Rotação em Diferentes Latitudes", "dificuldade": "Difícil", "enunciado": "Embora todas as cidades da Terra tenham a mesma velocidade angular de rotação (completando uma volta de 360º a cada 24 horas), a velocidade LINEAR de rotação (em km/h) varia drasticamente com a latitude. A velocidade linear é máxima na Linha do Equador (~1.670 km/h) e é nula (0 km/h) nos Polos Geográficos. Essa variação ocorre porque:", "alternativas": {"A": "A gravidade no equador atrai os aviões com força centrífuga dupla.", "B": "O raio do paralelo de rotação é máximo no equador (raio da Terra completo) e diminui com o cosseno da latitude até se anular nos polos geográficos (v = ω . R . cos(lat)).", "C": "Os polos da Terra são feitos de gelo denso que freia os átomos continentais.", "D": "O Sol puxa o equador para frente e empurra os polos para trás.", "E": "A velocidade de rotação varia porque o ano bissexto adiciona dias extras."}, "resposta_correta": "B", "justificativa": "A velocidade linear de rotação é v = ω . r. Como o raio do círculo de rotação para uma dada latitude é r = R . cos(latitude), no equador (cos 0º = 1) a distância percorrida em 24 h é a circunferência inteira (~40.075 km); nos polos (cos 90º = 0), o raio é zero e o ponto apenas gira sobre si mesmo.", "possui_imagem": false},
  {"id": 246, "uid": "CIEN-6-246", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Efeito Coriolis e a Rotação Terrestre", "dificuldade": "Difícil", "enunciado": "Massas de ar e correntes marítimas que se deslocam na atmosfera não viajam em linha reta, sofrendo desvio aparente para a direita no Hemisfério Norte e para a esquerda no Hemisfério Sul, gerando a rotação de furacões e ciclones. Esse desvio inercial em um referencial em rotação é denominado:", "alternativas": {"A": "Força de atrito estático.", "B": "Efeito Coriolis (ou aceleração de Coriolis).", "C": "Pressão osmótica atmosférica.", "D": "Efeito estufa polar inverso.", "E": "Atração magnética lunar."}, "resposta_correta": "B", "justificativa": "O efeito Coriolis é uma força inercial aparente observada em corpos em movimento relativo em um referencial não inercial em rotação (a Terra). Ele decorre da conservação do momento angular e da variação da velocidade linear da superfície terrestre em diferentes latitudes.", "possui_imagem": false},
  {"id": 247, "uid": "CIEN-6-247", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Evolução Histórica: Heliocentrismo vs. Geocentrismo", "dificuldade": "Difícil", "enunciado": "Durante séculos, o modelo Geocêntrico (de Ptolomeu), que colocava a Terra imóvel no centro do universo com o Sol e os planetas girando ao seu redor, foi o paradigma dominante. A transição científica para o modelo Heliocêntrico, consolidada pelos trabalhos de Nicolau Copérnico, Galileu Galilei e Johannes Kepler, baseou-se na compreensão de que:", "alternativas": {"A": "A Terra é o centro imóvel e o Sol é apenas uma ilusão de óptica do gnômon.", "B": "A Terra é um planeta que orbita o Sol em conjunto com os outros planetas e que o movimento diário dos astros é aparente, gerado pela própria rotação terrestre.", "C": "O Sol gira em torno da Lua e ambos giram em torno de Marte.", "D": "O universo é estático e as estrelas estão desenhadas em uma cúpula de cristal sólido.", "E": "As estações do ano ocorrem porque a Terra cai no espaço a cada inverno."}, "resposta_correta": "B", "justificativa": "Copérnico propôs matematicamente que o Sol ocupa o centro do sistema planetário e que os movimentos diários aparentes do céu decorrem da rotação da Terra sobre seu eixo, enquanto o ciclo anual das estações decorre da translação orbital terrestre em torno do Sol.", "possui_imagem": false},
  {"id": 248, "uid": "CIEN-6-248", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Refração Atmosférica e o Nascer Antecipado do Sol", "dificuldade": "Difícil", "enunciado": "Ao olhar para o Sol no exato instante em que ele parece tocar a linha do horizonte no amanhecer ou entardecer, os astrônomos sabem que, geometricamente, o disco solar ainda se encontra fisicamente ABAIXO da linha do horizonte astronômico. Esse adiantamento visual de alguns minutos é causado por:", "alternativas": {"A": "A reflexão da luz nas ondas do mar.", "B": "A refração atmosférica, que curva os raios luminosos ao atravessarem camadas de ar com densidades decrescentes da atmosfera terrestre, elevando a imagem aparente do astro.", "C": "A dilatação temporal descrita pela gravidade lunar.", "D": "A dispersão cromática dos cones na retina dos observadores matutinos.", "E": "O calor emitido pela poeira das cidades industriais."}, "resposta_correta": "B", "justificativa": "A atmosfera funciona como um meio com índice de refração continuamente decrescente com a altitude. A luz proveniente do Sol rasante curva-se em direção à normal (refração atmosférica), elevando a imagem aparente do disco solar em cerca de 0,5º no horizonte, fazendo-o ser visível antes do nascer geométrico real.", "possui_imagem": false},
  {"id": 249, "uid": "CIEN-6-249", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Consequências Ecológicas da Inclinação do Eixo da Terra", "dificuldade": "Difícil", "enunciado": "Se o eixo de rotação da Terra NÃO fosse inclinado (isto é, se a inclinação fosse exatamente 0º em relação ao plano da órbita), qual seria a consequência astronômica e climática direta para todo o planeta Terra?", "alternativas": {"A": "O planeta deixaria de girar e haveria apenas noite permanente.", "B": "Não existiriam as quatro estações do ano ao longo dos meses; todos os dias do ano teriam exatamente 12 horas de luz e 12 horas de escuridão em qualquer latitude, com clima e temperatura uniformes ao longo de todo o ano em cada região.", "C": "A Terra congelaria completamente em menos de 48 horas.", "D": "O Sol nasceria no oeste e se poria no leste.", "E": "A Lua se chocaria contra a atmosfera terrestre imediatamente."}, "resposta_correta": "B", "justificativa": "Com inclinação zero (eixo perpendicular à eclíptica), a declinação solar seria permanentemente 0º (condição perene de equinócio). O círculo de iluminação dividiria sempre todos os paralelos ao meio (dias e noites de 12 horas), eliminando as variações sazonais de insolação (sem estações do ano).", "possui_imagem": false},
  {"id": 250, "uid": "CIEN-6-250", "segmento": "Ensino Fundamental II", "disciplina": "Ciências", "serie": "6º Ano", "ano": "6º Ano", "modulo": "Módulo 17: Movimentos da Terra e Gnômon", "tema": "Cálculo da Altura Solar Meridiana nos Solstícios", "dificuldade": "Difícil", "enunciado": "A altura máxima aparente do Sol no horizonte ao meio-dia solar (h) é calculada astronomicamente pela fórmula: h = 90º - |latitude - declinação solar|. Na cidade de São Paulo (latitude arredondada de 23,5º S), qual é a altura solar ao meio-dia no solstício de verão (declinação = -23,5º) e no solstício de inverno (declinação = +23,5º)?", "alternativas": {"A": "Verão: h = 45º; Inverno: h = 0º.", "B": "Verão: h = 90º (Sol a pino no zênite, sem sombra lateral); Inverno: h = 43º (Sol culminando bem mais baixo no céu do Norte, gerando sombras longas).", "C": "Verão: h = 180º; Inverno: h = 90º.", "D": "Verão: h = 0º; Inverno: h = 90º.", "E": "Ambos com h = 60º."}, "resposta_correta": "B", "justificativa": "No solstício de verão de São Paulo (lat = -23,5º, decl = -23,5º): h = 90º - |-23,5 - (-23,5)| = 90º - 0 = 90º (Sol no zênite exato). No solstício de inverno (decl = +23,5º): h = 90º - |-23,5 - 23,5| = 90º - 47º = 43º (o Sol passa a 43º de elevação no quadrante Norte).", "possui_imagem": false}
];
